export const SCENARIO_EN: Record<string, { front: string; back: string; src: string }> = {
  "csa-scenario-001": { front: "ArrayList<Integer> a = new ArrayList<Integer>();\nint[] d = {2, 4, 5, 6, 8};\nfor (int v : d) { a.add(v); }\nfor (int i = 0; i < a.size(); i++) { if (a.get(i) % 2 == 0) { a.remove(i); } }\nWhat is the output of System.out.println(a);, and which loop form makes \"remove all even numbers\" hold?\nA. Output [4, 5, 8]; switching to the remove overload that deletes by element is enough to remove them all\nB. Output [5]; thinks that switching to an enhanced for loop and deleting removes all even numbers\nC. Output [4, 5, 8]; iterating backward from the end while deleting is what removes all even numbers\nD. Output [5]; thinks the original loop already removes all even numbers correctly and needs no change", back: "Answer: C\nExplanation: A after switching to the by-element remove overload the index still advances, so the 4 that shifts left is skipped; B removing inside an enhanced for throws ConcurrentModificationException; D the actual output still contains the even number 8, showing the even numbers are not all removed.\n\nCorrect option: Output [4, 5, 8]; iterating backward from the end while deleting is what removes all even numbers", src: "031ffdad4226" },
  "csa-scenario-002": { front: "static void modify(ArrayList<Integer> p) {\np.add(0, 99);\np = new ArrayList<Integer>();\np.add(7);\n}\nArrayList<Integer> a = new ArrayList<Integer>();\na.add(1);\na.add(2);\nmodify(a);\nSystem.out.println(a);\nA. Output [99, 1, 2]; p and a refer to the same list, so reassigning only changes the local reference\nB. Output [99, 1, 2, 7]; p is always an alias of a, so both add calls write into the same list\nC. Output [1, 2]; thinks that modifying the parameter reference inside the method does not carry back to the caller's list\nD. Output [7, 99, 1, 2]; p = new is the same as clearing a and then inserting 7", back: "Answer: A\nExplanation: B wrongly assumes that p still refers to a after being reassigned; C ignores that p.add(0, 99) has already modified a; D misreads p = new as clearing the original list and then inserting.\n\nCorrect option: Output [99, 1, 2]; p and a refer to the same list, so reassigning only changes the local reference", src: "1d2b7325e9ae" },
  "csa-scenario-003": { front: "int[][] t = {{5, 1}, {2, 7, 3}};\nint s = 0;\nfor (int r = 0; r < t.length; r++) {\nfor (int c = 0; c <= t[r].length; c++) {\ns += t[r][c];\n}\n}\nWhat is the result of running System.out.println(s);?\nA. Outputs 18; the default value 0 read at the out-of-bounds position does not affect the total\nB. Outputs 15; the inner condition is equivalent to iterating both rows using the length of the first row\nC. Compile error; a ragged two-dimensional array initialization is not legal in Java\nD. Throws an out-of-bounds exception at run time; when r=0, c reaches the illegal index 2", back: "Answer: D\nExplanation: A an out-of-bounds access throws an exception directly, so the default value 0 is not read; B the inner condition is c <= t[r].length and does not truncate to the length of the first row; C this initialization of a jagged array is completely legal in Java.\n\nCorrect option: Throws an out-of-bounds exception at run time; when r=0, c reaches the illegal index 2", src: "87dc353a75ce" },
  "csa-scenario-004": { front: "int[][] g = new int[2][2];\nint[] row = g[0];\nrow[0] = 8;\ng[1] = row;\nrow[1] = 9;\nSystem.out.println(g[0][0] + \" \" + g[1][1]);\nA. Output 0 0; assignment between arrays always copies out a new array\nB. Output 8 9; the two rows are the same array, so a change through row is visible in both places\nC. Output 0 9; row is a copied row and is no longer linked to the row g[0]\nD. Output 8 0; g[1] = row copied the contents at that time, and afterwards they do not affect each other", back: "Answer: B\nExplanation: A array assignment does not copy elements, so the two variables refer to the same array; C ignores that int[] row = g[0] assigns a reference; D ignores that after g[1] = row the two rows share the same array.\n\nCorrect option: Output 8 9; the two rows are the same array, so a change through row is visible in both places", src: "1d561b4090c0" },
  "csa-scenario-005": { front: "static void fill(int[] arr) {\nfor (int i = 0; i < arr.length; i++) { arr[i] = arr[i] + 1; }\n}\nstatic void replace(int[] arr) { arr = new int[]{0, 0, 0}; }\nint[] a = {1, 2, 3};\nfill(a);\nreplace(a);\nSystem.out.println(a[0] + \",\" + a[2]);\nA. Output 2,4; fill changed the array, replace only changed the local reference\nB. Output 0,0; thinks the array newly created inside replace was also assigned to the caller's a\nC. Output 1,3; modifications to array elements inside a method do not affect the caller's array\nD. Compile error; method parameters are implicitly declared final, so reassignment is not allowed", back: "Answer: A\nExplanation: B replace only changed the parameter reference and did not write back to a; C fill modifies elements through the reference, so it does affect the caller's array; D Java method parameters are not final, so reassignment is completely legal.\n\nCorrect option: Output 2,4; fill changed the array, replace only changed the local reference", src: "d99c5278f3d9" },
  "csa-scenario-006": { front: "int[] a = {3, 1, 4};\nfor (int x : a) { x = x * 2; }\nThe student wanted to double every element. Which choice is correct about the array's final contents and the right fix?\nA. {6, 2, 8}; thinks x is an alias of the array element, so everything is doubled when the loop ends\nB. {3, 1, 4}; should be changed to a[x] = x * 2, because x was treated as the index of the element\nC. Compile error; thinks the loop variable of an enhanced for cannot be reassigned inside the loop body\nD. {3, 1, 4}; x is only a copy, so a[i] = a[i] * 2 must be used instead", back: "Answer: D\nExplanation: A the x of an enhanced for has no referential relationship with the array element; B x is the element value, not the index, so a[x] goes out of bounds; C this code compiles normally, it simply does not change the array.\n\nCorrect option: {3, 1, 4}; x is only a copy, so a[i] = a[i] * 2 must be used instead", src: "9f19104504f3" },
  "csa-scenario-007": { front: "ArrayList<String> w = new ArrayList<String>();\nw.add(\"a\");\nw.add(\"bb\");\nw.add(\"ccc\");\nArrayList<String> r = new ArrayList<String>();\nfor (String s : w) { if (s.length() > 1) { r.add(0, s); } }\nSystem.out.println(r);\nA. [bb, ccc]; treats add(0, s) as appending the element at the end of the list\nB. [ccc, bb]; keeps only the strings whose length is greater than 1, and inserts each one at index 0\nC. [ccc]; treats add(0, s) as replacing the element at index 0\nD. Throws an out-of-bounds exception; thinks inserting at index 0 in an empty list is an illegal operation", back: "Answer: B\nExplanation: A add(0, s) inserts rather than appends at the end; C add is not set and does not replace an existing element; D inserting at index 0 in an empty list is legal and does not throw an exception.\n\nCorrect option: [ccc, bb]; keeps only the strings whose length is greater than 1, and inserts each one at index 0", src: "55fd89dd847a" },
  "csa-scenario-008": { front: "class Animal { public String speak() { return \"?\"; } }\nclass Dog extends Animal { public String speak() { return \"woof\"; } public String fetch() { return \"ball\"; } }\nAnimal a = new Dog();\nDog d = (Dog) a;\nSystem.out.println(a.speak() + d.fetch());\nA. ?ball; thinks the declared type of variable a determines which version of speak is finally called\nB. Compile error; thinks a superclass reference must be downcast before the speak method can be called\nC. woofball; speak is bound according to the run-time object, and fetch can be called after the cast\nD. Throws a type-cast exception at run time; thinks casting a superclass reference to a subclass must fail", back: "Answer: C\nExplanation: A an overridden method selects its version by run-time type, independent of the declared type; B a superclass reference can call speak directly, without casting first; D the actual object is a Dog, so the downcast does not fail.\n\nCorrect option: woofball; speak is bound according to the run-time object, and fetch can be called after the cast", src: "8ea2aead9ea2" },
  "csa-scenario-009": { front: "class Shape { public double area() { return 0; } public String name() { return \"shape\"; } }\nclass Square extends Shape { public double area() { return 4; } }\nclass Circle extends Shape { public double area() { return 3; } public String name() { return \"circle\"; } }\nShape[] s = { new Square(), new Circle(), new Shape() };\ndouble t = 0;\nfor (Shape p : s) { t += p.area(); }\nSystem.out.println(t + \" \" + s[1].name());\nA. 7.0 circle; area is called according to the run-time object, and name is overridden too\nB. 0.0 circle; a Shape variable only calls the area implementation defined in the superclass\nC. 7.0 shape; name was not overridden, so the string defined in the superclass is printed\nD. Throws a type-cast exception at run time; because iterating a heterogeneous array always requires downcasting", back: "Answer: A\nExplanation: B dynamic binding calls the area overridden in the subclass; C name has already been overridden in Circle; D calling an overridden method through a superclass reference does not require downcasting.\n\nCorrect option: 7.0 circle; area is called according to the run-time object, and name is overridden too", src: "2893e0536062" },
  "csa-scenario-010": { front: "public class Ticket {\nprivate static int sold = 0;\nprivate int id;\npublic Ticket() { sold++; id = sold; }\npublic int getId() { return id; }\npublic static int getSold() { return sold; }\n}\nTicket a = new Ticket();\nTicket b = new Ticket();\nSystem.out.println(a.getId() + \" \" + b.getId() + \" \" + Ticket.getSold());\nA. 0 1 2; id = sold executes first and then sold++, so the numbering starts at 0\nB. 2 2 2; thinks id is also declared static, so the two objects share the same number\nC. Compile error; thinks the class's static field sold cannot be accessed inside a constructor body\nD. 1 2 2; sold is shared by all objects, and each construction increments it before assigning it to id", back: "Answer: D\nExplanation: A the code increments first and then assigns, so the numbering starts at 1; B id is an instance field, and each object has its own copy; C accessing a static field inside a constructor is completely legal.\n\nCorrect option: 1 2 2; sold is shared by all objects, and each construction increments it before assigning it to id", src: "d525993420b0" },
  "csa-scenario-011": { front: "class P {\npublic P() { System.out.print(\"P\"); }\npublic P(int x) { System.out.print(\"P\" + x); }\n}\nclass C extends P {\npublic C() { super(2); System.out.print(\"C\"); }\n}\nnew C();\nA. PC; because super(2) finds no match and falls back to calling the superclass no-argument constructor\nB. P2C; the superclass constructor with an argument runs first and prints P2, then the subclass body prints C\nC. CP2; thinks the subclass constructor body finishes first, and then the superclass constructor runs\nD. Compile error; thinks a subclass constructor can only call the no-argument constructor through super()", back: "Answer: B\nExplanation: A an explicit super(2) can match the superclass constructor with a parameter and does not fall back to the no-argument version; C the superclass constructor always executes before the subclass constructor body; D a subclass constructor may call the superclass constructor that takes an argument.\n\nCorrect option: P2C; the superclass constructor with an argument runs first and prints P2, then the subclass body prints C", src: "778a7e17061a" },
  "csa-scenario-012": { front: "abstract class Food {\npublic abstract double cost();\n}\nclass Pizza extends Food {\nprivate int slices;\npublic Pizza(int n) { slices = n; }\npublic double cost(int n) { return n * 3.0; }\n}\nFood f = new Pizza(4);\nSystem.out.println(f.cost());\nA. Throws AbstractMethodError at run time; f.cost() finds no implementation\nB. Compile error; thinks the error is at the call site, and f must first be cast to Pizza\nC. Compile error; cost(int) is an overload, not an override, and should be changed to a no-argument cost()\nD. No error; thinks the same method name counts as implementing the abstract method, and 12.0 is printed", back: "Answer: C\nExplanation: A an unimplemented abstract method is a compile-time error and is not deferred to run time; B the error is in the class declaration of Pizza, and a cast cannot solve it; D the same method name is not an override, and a different parameter list is only an overload.\n\nCorrect option: Compile error; cost(int) is an overload, not an override, and should be changed to a no-argument cost()", src: "0bd156a5090f" },
  "csa-scenario-013": { front: "public static int f(int n) {\nif (n <= 1) { return n; }\nreturn f(n - 1) + f(n - 2);\n}\nAfter calling f(4), what are the return value and the total number of times f is called (including the initial call)?\nA. Return value 3, f is called 9 times in total, including the initial f(4) call\nB. Return value 5, f is called 9 times in total, because n <= 1 is treated as always returning 1\nC. Return value 3, f is called 8 times in total, because the initial call is not counted in the total\nD. Return value 3, f is called 7 times in total, because two f(0) calls were missed", back: "Answer: A\nExplanation: B the return values of the base case are not all 1, since f(0) returns 0; C the initial f(4) call must also be counted in the total; D f(0) really is called twice and must not be missed.\n\nCorrect option: Return value 3, f is called 9 times in total, including the initial f(4) call", src: "9c4e0862780b" },
  "csa-scenario-014": { front: "public static String g(String s) {\nif (s.length() <= 1) { return s; }\nreturn g(s.substring(1)) + s.charAt(0);\n}\nWhat is the return value of g(\"abc\")?\nA. bca; only the outermost concatenation is done, without continuing to recurse on the substring\nB. abc; the concatenation order is reversed, written as charAt(0) + g(s)\nC. cba; each level first reverses the remaining substring and then appends the first character to the end of the result\nD. Throws an out-of-bounds exception; thinks calling charAt(0) on the empty string also fails out of bounds", back: "Answer: C\nExplanation: A the code keeps recursing on the substring and does not do only the outermost step; B the concatenation order puts the recursive result first, not charAt(0); D the base case catches the empty string, so charAt(0) is never called.\n\nCorrect option: cba; each level first reverses the remaining substring and then appends the first character to the end of the result", src: "e3deff2c90f4" },
  "csa-scenario-015": { front: "public static int h(int n) {\nif (n == 0) { return 0; }\nreturn n + h(n - 2);\n}\nWhat is the result of h(5)?\nA. Returns 9; thinks the termination condition is automatically satisfied when n decreases to 1\nB. Throws a stack overflow error; an odd n skips 0, so the recursion never terminates\nC. Returns 15; ignores the step of 2 and treats h as computing the sum of consecutive integers from 1 to 5\nD. Returns 8; thinks the last remaining h(1) is not included in the result and only 5 and 3 are added", back: "Answer: B\nExplanation: A n == 0 is the only termination condition, and an odd sequence never reaches 0; C the step is 2, so it does not add 1 through 5 one by one; D the recursion never ends at all, so there is no remaining h(1) result.\n\nCorrect option: Throws a stack overflow error; an odd n skips 0, so the recursion never terminates", src: "ea7173377278" },
  "csa-scenario-016": { front: "public static int m(int[] a, int i) {\nif (i == a.length) { return 0; }\nint rest = m(a, i + 1);\nreturn a[i] > rest ? a[i] : rest;\n}\nint[] d = {3, 9, 4};\nint r = m(d, 0); // what is the value of r?\nA. 0; thinks the ternary expression finally returns the value of the base case\nB. 3; thinks there is no comparison and the value of the first element a[0] is returned directly\nC. 4; thinks the recursion always returns the value of the array's last element\nD. 9; each level compares the current element with the maximum of the right-hand subproblem and returns it", back: "Answer: D\nExplanation: A the base case only serves as the initial comparison value, and the maximum is what is finally returned; B every level performs a comparison and does not return a[0] directly; C the return value is determined by the comparison result and is unrelated to the last element.\n\nCorrect option: 9; each level compares the current element with the maximum of the right-hand subproblem and returns it", src: "80f85a167139" },
  "csa-scenario-017": { front: "public static void p(int n) {\nif (n == 0) { return; }\np(n - 1);\nSystem.out.print(n);\np(n - 1);\n}\nWhat is the output of p(2);?\nA. 211; places the print statement before the two recursive calls, printing first and then recursing\nB. 121; first goes through the left recursion down to the base case, then prints n, then goes through the right recursion\nC. 12; omits the last line's p(n - 1) call and goes through only the left half of the recursion\nD. 112; places the print statement after the two recursive calls, printing only after both recursions finish", back: "Answer: B\nExplanation: A writing the print before the recursion would output 2 first; C omitting the last p(n - 1) would output one fewer 1; D writing the print after the two recursions would give 112.\n\nCorrect option: 121; first goes through the left recursion down to the base case, then prints n, then goes through the right recursion", src: "95cc9e4ec560" },
  "csa-scenario-018": { front: "int[] a = {5, 3, 8, 1, 9};\nfor (int i = 0; i < 2; i++) {\nint min = i;\nfor (int j = i + 1; j < a.length; j++) { if (a[j] < a[min]) { min = j; } }\nint t = a[i]; a[i] = a[min]; a[min] = t;\n}\nWhat are the contents of the array after the loop ends, and how many more swaps are needed to make it fully ascending?\nA. {1, 3, 8, 5, 9}, 1 more swap needed; when i=2, 5 is swapped into index 2\nB. {1, 3, 8, 5, 9}, 2 more swaps needed; thinks both remaining passes necessarily require a swap\nC. {1, 3, 5, 8, 9}, 0 more swaps needed; thinks two passes have already put the first three positions in order\nD. {1, 1, 8, 1, 9}, 1 more swap needed; thinks assigning alone moves the minimum to the front", back: "Answer: A\nExplanation: B among the two remaining passes only i=2 requires a swap; C two passes fix only the first two positions and the array is not sorted; D the code uses a three-variable swap and does not overwrite element 5 with an assignment.\n\nCorrect option: {1, 3, 8, 5, 9}, 1 more swap needed; when i=2, 5 is swapped into index 2", src: "c42830a1e4b7" },
  "csa-scenario-019": { front: "int[] a = {2, 4, 6, 8, 10, 12, 14};\n// binary search for 12: lo=0, hi=a.length-1, mid=(lo+hi)/2,\n// each time a[mid] is compared with the target, and it stops on a hit\nWhat are the successive mid indices and the total number of comparisons?\nA. 3, 4, 5, 3 comparisons in total; lo is written as mid instead of mid + 1, adding an extra pass\nB. 3, 5, 3 comparisons in total; after hitting 12, one more comparison with an adjacent element is made for confirmation\nC. 4, 6, 2 comparisons in total; indices are numbered starting from 1, and (1 + 7) / 2 gives 4\nD. 3, 5, 2 comparisons in total; first a[3]=8 is compared and then a[5]=12, hitting on the second comparison", back: "Answer: D\nExplanation: A writing lo as mid adds an extra comparison pass and produces an extra mid of 4; B the search stops immediately on a hit, so no adjacent element needs to be compared; C array indices start at 0, so mid cannot be 4 or 6.\n\nCorrect option: 3, 5, 2 comparisons in total; first a[3]=8 is compared and then a[5]=12, hitting on the second comparison", src: "08fbb5a6eb50" },
  "csa-scenario-020": { front: "int[] a = {4, 2, 7, 1};\n// insertion sort: the outer i goes from 1 to a.length-1, inserting a[i] into the sorted prefix,\n// and each element shifted one position to the right counts as 1 right shift\nWhat are the contents of the array after the i = 2 pass finishes, and the total number of right shifts for the whole sort?\nA. {1, 2, 4, 7}, 4 right shifts in total; thinks the array is completely sorted after i=2 finishes\nB. {2, 4, 1, 7}, 4 right shifts in total; thinks each pass swaps positions with the adjacent element on the right\nC. {2, 4, 7, 1}, 4 right shifts in total; when i=2, 7 is already in place and only 1 needs to move\nD. {2, 4, 7, 1}, 5 right shifts in total; treats the number of comparisons as the number of right shifts (1+1+3=5), confusing comparisons with moves", back: "Answer: C\nExplanation: A when i=2 finishes, 1 has not been inserted yet and the array is not sorted; B insertion sort shifts elements right to make room, it does not swap adjacent elements; D the number of right shifts is 1+0+3=4, and 5 is the number of comparisons.\n\nCorrect option: {2, 4, 7, 1}, 4 right shifts in total; when i=2, 7 is already in place and only 1 needs to move", src: "ccbd7ab306ee" },
  "csa-scenario-021": { front: "public static int count(int[] a, int t) {\nint c = 0;\nfor (int i = 0; i < a.length; i++) {\nif (a[i] == t) { c++; return c; }\n}\nreturn c;\n}\nint[] d = {3, 5, 3, 5};\nWhat is the return value of count(d, 3), and what is the correct fix?\nA. Returns 1; this does not match the expected 2, so return c should be moved outside the loop\nB. Returns 2, matching the expectation; the loop keeps comparing later elements and accumulating the count\nC. Compile error; thinks there is an execution path with no return, so the method is missing a return value\nD. Returns 1; c++ should be changed to c = c + 1 so that the increment takes effect earlier", back: "Answer: A\nExplanation: B the return is written inside the loop body, so the method ends on the first hit; C the method already has a return at the end and compiles; D the c++ increment does take effect, and the real problem is the early return.\n\nCorrect option: Returns 1; this does not match the expected 2, so return c should be moved outside the loop", src: "d788809d63d2" },
  "csa-scenario-022": { front: "int a = 7, b = 2;\ndouble r = a / b;\ndouble s = (double) a / b;\nSystem.out.println(r + \" \" + s);\nA. 3.5 3.5; thinks assigning the result to a double makes the right-hand side evaluate as double first\nB. 3.0 3.5; the first line does integer division first and then widens, and the second line yields a decimal after the cast\nC. 3 3.5; thinks a double variable prints without a decimal point when it stores an integer value\nD. 3.5 3.0; reverses where (double) applies, thinking only the first line is promoted", back: "Answer: B\nExplanation: A the type of the assignment target does not affect the integer division on the right-hand side; C a double variable still prints a decimal point when it holds an integer value; D the promotion happens only on the second line, and the first line is still integer division.\n\nCorrect option: 3.0 3.5; the first line does integer division first and then widens, and the second line yields a decimal after the cast", src: "6b3e2d0a86d8" },
  "csa-scenario-023": { front: "char c = 'A';\nint k = c + 1;\nchar d = (char) k;\nSystem.out.println(k + \" \" + d);\nA. 66 A; thinks the (char) narrowing conversion does not change the character and d is still 'A'\nB. 66 66; thinks a char variable displays the numeric code when printed with println\nC. 66 B; 'A' is encoded as 65, and after adding 1 and converting back to char it is B\nD. Compile error; thinks a char must first be explicitly converted to int before arithmetic with an int", back: "Answer: C\nExplanation: A the (char) cast really does convert 66 to the character B; B printing a char variable with println outputs the character itself; D mixed arithmetic between char and int promotes automatically and needs no explicit conversion.\n\nCorrect option: 66 B; 'A' is encoded as 65, and after adding 1 and converting back to char it is B", src: "a2918b98c64e" },
  "csa-scenario-024": { front: "int i = 0;\nboolean b = (i++ > 0) && (i++ > 1);\nSystem.out.println(i + \" \" + b);\nA. 2 false; thinks both sides of && are evaluated and both increments execute\nB. 2 true; treats the postfix i++ as the prefix ++i, so both conditions hold\nC. 0 false; thinks the increments inside do not take effect when the whole boolean expression fails\nD. 1 false; the left side is false and short-circuits, so the second increment no longer executes", back: "Answer: D\nExplanation: A when the left side of && is false the right side is not evaluated at all; B i++ compares with the old value 0 first, so the left side is false; C the i++ on the left has already executed, and i does not return to 0.\n\nCorrect option: 1 false; the left side is false and short-circuits, so the second increment no longer executes", src: "bdc1c8238489" },
  "csa-scenario-025": { front: "int i = 0, sum = 0;\nwhile (i < 5) {\ni++;\nif (i % 2 == 0) { continue; }\nsum += i;\n}\nSystem.out.println(sum + \" \" + i);\nA. 9 5; only the odd numbers 1, 3, 5 are accumulated, and the loop exits after i reaches 5\nB. 15 5; ignores the if and continue and accumulates all of 1 through 5\nC. 1 2; treats continue as break and exits the loop on an even number\nD. 6 5; reverses the modulus condition and adds only the even numbers 2 and 4", back: "Answer: A\nExplanation: B continue skips the even numbers, it does not add all of 1 through 5; C continue skips only the current iteration and does not end the loop; D the condition skips even numbers, so the odd numbers are accumulated.\n\nCorrect option: 9 5; only the odd numbers 1, 3, 5 are accumulated, and the loop exits after i reaches 5", src: "2c114ca8e325" },
  "csa-scenario-026": { front: "int[] d = {5, 3, 8, 1};\nint s = 0;\nfor (int i = 0; i &lt; d.length - 1; i++) {\n  s += d[i + 1] - d[i];\n}\nWhat is the output of System.out.println(s);?\nA. Output -4; the accumulated adjacent differences leave only the last element minus the first element\nB. Output 3; the difference of the last pair of adjacent elements is not accumulated\nC. Output 14; the difference of every pair of adjacent elements is taken as an absolute value\nD. Output 28; mistakes subtracting adjacent elements for adding adjacent elements", back: "Answer: A\nExplanation: B the loop bound is d.length - 1, so all three pairs of adjacent elements take part; C the code does not take an absolute value; D the expression subtracts adjacent elements, it does not add them.\n\nCorrect option: Output -4; the accumulated adjacent differences leave only the last element minus the first element", src: "14e7cb6fba9e" },
  "csa-scenario-027": { front: "int[][] m = {{2, 5, 1}, {7, 3, 6}, {4, 8, 9}};\nint s = 0;\nfor (int i = 0; i &lt; m.length; i++) { s += m[i][i]; }\nWhat is the value of System.out.println(s);, and what should the inner index be changed to in order to find the sum of the anti-diagonal elements?\nA. 24; the inner index should be written as m.length - 1 - i\nB. 14; the inner index should be written as m.length - i to find the sum\nC. 14; the inner index should be written as m.length - 1 - i\nD. 14; the inner index needs no change, m[i][i] is already the anti-diagonal", back: "Answer: C\nExplanation: A the sum of the main diagonal is 2 + 3 + 9 = 14, not 24; B when the inner index is written as m.length - i, i = 0 accesses m[0][3] and goes out of bounds; D m[i][i] takes the main diagonal, not the anti-diagonal.\n\nCorrect option: 14; the inner index should be written as m.length - 1 - i", src: "96307f188b89" },
  "csa-scenario-028": { front: "ArrayList&lt;String&gt; list = new ArrayList&lt;String&gt;();\nlist.add(\"apple\");\nlist.add(\"grape\");\nlist.add(\"cherry\");\nlist.add(\"date\");\nfor (int i = 0; i &lt; list.size(); i++) {\n  if (list.get(i).length() == 5) { list.remove(i); }\n}\nWhat is the output of System.out.println(list);, and what is the correct fix?\nA. Output [cherry, date]; thinks the loop removes every string whose length equals 5\nB. Output [grape, cherry, date]; should be changed to iterate backward from the end, avoiding skipping the elements that shift left\nC. Throws an out-of-bounds exception; thinks that after an element is removed size becomes smaller, so a later get(i) is sure to go out of bounds\nD. Output [grape, cherry]; thinks remove(i) also deletes the element right after the current one", back: "Answer: B\nExplanation: A after apple is removed grape shifts left to index 0 and is skipped, so they are not all removed; C the loop ends normally when i equals size and does not go out of bounds; D remove(i) deletes only one element and does not delete the next one along with it.\n\nCorrect option: Output [grape, cherry, date]; should be changed to iterate backward from the end, avoiding skipping the elements that shift left", src: "4f3637beba1c" },
  "csa-scenario-029": { front: "ArrayList&lt;Integer&gt; n = new ArrayList&lt;Integer&gt;();\nn.add(4);\nn.add(7);\nn.add(4);\nn.add(9);\nn.remove(4);\nWhat is the result of running System.out.println(n);?\nA. Throws IndexOutOfBoundsException; remove(4) goes out of bounds under the index overload\nB. Output [7, 4, 9]; remove(4) deletes the first 4 in the list by value, and the elements after it shift left one by one\nC. Output [4, 7, 4]; remove(4) deletes the element 9 at the end of the list, and the positions of the other elements do not change\nD. Compile error; thinks an int argument makes the two overloads of remove ambiguous", back: "Answer: A\nExplanation: B the argument of remove(4) is an int, so it takes the index overload and the bounds are checked first, and it does not delete by value; C the out-of-bounds exception is thrown before the removal action, so it never gets to deleting the 9 at the end; D the call is legal, an int argument matches remove(int) exactly, and there is no ambiguity.\n\nCorrect option: Throws IndexOutOfBoundsException; remove(4) goes out of bounds under the index overload", src: "ef9aaef4dafa" },
  "csa-scenario-030": { front: "ArrayList&lt;String&gt; t = new ArrayList&lt;String&gt;();\nt.add(\"a\");\nt.add(\"b\");\nt.add(\"c\");\nfor (String s : t) {\n  if (s.equals(\"a\")) { t.remove(s); }\n}\nWhat is the result of running System.out.println(t.size());?\nA. Output 2; after a is removed the iterator happens to reach the end, the loop ends normally, and the list keeps only b and c\nB. Throws IndexOutOfBoundsException; the iterator accesses by index internally, so the index goes out of bounds after the removal\nC. Output 3; the remove call inside the enhanced for does not really change the list, so size is still 3\nD. Throws ConcurrentModificationException; the iterator detects a structural modification", back: "Answer: D\nExplanation: A after a is removed the iterator still has to take another element, so an exception is thrown at once and the loop cannot end normally; B the list has only 3 elements and the iterator does not access by index, so it does not go out of bounds; C remove really does change the structure of the list.\n\nCorrect option: Throws ConcurrentModificationException; the iterator detects a structural modification", src: "db8a387a0430" },
  "csa-scenario-031": { front: "class Box { int v; Box(int k) { v = k; } }\nBox[] bs = { new Box(1), new Box(2), new Box(3) };\nfor (Box b : bs) { b.v = b.v * 2; }\nfor (Box b : bs) { b = new Box(b.v + 1); }\nWhat is the output of System.out.println(bs[0].v + \" \" + bs[2].v);?\nA. Output 1 3; thinks neither loop changes the object fields stored in the array\nB. Output 1 7; thinks an assignment to b.v changes only a copy, and only assigning the whole variable writes back to the element\nC. Output 2 6; changing a field acts on the shared object, while reassigning the loop variable changes only a copy\nD. Output 3 7; thinks the new objects created in the second loop are also written back to the array", back: "Answer: C\nExplanation: A the first loop really does change the fields of the shared objects, and bs[0].v is 2; B it is exactly the opposite, the assignment to b.v works while assigning the whole variable does not; D the new objects in the second loop are assigned only to a local variable and are not written back into the array, so bs[2].v is still 6.\n\nCorrect option: Output 2 6; changing a field acts on the shared object, while reassigning the loop variable changes only a copy", src: "c058aafbaa28" },
  "csa-scenario-032": { front: "String s = \"Banana\";\nString t = s.substring(1, 4);\nString u = t.toUpperCase().replace(\"A\", \"o\");\nWhat is the output of System.out.println(s.length() + \" \" + t + \" \" + u);?\nA. Output 6 anan oNo; the character at the second argument of substring is counted as well\nB. Output 6 ana oNo; substring excludes the end index, and replace replaces every match\nC. Output 6 ana ANo; replace replaces only the first occurrence of the character in the string\nD. Output 3 ana oNo; substring changes s in place, so length() gives 3", back: "Answer: B\nExplanation: A substring(1, 4) does not include index 4, so the second n is not taken; C replace replaces every matching character and does not change only the first occurrence; D String is immutable, substring does not change s, and length() is still 6.\n\nCorrect option: Output 6 ana oNo; substring excludes the end index, and replace replaces every match", src: "ea0e65639e6a" },
  "csa-scenario-033": { front: "ArrayList&lt;Integer&gt; v = new ArrayList&lt;Integer&gt;();\nv.add(10);\nv.add(null);\nv.add(20);\nint total = 0;\nfor (int i = 0; i &lt; v.size(); i++) { total += v.get(i); }\nWhat is the result of running System.out.println(total);?\nA. Throws NullPointerException; the null element fails during automatic unboxing\nB. Output 30; thinks the null in the list is treated as 0 when it takes part in arithmetic\nC. Throws ClassCastException; the cast fails when the element holding null is read\nD. Compile error; the add method of ArrayList&lt;Integer&gt; does not accept null", back: "Answer: A\nExplanation: B null does not become 0 in arithmetic, the automatic unboxing fails instead; C an unboxing failure throws NullPointerException and has nothing to do with a type conversion; D add(null) compiles, since null is a legal Integer reference value.\n\nCorrect option: Throws NullPointerException; the null element fails during automatic unboxing", src: "98d0507aa2d3" },
  "csa-scenario-034": { front: "public class Lamp {\n  private static int count = 0;\n  private boolean on = false;\n  public Lamp() { count++; }\n  public static void report() { System.out.println(count + \" \" + on); }\n}\nWhich of the following is correct about whether this class compiles?\nA. It compiles and prints 0 false; a static method reads the default value of the field\nB. Compile error; accessing the static field count inside a constructor body is not legal\nC. Compile error; the count++ written inside the constructor is not legal for a static field\nD. Compile error; the static method report cannot refer directly to the instance field on", back: "Answer: D\nExplanation: A a static method cannot refer to the instance field on, so compilation fails; B accessing a static field inside a constructor is completely legal; C a static field can of course be incremented, so that compile error does not hold.\n\nCorrect option: Compile error; the static method report cannot refer directly to the instance field on", src: "f89b58557b17" },
  "csa-scenario-035": { front: "public class Point {\n  private int x;\n  public Point(int x) { x = x; }\n  public void shift(int x) { this.x = this.x + x; }\n  public int getX() { return x; }\n}\nPoint p = new Point(5);\np.shift(3);\nWhat is the output of System.out.println(p.getX());?\nA. Output 8; the constructor's x = x writes 5 into the field, so it is 8 after shift\nB. Output 3; the x = x in the constructor assigns only to the parameter, so the field is still its initial value 0\nC. Compile error; the constructor contains x = x, which the compiler reports as an uninitialized variable\nD. Output 0; thinks both assignments to x act only on the parameter, so the field is always 0", back: "Answer: B\nExplanation: A the x = x in the constructor assigns only to the parameter itself, and the field is not written as 5; C a parameter with the same name as a field is perfectly legal, and x = x is not an error; D the constructor's x = x assigns only to the parameter and the field stays 0, so shift leaves it at 3 and the field is not always 0; the premise that the constructor writes the field as 5 is itself wrong.\n\nCorrect option: Output 3; the x = x in the constructor assigns only to the parameter, so the field is still its initial value 0", src: "2a9f85f50cf3" },
  "csa-scenario-036": { front: "public class Circle {\n  private double r;\n  public Circle() { r = 1; }\n  public Circle(double d) { r = d; }\n  public Circle(int n) { r = n + 1; }\n  public double area() { return r * r; }\n}\nCircle c = new Circle(2);\nCircle d = new Circle(2.0);\nWhat is the output of System.out.println(c.area() + \" \" + d.area());?\nA. 4.0 4.0; thinks the argument 2 is first widened to double, so both objects use the double constructor\nB. 9.0 9.0; the argument 2.0 is first truncated to int, so both objects use the int constructor\nC. 9.0 4.0; the int literal matches the int constructor, and 2.0 uses the double constructor\nD. Compile error; new Circle(2) is ambiguous between the int and double overloads", back: "Answer: C\nExplanation: A an int argument is not first widened to double, and 2 matches the int constructor exactly; B a double argument is not narrowed and truncated, and 2.0 uses the double constructor; D each of the two candidates matches exactly, so there is no ambiguity.\n\nCorrect option: 9.0 4.0; the int literal matches the int constructor, and 2.0 uses the double constructor", src: "2dbf4f1260f2" },
  "csa-scenario-037": { front: "class A {\n  public A() { System.out.print(\"A\"); }\n  public A(int n) { System.out.print(\"A\" + n); }\n}\nclass B extends A {\n  public B() { this(3); System.out.print(\"B\"); }\n  public B(int n) { super(n + 1); System.out.print(\"b\" + n); }\n}\nWhat is the output of new B();?\nA. A4b3B; this(3) enters the constructor with a parameter, and super(4) prints A4 first\nB. A3b3B; treats super(n + 1) as super(n) and prints A3 first\nC. b3A4B; thinks the subclass constructor body executes first and the superclass constructor runs afterward\nD. A4B; thinks this(3) only switches constructors and does not execute the body of the constructor it calls", back: "Answer: A\nExplanation: B super(n + 1) passes 4, so what is printed first is A4; C the superclass constructor always executes before the subclass constructor body; D this(3) does execute the body of the constructor it calls in full, so b3 is certainly printed.\n\nCorrect option: A4b3B; this(3) enters the constructor with a parameter, and super(4) prints A4 first", src: "a93cf7f2b46a" },
  "csa-scenario-038": { front: "class Base { public String tag() { return \"base\"; } }\nclass Sub extends Base {\n  public String tag() { return \"sub\"; }\n  public String tag(int n) { return \"sub\" + n; }\n}\nBase r = new Sub();\nSystem.out.println(r.tag());\nSystem.out.println(r.tag(1));\nWhat is the result of running this code?\nA. Outputs sub and then sub1; thinks the run-time object is a Sub, so both calls can bind\nB. Compile error; thinks assigning a Sub object to a Base variable requires an explicit downcast first\nC. It compiles, but throws NoSuchMethodError at run time; tag(int) cannot be found\nD. Compile error; the declared type Base has no tag(int), and overloads are resolved by declared type", back: "Answer: D\nExplanation: A compilation already fails, so the program cannot run; B an upcast does not require an explicit conversion, and assigning a Sub to a Base variable is legal; C overloads are resolved at compile time by declared type, so there is no run-time NoSuchMethodError.\n\nCorrect option: Compile error; the declared type Base has no tag(int), and overloads are resolved by declared type", src: "8487d818e7d7" },
  "csa-scenario-039": { front: "class P { public String who() { return \"P\"; } }\nclass Q extends P {\n  public String who() { return \"Q\" + super.who(); }\n}\nP[] a = { new Q(), new P(), new Q() };\nString out = \"\";\nfor (P p : a) { out += p.who() + \",\"; }\nWhat is the output of System.out.println(out);?\nA. P,P,P,; thinks that once super.who() appears inside who, the whole call goes back to the superclass version\nB. QP,P,QP,; Q concatenates super.who() first, and the elements are dispatched by run-time type\nC. Q,P,Q,; super.who() returns the empty string, so only the Q concatenated by the subclass remains\nD. QP,QP,QP,; treats every element of the array as a Q, ignoring new P()", back: "Answer: B\nExplanation: A super.who() affects only that one call inside Q and does not change the dispatch target of the whole call; C super.who() returns \"P\" rather than the empty string; D the second element is new P(), so the superclass version is called.\n\nCorrect option: QP,P,QP,; Q concatenates super.who() first, and the elements are dispatched by run-time type", src: "4263e18cd9c5" },
  "csa-scenario-040": { front: "interface Moveable { void move(); }\nabstract class Machine implements Moveable {\n  public void start() { System.out.print(\"start \"); }\n  public abstract void move();\n}\nclass Fan extends Machine {\n  public void move() { System.out.print(\"spin\"); }\n}\nMachine m = new Fan();\nm.start();\nm.move(); What is the result of running this code?\nA. Compile error; an abstract class cannot implement an interface, it can only extend a concrete class\nB. Compile error; thinks Fan must also override the start method for the inheritance chain to be complete\nC. Output start spin; an abstract class may leave the interface method for Fan to implement\nD. Output start and then throws AbstractMethodError; a superclass reference cannot find the implementation", back: "Answer: C\nExplanation: A an abstract class can implement an interface and leave the interface method as an abstract method; B Fan only has to implement the abstract method move, since start already has an implementation; D Fan provides an implementation of move, so AbstractMethodError is not thrown.\n\nCorrect option: Output start spin; an abstract class may leave the interface method for Fan to implement", src: "2e48e91d06aa" },
  "csa-scenario-041": { front: "public static int sum(int n) {\n  if (n == 0) { return 0; }\n  return n + sum(n - 3);\n}\nWhat is the result of running System.out.println(sum(7));?\nA. Throws StackOverflowError; n decreases by 3 each time and skips 0, so the recursion does not terminate\nB. Output 12; thinks that when n decreases to a negative number it is equivalent to satisfying n == 0, so the three numbers 7, 4, and 1 are added\nC. Output 11; thinks the base case takes effect once n is less than 3, so the final 1 is no longer counted\nD. Output 28; mistakes the step of 3 for 1, so all the integers from 1 to 7 are added", back: "Answer: A\nExplanation: B a negative number is not equal to 0, the base case never holds, and 12 is not obtained; C for the same reason, the recursion does not stop at a small n; D the step is 3, so after 7 come 4 and then 1, and it does not add up all the integers from 1 to 7.\n\nCorrect option: Throws StackOverflowError; n decreases by 3 each time and skips 0, so the recursion does not terminate", src: "1b5d97d2b5ce" },
  "csa-scenario-042": { front: "public static int f(int n) {\n  if (n &lt;= 0) { return 0; }\n  return n + f(n / 2);\n}\nWhat are the return value of the call f(10) and the total number of times f is called (including the initial call)?\nA. Return value 18, 4 calls in total; the call that finally returns 0 is not counted\nB. Return value 19, 5 calls in total; when n &lt;= 0 it returns 1 instead of 0\nC. Return value 19, 4 calls in total; the base case returns 1 and that call is not counted\nD. Return value 18, 5 calls in total; n is 10, 5, 2, 1, 0 in succession", back: "Answer: D\nExplanation: A f(0) is also a real call, so the total number of calls is 5; B when n <= 0 what is returned is 0, and the return value is 18; C both the return value and the number of calls are wrong, because the base case returns 0 and must be counted in the total.\n\nCorrect option: Return value 18, 5 calls in total; n is 10, 5, 2, 1, 0 in succession", src: "5cee7e5c66c8" },
  "csa-scenario-043": { front: "int[] a = {2, 5, 5, 9, 12, 12, 20};\nint lo = 0, hi = a.length - 1, steps = 0;\nwhile (lo &lt;= hi) {\n  int mid = (lo + hi) / 2;\n  steps++;\n  if (a[mid] == 12) { break; }\n  if (a[mid] &lt; 12) { lo = mid + 1; } else { hi = mid - 1; }\n}\nWhat is the value of System.out.println(steps);, and which statement about the precondition of this search is correct?\nA. steps is 1; thinks the first mid = 3 already holds 12, so it hits on a single try\nB. steps is 2; mid is 3 and then 5, and the repeated 12 does not affect correctness\nC. steps is 3; thinks a binary search over 7 elements always needs 3 comparisons\nD. steps is 2; but thinks the repeated 12 makes the result of the binary search unreliable", back: "Answer: B\nExplanation: A the value at mid = 3 is 9, which is not equal to 12, so hitting on a single try does not hold; C the number of comparisons is set by the positions actually visited, not by the number of elements, so it is not always 3; D binary search requires the array to be sorted, and repeated values do not affect correctness.\n\nCorrect option: steps is 2; mid is 3 and then 5, and the repeated 12 does not affect correctness", src: "652c0a3b0b2a" },
  "csa-scenario-044": { front: "int[] a = {6, 1, 5, 2};\nfor (int i = 0; i &lt; a.length - 1; i++) {\n  int min = i;\n  for (int j = i + 1; j &lt; a.length; j++) { if (a[j] &lt; a[min]) { min = j; } }\n  int t = a[i]; a[i] = a[min]; a[min] = t;\n}\nWhat are the contents of the array after the i = 1 pass finishes, and the total number of times the swap statement is executed?\nA. {1, 2, 5, 6}, 2 times in total; thinks the pass that swaps an element with itself should not count as a swap\nB. {1, 2, 6, 5}, 3 times in total; thinks each pass moves the minimum to the front by swapping adjacent elements\nC. {1, 2, 5, 6}, 3 times in total; in the i = 2 pass the minimum is a[2] itself, and the swap is still executed\nD. {1, 2, 5, 6}, 6 times in total; thinks each pass must swap with every remaining element for the pass to be complete", back: "Answer: C\nExplanation: A the swap statement is executed on every pass, 3 times in total; B selection sort swaps whole positions rather than adjacent elements, so after i = 1 the array is {1, 2, 5, 6} and not {1, 2, 6, 5}; D each pass swaps only once and does not swap once with every remaining element.\n\nCorrect option: {1, 2, 5, 6}, 3 times in total; in the i = 2 pass the minimum is a[2] itself, and the swap is still executed", src: "a25660faf168" },
  "csa-scenario-045": { front: "String[] name = {\"Al\", \"Bo\", \"Cy\"};\nint[] key = {3, 3, 1};\n// sorting in ascending order by key, comparing only the key\nWhat are the contents of name after a stable merge sort? And after switching to a selection sort that swaps the minimum to the front on each pass, what are they then?\nA. After merge sort {Cy, Al, Bo}, and the same after selection sort; thinks the results of arranging by ascending key value must agree\nB. After merge sort {Bo, Al, Cy}; thinks a stable sort reorders elements with the same key by name, putting Bo first\nC. After merge sort {Al, Bo, Cy}; thinks a stable sort means the relative positions of all elements stay completely unchanged\nD. After merge sort {Cy, Al, Bo}, and after selection sort {Cy, Bo, Al}; the swaps destroy stability", back: "Answer: D\nExplanation: A the swaps in selection sort destroy stability, so the two results do not agree; B elements with the same key keep their original order, so Bo still comes before Al, and they are not reordered by name; C a stable sort still moves elements to their correct positions by key and does not leave them in place.\n\nCorrect option: After merge sort {Cy, Al, Bo}, and after selection sort {Cy, Bo, Al}; the swaps destroy stability", src: "6651d96afca6" },
  "csa-scenario-046": { front: "int[] a = {-4, -8, -3};\nint max = 0;\nfor (int i = 0; i &lt; a.length; i++) {\n  if (a[i] &gt; max) { max = a[i]; }\n}\nWhat is the output of System.out.println(max);, and what is the correct change that makes this loop find the maximum for any non-empty array?\nA. Output -3; thinks the loop writes the maximum value in the array into max, so the code itself needs no change\nB. Output -4; thinks max keeps the first element it checks, -4, and is not updated by the negative numbers that follow\nC. Output -8; reads a[i] &gt; max as a[i] &lt; max and computes the minimum\nD. Output 0; max should be initialized to a[0], and the loop should traverse starting from i = 1", back: "Answer: D\nExplanation: A no element is greater than 0, so max is not updated and the output is not -3; B max keeps its initial value 0 and does not become -4; C the condition really is a[i] > max, and what is computed is the maximum rather than the minimum.\n\nCorrect option: Output 0; max should be initialized to a[0], and the loop should traverse starting from i = 1", src: "36a06259ecbc" },
  "csa-scenario-047": { front: "int count = 0;\nfor (int i = 0; i &lt; n; i++) {\n  for (int j = i; j &lt; n; j++) {\n    count++;\n  }\n}\nWhen n = 6, what is the value of count?\nA. 36; thinks each of the two loops runs 6 times, for a total of 36\nB. 21; the inner loop runs 6, 5, 4, 3, 2, and 1 times in the successive rounds\nC. 15; thinks the inner loop starts at j = i + 1 and counts only unordered pairs\nD. 30; thinks the inner loop runs a fixed 5 times each round, for 30 in total", back: "Answer: B\nExplanation: A the inner loop does not run 6 times every round; C the inner loop starts at j = i and includes the case i = j, so it is not 15; D the inner loop runs 6 - i times each round, not a fixed 5 times.\n\nCorrect option: 21; the inner loop runs 6, 5, 4, 3, 2, and 1 times in the successive rounds", src: "db249a64710c" },
  "csa-scenario-048": { front: "String a = \"ab\";\nString b = \"a\" + \"b\";\nString c = new String(\"ab\");\nWhat is the output of System.out.println((a == b) + \" \" + (a == c) + \" \" + a.equals(c));?\nA. false false true; thinks that as long as they are not the same variable, == comparing references is always false\nB. true true true; thinks == on String always compares contents rather than references\nC. true false true; the constant expression \"a\" + \"b\" is merged at compile time, while new creates a new object\nD. true false false; thinks equals and == are completely equivalent for String, so the results can only be the same", back: "Answer: C\nExplanation: A the constant expression makes a and b refer to the same String object, so the first item is true; B new String(\"ab\") creates a new object, so a == c is false; D equals compares contents while == compares references, so the two are not equivalent.\n\nCorrect option: true false true; the constant expression \"a\" + \"b\" is merged at compile time, while new creates a new object", src: "0349b954e39c" },
  "csa-scenario-049": { front: "class Holder { int v; Holder(int k) { v = k; } }\npublic static void swap(Holder x, Holder y) { Holder t = x; x = y; y = t; }\npublic static void grow(Holder h) { h.v = h.v + 5; }\nHolder p = new Holder(1);\nHolder q = new Holder(2);\nswap(p, q);\ngrow(p);\nWhat is the output of System.out.println(p.v + \" \" + q.v);?\nA. Output 7 1; thinks swap successfully exchanges the references, so grow acts on the object whose v is 2\nB. Output 2 1; thinks swap exchanges p and q, but the change made by grow is not kept\nC. Output 6 7; thinks grow acts on both p and q, because the two share the same object\nD. Output 6 2; swap exchanges only the parameter copies, and the change grow makes to the field through the reference is kept", back: "Answer: D\nExplanation: A swap exchanges only the parameter copies, so p still refers to the object whose v is 1, which becomes 6 after grow; B swap does not exchange the caller's references, so the objects that p and q refer to are not interchanged; C grow acts only on the p that is passed in, and the object that q refers to is unaffected.\n\nCorrect option: Output 6 2; swap exchanges only the parameter copies, and the change grow makes to the field through the reference is kept", src: "1fb93c2dd87b" },
  "csa-scenario-050": { front: "int[] a = {10, 20, 30};\nString s = null;\nint r = 0;\ntry {\n  r = a[1] + s.length();\n} catch (NullPointerException e) {\n  r = a[0];\n} catch (ArrayIndexOutOfBoundsException e) {\n  r = a[2];\n} finally {\n  r = r + 1;\n}\nWhat is the output of System.out.println(r);?\nA. Output 11; after s.length() throws NPE, r takes a[0], and finally adds 1 more\nB. Output 10; thinks finally executes only when the try ends normally, so it does not run here\nC. Output 31; thinks that after the NPE is caught the out-of-bounds branch still runs, so r finally takes a[2]\nD. Output 21; thinks calling length() on null returns 0, so r gets 20 and then adds 1", back: "Answer: A\nExplanation: B finally executes no matter how the try block ends, so r is increased by 1; C once the NPE is thrown control enters the matching catch at once and does not continue evaluating to a[2]; D calling length() on null throws an exception and does not return 0.\n\nCorrect option: Output 11; after s.length() throws NPE, r takes a[0], and finally adds 1 more", src: "2c0e7400a9f3" },
  "csp-scenario-001": { front: "a←[3,7,2,9]\nAPPEND(a,5)\nINSERT(a,2,6)\nREMOVE(a,4)\nList indices start at 1. After execution, what are the contents of a?\nA. The result becomes [3,6,7,2,9,5]\nB. The result becomes [3,6,7,2,5]\nC. The result becomes [3,6,7,9,5]\nD. The result becomes [3,6,7,2,9]", back: "Answer: C\nExplanation: A mistakenly treats REMOVE as deleting by value (the list contains no 4, so nothing is removed), B treats the value 9 in the list after the insertion as the element to remove (confusing an index with an element value), and D mistakenly believes that REMOVE deletes the last element.\n\nCorrect option: The result becomes [3,6,7,9,5]", src: "b4beee544382" },
  "csp-scenario-002": { front: "t←0\nFOR EACH x IN [2,5,3,80]\nIF (x MOD 2) = 0\nt←t+x\nELSE\nt←t-x\nAfter execution, what is the value of t?\nA. t equals 74\nB. t equals -74\nC. t equals 82\nD. t equals 90", back: "Answer: A\nExplanation: B reverses the condition (even numbers subtracted, odd numbers added) and gets -74, C ignores the ELSE branch and only adds the even numbers, getting 82, and D ignores the condition entirely and adds all 4 elements, getting 90.\n\nCorrect option: t equals 74", src: "ca9e13a868f0" },
  "csp-scenario-003": { front: "The daily screen time in hours of the 11 students in a class, sorted, is 1, 2, 2, 3, 3, 3, 4, 4, 5, 6, 48, where 48 is a data entry error. If 48 is changed to 4, which of the following is correct?\nA. Neither the median nor the mean changes, because the number of data values has not changed\nB. Both the median and the mean decrease, and the median decreases more\nC. The median decreases by about 2 and the mean decreases by about 4 hours\nD. The median stays unchanged and the mean decreases by about 4 hours", back: "Answer: D\nExplanation: A sees only that the number of data values has not changed and concludes that neither statistic changes, B mistakenly believes that the median is more easily pulled by extreme values than the mean, and C mistakenly believes that the median changes (after 48 is changed to 4, the median is still 3).\n\nCorrect option: The median stays unchanged and the mean decreases by about 4 hours", src: "76f6b937ad33" },
  "csp-scenario-004": { front: "A school wants to estimate the average sleep duration of all 1200 students. On a school day at 7:30 the surveyor asks only the 100 students who arrive at school earliest, and distributes the questionnaire only through the campus app. Which of the following is correct about this sample?\nA. The sample has only 100 people, so expanding it to 300 people would eliminate the bias\nB. The sample is not representative, and students who arrive early and have the app installed may sleep less\nC. This is random sampling among students, so the results can be used to infer a causal relationship\nD. The questionnaire is collected through the campus app and transmitted encrypted, so the data are relatively objective and reliable", back: "Answer: B\nExplanation: A assumes that sample size can eliminate bias, C mistakes a convenience sample for random sampling and further infers causation, and D mistakes encrypted transmission for data that are objective and reliable.\n\nCorrect option: The sample is not representative, and students who arrive early and have the app installed may sleep less", src: "e7081ecd501d" },
  "csp-scenario-005": { front: "g←[58,72,91,45,88]\nt←0\nc←0\nFOR EACH x IN g\nIF x ≥ 60\nt←t+x\nc←c+1\nDISPLAY(t/c)\nThe program outputs about 83.7. What does this output represent?\nA. The arithmetic mean of the scores of all 5 students\nB. The sum of the scores of the 3 students who scored 60 or above\nC. The average score of the 3 students who scored 60 or above\nD. The proportion of the total score of the students who scored 60 or above to the total score of the whole class", back: "Answer: C\nExplanation: A ignores the IF condition (the class average is about 70.8), B forgets the final division and looks only at the accumulated sum 251, and D reads the numerator and denominator as the passing total and the class total (a ratio of about 70.9%).\n\nCorrect option: The average score of the 3 students who scored 60 or above", src: "d4215a4d5716" },
  "csp-scenario-006": { front: "An image is 50×100 pixels, and the brightness of each pixel is represented with 4 bits and stored uncompressed. Which of the following is correct about this image?\nA. 2500 bytes are needed, and brightness has 16 possible values\nB. 20000 bytes are needed, and brightness has 16 possible values\nC. 2500 bytes are needed, and brightness has 4 possible values\nD. 5000 bytes are needed, and brightness has 256 possible values", back: "Answer: A\nExplanation: B treats 4 bits as 4 bytes and computes 20000 bytes, C treats the bit depth directly as the number of values (mistakenly writing 16 values as 4 values), and D ignores the bit depth, computes at 1 byte per pixel, and wrongly uses the 8-bit number of colors.\n\nCorrect option: 2500 bytes are needed, and brightness has 16 possible values", src: "13f84f0d2ec5" },
  "csp-scenario-007": { front: "A remote surgery system requires the round-trip latency of control commands to be below 50 milliseconds and needs about 20 Mbps of bandwidth to send video back. The carrier raises the bandwidth from 20 Mbps to 100 Mbps, and the round-trip latency between the two locations does not change. Which of the following is correct?\nA. After the bandwidth is raised, the latency decreases accordingly and the controls feel noticeably better\nB. Higher bandwidth means that packet loss no longer occurs, so transmission between the two ends is necessarily reliable\nC. Latency is determined by the distance between the two locations, and no technical means can reduce it\nD. The returned video can be clearer, but the controls will not feel better", back: "Answer: D\nExplanation: A is the typical misconception that \"large bandwidth means low latency\", B conflates bandwidth with reliability (bandwidth does not eliminate packet loss), and C ignores means such as route optimization and edge nodes that can indeed reduce latency.\n\nCorrect option: The returned video can be clearer, but the controls will not feel better", src: "db3668d375e6" },
  "csp-scenario-008": { front: "A message is split into 5 packets and sent over a packet-switching network. The 3rd packet is lost on the way, and the receiver receives the other 4 packets. Which of the following is correct?\nA. As long as redundant paths exist in the network, no packet is ever lost, so the receiver does not need to request retransmission\nB. The lost packet can be retransmitted over another path, and the receiver reassembles the original message by sequence number\nC. Packets must arrive along the same path in the order they were sent, otherwise the whole message must be discarded\nD. The sender must resend all 5 packets once in order to restore the whole message", back: "Answer: B\nExplanation: A mistakes redundant paths for never losing packets, C mistakenly believes that packets must travel the same path and arrive in strict order, and D mistakenly believes that losing one packet requires resending all the data.\n\nCorrect option: The lost packet can be retransmitted over another path, and the receiver reassembles the original message by sequence number", src: "2a21fe53e664" },
  "csp-scenario-009": { front: "A student types school.example.edu into the browser and the page opens successfully. Which of the following is correct about this access?\nA. The browser communicates with the server directly using the domain name, and the IP address is used only when resolution fails\nB. TCP/IP is responsible for rendering the web page into an image, and HTTP is responsible for transmitting the bits of the web page\nC. The domain name is first resolved to an IP address by DNS, and the browser then uses it to request the page content\nD. One domain name can correspond to only one IP address, so every access connects to the same server", back: "Answer: C\nExplanation: A assumes that the domain name can be used for communication directly, B swaps the responsibilities of TCP/IP and HTTP and also mixes in rendering, and D mistakenly believes that one domain name can correspond to only one IP address (ignoring load balancing and multiple servers).\n\nCorrect option: The domain name is first resolved to an IP address by DNS, and the browser then uses it to request the page content", src: "1bbbd64a2125" },
  "csp-scenario-010": { front: "A student wants to upload a 120 MB assignment to a server. The upload bandwidth is 10 Mbps; ignore protocol overhead (1 byte = 8 bits). About how long does the upload take?\nA. About 96 seconds\nB. About 12 seconds\nC. About 960 seconds\nD. About 9600 seconds", back: "Answer: A\nExplanation: B ignores the byte-to-bit conversion and computes 120÷10 directly, C converts the units but forgets to divide by the bandwidth and is left with only 960, and D writes the division as a multiplication and gets 960×10.\n\nCorrect option: About 96 seconds", src: "d9f7ce0919f6" },
  "csp-scenario-011": { front: "A hospital stores medical records in 3 data centers at the same time. When 1 of them goes down because of a power outage, the system can still access the data, but the annual maintenance cost rises noticeably. Which of the following is correct?\nA. This reflects encryption, because once the data are stored in separate places others cannot read their contents\nB. Multiple copies share the same data, so the total storage and maintenance cost will not rise\nC. This reflects fault tolerance, and as long as there are multiple copies the data will not be modified incorrectly\nD. This reflects fault tolerance; the data remain accessible when a single data center fails, but the cost rises", back: "Answer: D\nExplanation: A mistakes redundancy for encryption, B mistakenly believes that copies take no extra storage or cost (copies actually increase the total overhead), and C is wrong in believing that redundancy can guarantee the correctness of the data content.\n\nCorrect option: This reflects fault tolerance; the data remain accessible when a single data center fails, but the cost rises", src: "d1f18c51bea1" },
  "csp-scenario-012": { front: "A campus app collects the following data: student ID, date of birth, total steps per day, email address, and the classroom number of each class each day. Which of the following is correct?\nA. Only names count as personally identifiable information; student IDs and email addresses are just ordinary numbers\nB. Student IDs are personally identifiable information, and a combination of classroom numbers may also identify an individual\nC. As long as no names are collected, these data are no longer personal information and can be made public\nD. Step counts are also personally identifiable information, because they are stored in numeric form", back: "Answer: B\nExplanation: A equates PII with names, C assumes that removing names is the same as de-identification, and D treats the format of the data (numbers) as the basis for judging sensitivity.\n\nCorrect option: Student IDs are personally identifiable information, and a combination of classroom numbers may also identify an individual", src: "1a51701c7041" },
  "csp-scenario-013": { front: "A website uses HTTPS to transmit login information, and the server stores only the hash of \"password + random salt\" and compares hash values at login. Which of the following is correct?\nA. A hash is a form of reversible encryption, and the server can use a key to restore the hash to the original password\nB. HTTPS can guarantee that attackers cannot read the passwords in the database, so hashing is no longer necessary\nC. The transmission is protected by HTTPS, and even if the database is leaked the hash makes the password hard to recover\nD. The purpose of adding salt is to make the same password produce the same hash value every time, which makes comparison easier", back: "Answer: C\nExplanation: A treats the irreversible hash as reversible encryption, B extends the scope of protection of transmission encryption to the server database, and D misunderstands salting as keeping the hash fixed (salting is precisely what makes each result different).\n\nCorrect option: The transmission is protected by HTTPS, and even if the database is leaked the hash makes the password hard to recover", src: "9660a5fcac78" },
  "csp-scenario-014": { front: "A student logs in to the campus system with a \"password + phone verification code\", and the system also restricts him by role so that he can view only his own grades. Which of the following is correct?\nA. The password and phone verification code are used for authentication, and restricting the viewing scope is authorization\nB. The verification code is authorization, because it determines which pages you can see\nC. Both are encryption measures, because both protect the confidentiality of the data\nD. Two-factor authentication guarantees that the account cannot be cracked, so a strong password is no longer needed", back: "Answer: A\nExplanation: B mistakes an authentication method for authorization, C mistakes authentication for encryption (encryption does not determine identity), and D exaggerates the effect of two-factor authentication and on that basis gives up strong passwords.\n\nCorrect option: The password and phone verification code are used for authentication, and restricting the viewing scope is authorization", src: "0889638f35bf" },
  "csp-scenario-015": { front: "A team uses records from the past 5 years to train a model that predicts whether a student needs tutoring. Because low-income students have received less tutoring in the past, the model's predictions for these students are low. Which of the following is correct?\nA. As long as the household income field is deleted, the output of the model will no longer be biased\nB. The bias shows that the amount of data is insufficient; increasing the records 10-fold will eliminate it\nC. A model is only a mathematical computation, so it will not have any real social impact\nD. The bias comes from the way the historical data were produced, and deleting the income field cannot eliminate it", back: "Answer: D\nExplanation: A mistakenly believes that removing the sensitive field eliminates the bias, B treats the bias as an insufficient sample size, and C ignores the impact of algorithmic conclusions on real people.\n\nCorrect option: The bias comes from the way the historical data were produced, and deleting the income field cannot eliminate it", src: "b708b899fb81" },
  "csp-scenario-016": { front: "A school plans to share student attendance data with a company for an \"absence reminder\" service, and the company will keep the raw data for a long time and use it to improve its own model. Which of the following deserves the most attention?\nA. The main risk of data sharing is slower transmission, which can be addressed by negotiating higher bandwidth with the company\nB. The data of students are kept for a long time and used a second time, and the students themselves can hardly withdraw them or know about it\nC. After the school signs a contract with the company, students are no longer stakeholders\nD. Attendance records are not personal information, so sharing them requires neither informing students nor obtaining consent", back: "Answer: B\nExplanation: A mistakes a privacy risk for a bandwidth problem, C assumes that students are no longer stakeholders once a contract is signed, and D misjudges attendance data as not being personal information and thereby removes the duty to inform.\n\nCorrect option: The data of students are kept for a long time and used a second time, and the students themselves can hardly withdraw them or know about it", src: "0c24bd24933e" },
  "csp-scenario-017": { front: "A student uses binary search directly to find a value in an unsorted list of 1000 items. Which of the following is correct?\nA. Binary search works on any list, as long as its length is a power of 2\nB. The number of comparisons in binary search is independent of the list length, so it can always find the target in one step\nC. Binary search is a heuristic method: it is fast, but it cannot guarantee finding the target\nD. Binary search requires the list to be sorted; otherwise the search result may be incorrect", back: "Answer: D\nExplanation: A replaces the precondition of being sorted with whether the length is a power of 2, B mistakenly believes that the number of comparisons is independent of the length and that the target can be found in one step, and C mistakes the deterministic binary search for a heuristic method.\n\nCorrect option: Binary search requires the list to be sorted; otherwise the search result may be incorrect", src: "ffd8e295f47a" },
  "csp-scenario-018": { front: "A team simulates cafeteria queue times, assuming that each student takes exactly 30 seconds to order and not considering that students arrive at the same time during the peak between classes. Which of the following is correct?\nA. The simulation result is valid only when the assumptions hold, and ignoring the peak makes the prediction too optimistic\nB. The simulation uses random numbers, so it does not need verification; randomness automatically eliminates error\nC. As long as the number of simulation runs is increased, any wrong assumption will be corrected automatically\nD. A simulation is an experiment on the real system, and its conclusions are causal conclusions about the real world", back: "Answer: A\nExplanation: B treats randomness as a reason to skip verification, C assumes that running many times can automatically correct wrong assumptions, and D takes simulation output directly as causal conclusions about the real world.\n\nCorrect option: The simulation result is valid only when the assumptions hold, and ignoring the peak makes the prediction too optimistic", src: "789fee880c50" },
  "csp-scenario-019": { front: "Which of the following is correct about the question of deciding whether an arbitrary program P halts on input I?\nA. The problem is undecidable, which means that no individual program can determine whether it itself halts\nB. The problem is only that no one has written an algorithm yet; once computing power improves it can be solved\nC. No general algorithm exists for this problem, but the running time of many specific programs can still be analyzed\nD. A heuristic method can give a correct decision for all inputs within a finite number of steps", back: "Answer: C\nExplanation: A expands \"the general algorithm is undecidable\" into \"every individual program cannot be decided\", B mistakes undecidability for an engineering difficulty, and D mistakes a heuristic method for an algorithm that can guarantee a correct decision.\n\nCorrect option: No general algorithm exists for this problem, but the running time of many specific programs can still be analyzed", src: "96f6e94d21ac" },
  "csp-scenario-020": { front: "A delivery company wants to find the shortest tour among 30 cities. The exact algorithm takes too long to run, so the company switches to a \"nearest neighbor + local adjustment\" method. Which of the following is correct?\nA. As long as it runs long enough, this method will eventually produce the optimal route\nB. This method can obtain a good route relatively quickly, but it is not guaranteed to be optimal\nC. The exact algorithm is too slow, which shows that no algorithm can solve the shortest tour problem\nD. Nearest neighbor is an exact algorithm, so the result it produces is necessarily optimal", back: "Answer: B\nExplanation: A mistakenly believes that a heuristic method converges to the optimum if it simply runs longer, C mistakes a high computational cost for being unsolvable, and D mistakes the greedy strategy of nearest neighbor for an exact algorithm.\n\nCorrect option: This method can obtain a good route relatively quickly, but it is not guaranteed to be optimal", src: "24b367cacc6f" },
  "csp-scenario-021": { front: "A student builds a \"campus lost and found\" program: users submit an item description and a photo, and the program matches keywords in a list of 300 records and displays possible contact information. When writing the program purpose and input in the Create task report, which of the following is most appropriate?\nA. State that the program uses lists and procedures, so its purpose is to demonstrate data types\nB. Writing only \"this program is very useful and can help many people\" is enough, and the input does not need to be written\nC. State that the purpose of the program is to run without errors, and that the input is CPU and memory usage\nD. State that the purpose is to help match lost items with their owners, and that the input is the description and photo that the user fills in", back: "Answer: D\nExplanation: A treats implementation details as the purpose, B gives only vague praise and lacks a description of the input, and C takes \"not reporting errors\" as the purpose and writes the wrong source of input.\n\nCorrect option: State that the purpose is to help match lost items with their owners, and that the input is the description and photo that the user fills in", src: "c14d550ad13a" },
  "csp-scenario-022": { front: "A student writes the procedure FIND(items, key), which returns the index of the first occurrence of key and returns -1 if it is not found, and calls it in several places in the program. When describing this procedure in the Create task report, which of the following is most appropriate?\nA. Explain the meaning of the parameters and the return value, and explain how it is called in the program\nB. Explain that the procedure is an abstraction, so the report does not need to state the meaning of the parameters and return value\nC. Explain line by line the syntax of each statement inside the procedure, so that readers can copy it\nD. Explain that the procedure uses a loop, so it is data abstraction rather than procedural abstraction", back: "Answer: A\nExplanation: B misunderstands abstraction as allowing the description of the interface to be omitted, C turns the report into a line-by-line explanation of syntax, and D confuses procedural abstraction with data abstraction.\n\nCorrect option: Explain the meaning of the parameters and the return value, and explain how it is called in the program", src: "d855be1c0566" },
  "csp-scenario-023": { front: "A student's program passes the tests for cases 1, 2, and 3, but it crashes when the input is an empty list. According to the Create task testing requirements, which of the following is most appropriate?\nA. As long as all three cases pass, the report can state that the program is correct\nB. Record the input and expected result of each case, add the empty-list case, and modify the code\nC. The crash shows that this is only a syntax error, and the case should be deleted from the report so that it does not affect the score\nD. As long as the whole program is rewritten, there is no need to record the test data used before", back: "Answer: B\nExplanation: A equates passing three test cases with the program being correct, C misjudges the empty-list crash as a syntax error and wants to hide the case, and D assumes that the test records can be omitted after the code is rewritten.\n\nCorrect option: Record the input and expected result of each case, add the empty-list case, and modify the code", src: "f05af1382cbe" },
  "csp-scenario-024": { front: "A student's program uses background music downloaded from the internet, a photo of a classmate, and 200 user comments scraped from a public website. Which of the following is most appropriate?\nA. Content that is public online is in the public domain, so it can be used directly without citing the source\nB. As long as the name of the music is written in the report, licensing and personal data need not be considered\nC. Use licensed material and cite the sources, and at the same time protect the personal information in the comments\nD. Scraping public comments is using public data, so there is no privacy problem at all", back: "Answer: C\nExplanation: A mistakes being publicly visible for being in the public domain, B only provides attribution while ignoring licensing and personal information, and D mistakenly believes that public data raise no privacy problems.\n\nCorrect option: Use licensed material and cite the sources, and at the same time protect the personal information in the comments", src: "14d1b531ea14" },
  "csp-scenario-025": { front: "A student writes \"count the total steps of each student this week\" as the procedure TOTAL(steps, days) and calls it in several places in the main program. Which of the following is correct about abstraction and the content of the report?\nA. A procedure is an abstraction, so the report does not need to state who the intended users of the program are\nB. Because the procedure is called many times, it is a simulation rather than a kind of abstraction\nC. The variable names inside the procedure must match those at the call site, otherwise parameter passing will fail\nD. A procedure with parameters is an abstraction, and the report still needs to state the intended users and purpose", back: "Answer: D\nExplanation: A assumes that using abstraction means no user description is needed, B mistakes procedural abstraction for a simulation, and C invents a requirement that parameter passing places on variable names.\n\nCorrect option: A procedure with parameters is an abstraction, and the report still needs to state the intended users and purpose", src: "7202ae5f4851" },
  "csp-scenario-026": { front: "The 8-bit binary reading output by a sensor is 0010 1101, and an engineer adds 5 to this reading and still stores it as 8-bit binary. What is the 8-bit representation after adding 5?\nA. 0011 0101, because adding 5 to the low 13 gives 18 and requires successive carries\nB. 0010 1110, because adding 5 only changes the last two digits to 10\nC. 0011 0001, because it treats the original reading as the decimal number 44\nD. 0011 0010, because the original reading 45 plus 5 gives 50", back: "Answer: D\nExplanation: A computes the carry from adding 5 to the low 13 as successive carries (getting 0011 0101 = 53), B ignores the carry into the 5th bit and only changes the last two digits to 10 (getting 0010 1110 = 46), and C mistakes the binary reading for the decimal number 44 and then adds 5 (getting 0011 0001 = 49); 0010 1101 = 45, 45+5 = 50 = 0011 0010.\n\nCorrect option: 0011 0010, because the original reading 45 plus 5 gives 50", src: "dc43e4b19788" },
  "csp-scenario-027": { front: "A bitmap is 200×150 pixels, each pixel is represented with 24 bits (8 bits each for R, G, and B), and it is stored uncompressed. About how many bytes does the data portion of this bitmap take up?\nA. 90000 bytes, that is, 720000 bits divided by 8\nB. 30000 bytes, that is, counting each pixel as 1 byte\nC. 720000 bytes, that is, treating the 24 bits per pixel as 24 bytes\nD. 15000 bytes, that is, computing each pixel as 4 bits", back: "Answer: A\nExplanation: B counts each pixel as 1 byte (getting 30000 bytes), C treats 24 bits as 24 bytes (getting 720000 bytes), and D mistakes the bit depth for 4 bits (getting 15000 bytes); 200×150 = 30000 pixels, ×24 = 720000 bits, ÷8 = 90000 bytes.\n\nCorrect option: 90000 bytes, that is, 720000 bits divided by 8", src: "541e83ac334f" },
  "csp-scenario-028": { front: "A student exports a photo collection of 60 MB to share it: high-frequency details that the human eye is not sensitive to are discarded, and large areas of the same color are shrunk using a \"store once + record where it appears\" approach, giving 10 MB after compression; but the photos' capture time, device model, and latitude and longitude are still fully preserved. Which of the following is correct?\nA. Both steps are lossless compression, because the photos can still be opened normally\nB. Both steps are lossy compression, because the size shrank to one sixth\nC. Discarding details is lossy, the same-color-area compression is reversible, and the metadata are still preserved\nD. The same-color-area compression discards some pixel color values, so it is lossy compression", back: "Answer: C\nExplanation: A assumes that being able to open normally after decompression means lossless (the discarded high-frequency details can no longer be restored), B uses the compression ratio 60÷10 = 6 to infer the type of algorithm (the compression ratio has nothing to do with whether there is loss), and D treats the \"store once + record where it appears\" encoding as discarding color values (that encoding can be fully restored); discarding high-frequency details is lossy compression.\n\nCorrect option: Discarding details is lossy, the same-color-area compression is reversible, and the metadata are still preserved", src: "ccf3d3073cda" },
  "csp-scenario-029": { front: "The monthly electricity use of the 9 households in a community is 180, 190, 200, 210, 220, 230, 240, 250, and 980 kWh, where 980 kWh is a meter-reading error. The community wants to describe the electricity use level of a \"typical household\". Which of the following is correct?\nA. The mean of 300 kWh better represents the typical level, because it uses all nine data points\nB. The median of 220 kWh better represents the typical level, and the mean is raised by 980 kWh\nC. Both the mean and the median equal 300 kWh, and neither is affected by extreme values\nD. The median equals 300 kWh, which shows that the meter-reading error did not affect any statistic", back: "Answer: B\nExplanation: A believes that using all the data makes the result more reliable and ignores that the mean is raised to 300 by 980, C mistakenly believes that the median is also 300 (the 5th value of the 9 after sorting is 220), and D mistakenly believes that the meter-reading error did not affect any statistic; a median of 220 kWh better represents the typical level than a mean of 300 kWh.\n\nCorrect option: The median of 220 kWh better represents the typical level, and the mean is raised by 980 kWh", src: "f3a280121025" },
  "csp-scenario-030": { front: "A project asks the public to report by phone whether roadside parking spaces are occupied, and it receives 500,000 reports in one week; at the same moment the same parking space is often reported repeatedly by many people, with contradictory conclusions. Which of the following is correct?\nA. Crowdsourcing can obtain data quickly, but it requires deduplication and cross-checking to ensure quality\nB. The amount of data is large enough that contradictory reports cancel each other out, so no handling is needed\nC. Crowdsourced data are provided voluntarily by volunteers, so they are more objective than sensor data\nD. As long as the number of people reporting keeps increasing, the error rate will automatically drop to zero", back: "Answer: A\nExplanation: B mistakenly believes that a large amount of data makes contradictory records cancel each other out automatically (duplicate and conflicting reports still need deduplication and cross-checking), C treats voluntary reporting by volunteers as more objective than sensor data (crowdsourcing has systematic bias), and D mistakenly believes that more people reporting will bring the error rate down to zero.\n\nCorrect option: Crowdsourcing can obtain data quickly, but it requires deduplication and cross-checking to ensure quality", src: "82089ae064f9" },
  "csp-scenario-031": { front: "A running log table has 500 rows: the distance unit in 45 of the rows is miles (1 mile ≈ 1.6 kilometers) and the rest are in kilometers; the distance is missing in 12 rows; and another 30 rows are the same run imported twice. To compute the \"average distance per run\", which of the following practices is most appropriate?\nA. Fill the 12 rows with missing values with 0, because the total number of rows does not change\nB. Delete only the 30 duplicate rows, and leave the units and missing values to be handled at the analysis stage\nC. Compute the average directly from the 500 rows, because individual errors are diluted by the large sample\nD. First unify the distance unit to kilometers, then handle the missing values and remove the duplicate records", back: "Answer: D\nExplanation: A filling the missing values with 0 would pull the average distance down, B removes only the duplicates but still leaves miles and kilometers mixed together (1 mile ≈ 1.6 kilometers), and C computing directly from the 500 rows would include the unit errors, missing values, and duplicate records in the average; the units should be unified first, then the missing values handled, and then the duplicates removed.\n\nCorrect option: First unify the distance unit to kilometers, then handle the missing values and remove the duplicate records", src: "17a36877f582" },
  "csp-scenario-032": { front: "A team wants to analyze the cafeteria card-swipe data of one semester: ① export the raw card-swipe records from the school system, ② remove duplicate records and unify the time format, ③ count each person's number of meals per week, ④ report to the school with a bar chart. According to the data processing pipeline (collection, cleaning, analysis, and visualization and conclusions), which of the following practices is most appropriate?\nA. The data source is reliable, so after exporting the records it is enough to count the meals and draw the chart directly, with no cleaning needed\nB. Export the raw records, then deduplicate and unify the format, then count the meals, and finally draw the chart for the report\nC. After exporting the records, count the meals first, then deduplicate, unify the format, and draw the chart for the report\nD. After exporting the records, draw the chart for the report directly, and handle deduplication and format unification last", back: "Answer: B\nExplanation: A mistakenly believes that a reliable data source means no cleaning is necessary (duplicate records and inconsistent formats still exist), C counts the meals before cleaning and places cleaning after analysis, and D places cleaning after visualization, which amounts to drawing conclusions from uncleaned data; collection → cleaning → analysis → visualization and conclusions is the correct order.\n\nCorrect option: Export the raw records, then deduplicate and unify the format, then count the meals, and finally draw the chart for the report", src: "f55d94501e2f" },
  "csp-scenario-033": { front: "A school uses a bar chart to compare the averages of two classes: class 1 has 4.91 points and class 2 has 5.00 points (out of 5 points), the vertical axis range is set to 4.90–5.00, and on the chart class 2's bar looks about ten times as tall as class 1's. Which of the following is correct?\nA. A difference of only 0.09 points in the averages is also large, so the graph does not exaggerate the difference\nB. A bar chart cannot truncate the vertical axis; only a line chart may freely set the starting point\nC. Truncating the vertical axis magnifies the visual difference, and differences should be compared by the numbers rather than the bar heights\nD. A tenfold difference on the chart shows that the two classes' averages really differ tenfold", back: "Answer: C\nExplanation: A believes that a 0.09-point difference between 4.91 and 5.00 is also a very large gap and ignores that the graph is magnified by truncation, B mistakenly believes that only a line chart may set the starting point of the vertical axis (truncating the vertical axis of a bar chart is equally misleading), and D takes the 10-fold ratio of the bar heights as the real difference in scores; the comparison between bar heights of 0.01 and 0.10 is only an illusion caused by the vertical axis starting at 4.90.\n\nCorrect option: Truncating the vertical axis magnifies the visual difference, and differences should be compared by the numbers rather than the bar heights", src: "e0b8a407456b" },
  "csp-scenario-034": { front: "Data show that \"students who watch short videos for more than 3 hours a day score 12 points lower on average than others.\" Some people conclude from this that watching short videos causes grades to drop. Which of the following is the most reasonable judgment?\nA. A third factor such as lack of sleep may affect both variables at the same time\nB. Watching short videos causes grades to drop, so the two are in a causal relationship\nC. Only students with low grades watch short videos, so there is no correlation between the two\nD. If the correlation coefficient is large enough, the direction of causation can be determined without considering other variables", back: "Answer: A\nExplanation: B concludes causation directly from correlation, C uses the reverse explanation that \"only those with low grades watch short videos\" to deny the correlation that does exist in the data, and D mistakenly believes that a large enough correlation coefficient can determine the direction of causation; a third factor such as lack of sleep may affect both the time spent watching videos and grades.\n\nCorrect option: A third factor such as lack of sleep may affect both variables at the same time", src: "fd4c539cbbeb" },
  "csp-scenario-035": { front: "A student simulates a cafeteria queue: the assumption is that each student's food pickup time takes a random value between 20 and 40 seconds and that each person picks up food only once, but the case of a large number of students arriving at the same time when class ends is ignored. After 1000 runs, the average waiting time is 1.2 minutes. Which of the following is correct?\nA. The random numbers already include all the variation of the real world, so the result can be used directly\nB. As long as the number of runs is increased to 1,000,000, the assumption bias will disappear\nC. A simulation is an experiment on the real system, so its output is necessarily a real conclusion\nD. The assumptions do not match the real arrival pattern, and the model very likely underestimates the waiting time at the peak", back: "Answer: D\nExplanation: A treats the random numbers as the entire source of variation in the real world and ignores that the model's assumptions themselves may be biased, B mistakenly believes that increasing the number of runs to 1,000,000 can correct the wrong arrival assumption, and C takes the simulation output directly as a causal conclusion about the real world; ignoring the peak when class ends makes the waiting time underestimated.\n\nCorrect option: The assumptions do not match the real arrival pattern, and the model very likely underestimates the waiting time at the peak", src: "c79be74d8bd1" },
  "csp-scenario-036": { front: "List a is already sorted in ascending order and contains 4096 items, and the program uses binary search to determine whether a target value is in a, halving the search range after each comparison:\nlow←1\nhigh←4096\nREPEAT UNTIL (low > high)\n    mid←the integer part of (low+high)/2\n    compare a[mid] with the target value and accordingly halve the range\nTo shrink the search range from 4096 items down to only 1 item, how many halvings are needed at most?\nA. 4096 times, because in the worst case every item in the list must be checked one by one\nB. 12 times, because 2 to the 12th power equals 4096\nC. 64 times, because the square root of 4096 is exactly 64\nD. 2048 times, because after the first comparison half of the items in the list can be eliminated", back: "Answer: B\nExplanation: A treats binary search as checking items one by one (that is the 4096 times of a linear search), C uses the square root instead of the logarithm (the square root of 4096, 64, has nothing to do with the number of halvings), and D takes \"the first round eliminates half\" as the total number of times; 2 to the 12th power equals 4096, so after 12 halvings only 1 item remains in the range.\n\nCorrect option: 12 times, because 2 to the 12th power equals 4096", src: "9f905264cf1e" },
  "csp-scenario-037": { front: "A security team wants to build a tool that, for any given program, determines whether it will definitely access the network and upload user data when it runs. This kind of semantic judgment about an arbitrary program cannot be fully implemented with an algorithm, so the team has to switch to scoring suspicious behavior. Which of the following is correct?\nA. As long as a faster computer is used, this decision program can be written eventually\nB. The fact that it cannot be implemented shows that there is a syntax error in the decision program, which needs to be fixed line by line\nC. A heuristic method can give a correct judgment for all inputs within a finite number of steps\nD. The problem itself is undecidable, and heuristic scoring can only provide useful guesses", back: "Answer: D\nExplanation: A treats undecidability as an engineering problem of insufficient computing power, B mistakes semantic undecidability for a syntax error in the program, and C mistakenly believes that a heuristic method can guarantee a correct judgment for all inputs within a finite number of steps; this kind of judgment about an arbitrary program is undecidable, and heuristic scoring can only give possibly useful guesses.\n\nCorrect option: The problem itself is undecidable, and heuristic scoring can only provide useful guesses", src: "8e36c5c545fc" },
  "csp-scenario-038": { front: "A task takes 100 seconds in total, of which 80 seconds can be perfectly parallelized and 20 seconds must be executed serially. If 8 processors are used to execute the parallelizable part in parallel, about how many seconds is the theoretical minimum total time?\nA. About 12.5 seconds, because the 100 seconds are divided evenly among 8 processors\nB. About 20 seconds, because the 20 seconds of the serial part determine the minimum total time\nC. About 30 seconds, that is, the 20 serial seconds plus the 10 seconds of 80÷8\nD. About 10 seconds, because the parallelizable 80 seconds only need to be divided by 8", back: "Answer: C\nExplanation: A ignores the 20 serial seconds and divides 100 seconds directly by 8 to get 12.5 seconds, B mistakenly believes that the total time equals the 20 seconds of the serial part, and D computes only the parallelizable part 80÷8 = 10 seconds and leaves out the serial time; 20 + 80÷8 = 20 + 10 = 30 seconds.\n\nCorrect option: About 30 seconds, that is, the 20 serial seconds plus the 10 seconds of 80÷8", src: "dba2f412f9f9" },
  "csp-scenario-039": { front: "Counting a year as 8760 hours, a certain service's single server is down for about 87.6 hours per year (about 1% of the time). After the service is deployed on 3 servers that are replicas of one another, the service is interrupted only when all 3 are down at the same time; assuming the outages of the servers are independent, about what is the expected service interruption time in one year?\nA. About 32 seconds, because 0.01 to the third power times 8760 hours\nB. About 29 hours, because the 87.6 hours of a single server are divided evenly among 3 servers\nC. About 53 minutes, because 87.6 hours is multiplied by 0.01\nD. About 0 seconds, because as long as there are three copies the service will never be interrupted", back: "Answer: A\nExplanation: B divides the 87.6 hours of a single server evenly among 3 servers (getting about 29 hours) and ignores that an interruption requires all three to be down at the same time, C multiplies by 0.01 only once (87.6×0.01 ≈ 53 minutes) and is missing two factors, and D mistakenly believes that having copies means the service will never be interrupted; the interruption probability is 0.01³ = 10⁻⁶, and 8760×10⁻⁶ hours ≈ 0.526 minutes ≈ 32 seconds.\n\nCorrect option: About 32 seconds, because 0.01 to the third power times 8760 hours", src: "899ce070ba19" },
  "csp-scenario-040": { front: "A student opens a meeting website: the browser first resolves the domain name into an IP address and requests the page over HTTP, then the voice is sent with UDP in frames of 20 milliseconds each; downloading the courseware uses TCP, which automatically retransmits after packet loss. Which of the following is correct?\nA. UDP also retransmits lost frames, so the two protocols have the same reliability\nB. Domain name resolution is completed before transmission, and UDP does not guarantee retransmission or in-order arrival\nC. Domain name resolution is done by HTTP, and the IP address is used only to name the web page\nD. When UDP is used, the application cannot detect a lost frame, so the user does not notice the stuttering", back: "Answer: B\nExplanation: A mistakenly believes that UDP also retransmits lost frames (retransmission is the responsibility of TCP or the application layer), C attributes domain name resolution to HTTP and treats the IP address as the name of the web page, and D mistakenly believes that the application cannot detect lost frames and that the user will not notice stuttering; the domain name is resolved into an IP address first and then transmission happens, and UDP does not guarantee retransmission or ordering.\n\nCorrect option: Domain name resolution is completed before transmission, and UDP does not guarantee retransmission or in-order arrival", src: "00931de0d205" },
  "csp-scenario-041": { front: "A 3 GB file is uploaded to cloud storage (1 GB = 1000 MB, 1 byte = 8 bits), the link bandwidth is 50 Mbps, the actual throughput is only 80% of the bandwidth, and the round-trip latency is 80 milliseconds. Ignoring protocol overhead, about how long does the upload take?\nA. About 480 seconds, because 24000 megabits is divided by 50 Mbps\nB. About 24000 seconds, because after computing 24000 megabits it forgets to divide by the bandwidth\nC. About 60 seconds, that is, treating 3 GB as 3 Gbit and then dividing by 50\nD. About 600 seconds, because 24000 megabits is divided by 40 Mbps", back: "Answer: D\nExplanation: A uses 24000÷50 = 480 seconds and ignores that the actual throughput is only 80% of the bandwidth, B computes 24000 megabits and forgets to divide by the bandwidth, and C treats 3 GB as 3 Gbit and divides by 50 directly (getting 60 seconds), missing the factor of 8 for converting bytes to bits; 3000 MB×8 = 24000 megabits, 24000÷40 = 600 seconds, and the 80-millisecond latency can be ignored.\n\nCorrect option: About 600 seconds, because 24000 megabits is divided by 40 Mbps", src: "223f68402047" },
  "csp-scenario-042": { front: "A student wants to send an encrypted file to a teacher he has never met: the teacher publishes his public key on a website, the student encrypts the file with that public key, and the teacher decrypts it with his own private key; the student also uses the teacher's digital certificate to verify that the public key really belongs to the teacher. Which of the following is correct?\nA. Content encrypted with the public key is decrypted with the private key, and a certificate can confirm who the public key belongs to\nB. Ciphertext encrypted with the public key can only be decrypted with the public key, so the certificate is unnecessary\nC. The purpose of a digital certificate is to compress files, making the encrypted file smaller\nD. Symmetric encryption also requires publishing a public key first, so it is essentially the same as public key encryption", back: "Answer: A\nExplanation: B mistakenly believes that ciphertext encrypted with the public key can only be decrypted with the public key (in fact the teacher decrypts it with the private key) and therefore treats the certificate as unnecessary, C treats a digital certificate as a compression tool, and D mistakenly believes that symmetric encryption also requires publishing a public key first; public key encryption works together with a certificate to verify identity, and only the teacher who holds the private key can decrypt.\n\nCorrect option: Content encrypted with the public key is decrypted with the private key, and a certificate can confirm who the public key belongs to", src: "076f2d4f6c65" },
  "csp-scenario-043": { front: "A campus system uses HTTPS throughout the login process; passwords are stored in the database as \"random salt + hash\"; in addition to the password, a phone verification code is also required; and after login the system allows students to view only their own grades according to their role. Which of the following is correct?\nA. HTTPS protects the transmission process, so the passwords in the database no longer need to be stored with salt\nB. The phone verification code is authorization, because it determines which pages you can enter\nC. Transmission encryption, salted hashing, and the verification code each protect a different link, and the viewing scope is authorization\nD. With multi-factor authentication, no harm is done even if the password is obtained by a phishing website", back: "Answer: C\nExplanation: A extends the scope of protection of transmission encryption to the static data in the database, B mistakes an authentication method such as the phone verification code for authorization, and D exaggerates the effect of multi-factor authentication (the account is still compromised when a phishing website obtains the password and the verification code at the same time); transmission encryption, salted hashing, and the verification code each protect a different link, and the viewing scope is determined by authorization.\n\nCorrect option: Transmission encryption, salted hashing, and the verification code each protect a different link, and the viewing scope is authorization", src: "f9f2e77c8d6e" },
  "csp-scenario-044": { front: "A student receives an email that claims to come from the school IT department and asks him to click a link to \"verify the email password\", or else the account will be disabled within 24 hours; on the same day, the campus website becomes very slow because of a large number of forged requests from various places. Which of the following is correct?\nA. The email really comes from the school domain, which shows that this is a genuine notice, so the password can be entered directly\nB. The email is phishing social engineering, and the slow website may be a DDoS attack\nC. The website is slow because someone used a keylogger to steal the administrator's password\nD. As long as antivirus software is installed on the computer, the password can be entered on the linked page", back: "Answer: B\nExplanation: A judges the notice to be genuine merely because the email claims to come from a school domain, C attributes the slow website to a keylogger (a large number of forged requests fits a DDoS attack better), and D mistakenly believes that antivirus software can replace protecting credentials; this kind of urgent email demanding password verification is typical phishing social engineering.\n\nCorrect option: The email is phishing social engineering, and the slow website may be a DDoS attack", src: "1e3023f3e75f" },
  "csp-scenario-045": { front: "A hospital releases a public dataset that has the names and ID numbers removed and keeps only three fields: date of birth, postal code, and visit date; a researcher compares it with a public voter registration list and re-identifies some of the patients. Which of the following is correct?\nA. The data no longer contain names, so no individual can possibly be re-identified\nB. As long as the date of birth is also removed, this dataset will never be re-identified\nC. A combination of fields may constitute an identifier, and de-identified data can still be re-identified\nD. Date of birth and postal code are just ordinary codes and are not personally identifiable information", back: "Answer: C\nExplanation: A believes that removing names makes it impossible to re-identify any individual, B mistakenly believes that removing one more field can absolutely prevent re-identification, and D treats quasi-identifiers such as date of birth and postal code as ordinary codes; a combination of several fields matched against external data allows re-identification, and de-identified data can still be re-identified.\n\nCorrect option: A combination of fields may constitute an identifier, and de-identified data can still be re-identified", src: "7d769a837114" },
  "csp-scenario-046": { front: "A company uses the hiring records of the past 8 years to train a resume screening model; because the hiring rate for a certain major was high in the past, the model gives resumes from that major higher scores. Which of the following is correct?\nA. The model is only a mathematical computation, and its scores do not affect real people\nB. As long as the training data are extended to 30 years, the bias will disappear as the amount of data grows\nC. If the model has high accuracy on the test set, that shows it is not biased\nD. The bias comes from the historical hiring data themselves, and the choice of training data affects fairness", back: "Answer: D\nExplanation: A ignores the actual impact of the model's output on real people, B mistakenly believes that extending the training data from 8 years to 30 years can make the historical bias disappear, and C takes high accuracy on the test set as an absence of bias; the bias comes from the way the historical hiring data themselves were produced, and the choice of training data determines the fairness of the model.\n\nCorrect option: The bias comes from the historical hiring data themselves, and the choice of training data affects fairness", src: "42a6954de949" },
  "csp-scenario-047": { front: "In a certain area, 60% of households do not have broadband, and students can only use mobile data to complete online homework; the school has given every student a tablet, but the homework platform requires uploading a 200 MB video. Which of the following deserves the most attention?\nA. The tablets have already solved the problem, because every student received a device for going online\nB. Mobile data has the same bandwidth as broadband, so there is no real difficulty in completing the homework\nC. The access gap is not only a matter of devices; it also includes a persistent gap in bandwidth and cost\nD. As long as the school provides free data for a long time, the gap in digital access will disappear permanently", back: "Answer: C\nExplanation: A believes that handing out tablets is the same as achieving equal access, B mistakenly believes that mobile data has the same bandwidth as broadband and that completing the homework poses no difficulty, and D mistakenly believes that providing free data can permanently eliminate the gap; household broadband coverage, bandwidth, and ongoing cost are all parts of the digital access gap.\n\nCorrect option: The access gap is not only a matter of devices; it also includes a persistent gap in bandwidth and cost", src: "12a5ba80fa90" },
  "csp-scenario-048": { front: "A student builds a \"campus used book exchange\" program: the user enters a book title and an expected price, and the program searches a list for matches and displays the seller's contact information. When describing the program purpose and function in the Create task report, which of the following is most appropriate?\nA. Write the purpose as \"the program uses a list, so its purpose is to demonstrate data types\"\nB. State that the purpose is to help classmates exchange used books, and that the function is to match and display sellers\nC. Writing only \"this program is very useful and can help many classmates\" is enough, and the function does not need to be described\nD. Write the purpose as \"the program does not report errors when it runs\" and the input as CPU usage", back: "Answer: B\nExplanation: A treats an implementation detail (using a list) as the purpose of the program, C gives only vague praise and does not explain the program's function, and D takes \"no errors when it runs\" as the purpose and writes the wrong source of input; the report should state that the purpose of the program is to help classmates exchange used books and that its function is to match and display seller contact information.\n\nCorrect option: State that the purpose is to help classmates exchange used books, and that the function is to match and display sellers", src: "549e0bf639a7" },
  "csp-scenario-049": { front: "A student stores 300 book records in the list books, where each record contains a book title, a price, and the seller's contact information, and also writes the procedure SEARCH(books, key) and calls it many times in the main program. When describing abstraction in the report, which of the following is most appropriate?\nA. books is data abstraction and SEARCH is procedural abstraction, and both reduce complexity\nB. A list is only a data container and only a procedure counts as abstraction, so only SEARCH needs to be described\nC. When describing abstraction, all the statements inside SEARCH should be written out line by line so that readers can implement it\nD. Because SEARCH is called many times, it is a simulation rather than a kind of abstraction", back: "Answer: A\nExplanation: B mistakenly believes that a data abstraction such as a list does not count as abstraction and that only a procedure does, C turns the report into a line-by-line explanation of syntax (describing abstraction should give the interface and purpose rather than the internal statements), and D confuses procedural abstraction with simulation; books is a data abstraction and SEARCH is a procedural abstraction, and both reduce the complexity of the program.\n\nCorrect option: books is data abstraction and SEARCH is procedural abstraction, and both reduce complexity", src: "34a076e07e41" },
  "csp-scenario-050": { front: "A student's Create task program passes 3 sets of test data, but it crashes when the input is an empty list; the program also uses a piece of music credited \"CC BY-NC\", and he plans to publish the work on a paid learning platform. Which of the following is most appropriate?\nA. Passing all three cases shows that the program is correct, so the empty-list crash does not need to be recorded\nB. CC BY-NC allows any use, as long as the original author's credit is kept\nC. As long as the name of the music is noted in the report, licensing and testing need not be considered\nD. An empty-list test should be added and recorded, and this paid use does not comply with the NC clause", back: "Answer: D\nExplanation: A equates passing three cases with the program being correct and wants to hide the empty-list crash, B mistakenly believes that CC BY-NC allows commercial use (publishing on a paid platform is commercial use), and C thinks that noting the name of the music can replace licensing and test records; an empty-list test should be added and honestly recorded, and this paid use does not comply with the NC clause.\n\nCorrect option: An empty-list test should be added and recorded, and this paid use does not comply with the NC clause", src: "ec327cf4562c" },
  "precalc-scenario-001": { front: "Let r(x)=(x²-9)/(x²-x-6). Regarding the discontinuities and asymptotes of the graph of r, which of the following descriptions is correct?\nA. After reducing, only the vertical asymptote x=-2 remains, and there is no longer a horizontal asymptote\nB. There is a removable discontinuity at x=3, a vertical asymptote x=-2, and a horizontal asymptote y=1\nC. There are vertical asymptotes x=3 and x=-2, and a horizontal asymptote y=1\nD. There is a removable discontinuity at x=-2, a vertical asymptote x=3, and a horizontal asymptote y=1", back: "Answer: B\nExplanation: The numerator and the denominator factor as (x-3)(x+3) and (x-3)(x+2) respectively; after canceling x-3, x=3 is a removable discontinuity and x=-2 is a vertical asymptote; the numerator and the denominator have the same degree, so the horizontal asymptote is y=1. The answer is B\n\nCorrect option: There is a removable discontinuity at x=3, a vertical asymptote x=-2, and a horizontal asymptote y=1", src: "c9e7778859d2" },
  "precalc-scenario-002": { front: "The monthly profit of a product is P(t)=-2t²+12t+20 (ten thousand yuan), where t is the t-th month after launch, 0≤t≤9. Find the average rate of change of P on the interval 3≤t≤7.\nA. -32 ten thousand yuan per month, only the difference of the endpoint function values was computed\nB. 8 ten thousand yuan per month, a decrease in profit was mistakenly computed as an increase\nC. -16 ten thousand yuan per month, the instantaneous rate of change at t=7 was used instead\nD. -8 ten thousand yuan per month, the difference of the endpoints divided by the interval length 4", back: "Answer: D\nExplanation: P(3)=-18+36+20=38, P(7)=-98+84+20=6, so the average rate of change is (6-38)/(7-3)=-8 ten thousand yuan per month. The answer is D\n\nCorrect option: -8 ten thousand yuan per month, the difference of the endpoints divided by the interval length 4", src: "343133d84e89" },
  "precalc-scenario-003": { front: "What is the solution set of the inequality (x-1)/(x+3)≥2?\nA. [-7,-3), that is, -7≤x<-3\nB. (-∞,-7], obtained from x-1≥2(x+3)\nC. [-7,-3], including the endpoint x=-3\nD. (-7,-3), assuming neither endpoint can be included", back: "Answer: A\nExplanation: Moving the terms and combining over a common denominator gives (x+7)/(x+3)≤0, so -7≤x<-3, and x=-3 must be excluded because it makes the denominator zero. The answer is A\n\nCorrect option: [-7,-3), that is, -7≤x<-3", src: "075e5aa39059" },
  "precalc-scenario-004": { front: "Let g be a cubic polynomial with g(0)=5, g(1)=9, g(2)=21, and g(3)=47. Find the value of g(4).\nA. g(4)=73, extending the first difference 26\nB. g(4)=87, keeping the second difference at 14\nC. g(4)=93, keeping the third difference at 6\nD. g(4)=99, counting the third difference 6 twice", back: "Answer: C\nExplanation: The first differences are 4, 12, 26 and the second differences are 8, 14; the third difference is constantly 6, so continuing gives a next second difference of 20 and a next first difference of 46, and g(4)=47+46=93. The answer is C\n\nCorrect option: g(4)=93, keeping the third difference at 6", src: "34862cbbe369" },
  "precalc-scenario-005": { front: "The average cost for a factory to produce x units of a product is C(x)=(3x+1200)/x yuan per unit, where x is a positive integer. Find the smallest production level for which the average cost does not exceed 8 yuan per unit.\nA. At most 240 units, obtained by reversing the direction of the inequality\nB. At least 240 units, obtained from 3+1200/x≤8\nC. At least 150 units, ignoring the 3 yuan per-unit variable cost term\nD. Any positive production level works, because C(x) is decreasing", back: "Answer: B\nExplanation: Setting 3+1200/x≤8 gives 1200/x≤5, so x≥240, and the smallest production level is 240 units. The answer is B\n\nCorrect option: At least 240 units, obtained from 3+1200/x≤8", src: "6d6b4a629e10" },
  "precalc-scenario-006": { front: "Let q(x)=-2(x-1)³(x+4)(x-5)². Among its zeros, at which ones does the graph cross the x-axis (the function values change sign)?\nA. It crosses only at x=-4, and is tangent to the axis at x=1 and x=5\nB. It crosses the x-axis at all three of x=1, x=-4, and x=5\nC. It crosses at x=1 and x=5, and is tangent at x=-4\nD. It crosses at x=1 and x=-4, and is only tangent at x=5", back: "Answer: D\nExplanation: The three zeros have multiplicities 3, 1, and 2 respectively; the sign changes at zeros of odd multiplicity, so the graph crosses at x=1 and x=-4, while at x=5, which has multiplicity 2, it is only tangent and turns back. The answer is D\n\nCorrect option: It crosses at x=1 and x=-4, and is only tangent at x=5", src: "e5d2e7078bf1" },
  "precalc-scenario-007": { front: "The size of a bacterial colony satisfies N(t)=N₀·b^t (t in hours). After 2 hours of culture there are 500, and after 6 hours there are 8000. Find the colony size at hour 5.\nA. About 4000, obtained from N₀=125 and b=2\nB. About 6125, extrapolating arithmetically by 7500 every 4 hours\nC. About 32000, obtained from b=4 and N₀=31.25\nD. About 2.05 million, obtained from b=16 and N₀≈1.95", back: "Answer: A\nExplanation: b⁴=8000/500=16 gives b=2, N₀=500/4=125, and N(5)=125·2⁵=4000. The answer is A\n\nCorrect option: About 4000, obtained from N₀=125 and b=2", src: "7f3da5b30f3d" },
  "precalc-scenario-008": { front: "The concentration of a drug in the blood decays to half its value every 4 hours, and the measured concentration after dosing is 80 mg/L. Find the number of hours required for the concentration to drop to 5 mg/L.\nA. 4 hours, treating 4 half-lives as 4 hours\nB. 12 hours, computing with 3 halvings\nC. 16 hours, computing with 4 halvings\nD. 20 hours, counting the number of halvings as 5", back: "Answer: C\nExplanation: 80·(1/2)^(t/4)=5 gives (1/2)^(t/4)=1/16=2⁻⁴, so t/4=4 and t=16 hours. The answer is C\n\nCorrect option: 16 hours, computing with 4 halvings", src: "4401d4607b26" },
  "precalc-scenario-009": { front: "The balance of Plan A is 2000+150n yuan and the balance of Plan B is 500·1.2^n yuan, where n is the number of months elapsed (a nonnegative integer). Find the value of n at which the balance of Plan B first exceeds that of Plan A.\nA. n=10, rounding the approximate value of the intersection point down\nB. n=12, roughly estimating by a full year\nC. It never exceeds, because Plan A starts with a larger amount\nD. n=11, the first month that exceeds after checking month by month", back: "Answer: D\nExplanation: At n=10, Plan B is about 3096 yuan, which is less than Plan A's 3500 yuan; at n=11, Plan B is about 3715 yuan, which is greater than Plan A's 3650 yuan; so the earliest is n=11. The answer is D\n\nCorrect option: n=11, the first month that exceeds after checking month by month", src: "716d6d11c5e4" },
  "precalc-scenario-010": { front: "The sound intensity level is D=10·log₁₀(I/I₀) decibels. The sound intensity I₁ of machine A corresponds to 80 decibels, and the sound intensity I₂ of machine B corresponds to 95 decibels. Find the ratio I₂/I₁.\nA. About 15 times, directly subtracting 80 from 95\nB. About 32 times, obtained from 10^{1.5}\nC. About 10^{15} times, forgetting to divide by 10 first\nD. About 1.5 times, treating the difference of the logarithms directly as a factor", back: "Answer: B\nExplanation: From 10·lg(I/I₀)=D we get I₁=10⁸I₀ and I₂=10^{9.5}I₀, so I₂/I₁=10^{1.5}≈31.6, about 32 times. The answer is B\n\nCorrect option: About 32 times, obtained from 10^{1.5}", src: "0d6dae3eecf1" },
  "precalc-scenario-011": { front: "An investment grows continuously according to A(t)=A₀e^{0.07t} (t in years). Find the number of years required for the principal to double (ln2≈0.693).\nA. About 4.3 years, using a common logarithm instead of a natural logarithm\nB. About 14.3 years, interpreting it as linear growth of 7% per year\nC. About 9.9 years, obtained from 0.693÷0.07\nD. About 28.6 years, solving 0.07t=2 directly without taking a logarithm", back: "Answer: C\nExplanation: Setting e^{0.07t}=2 gives 0.07t=ln2≈0.693, so t≈9.9 years. The answer is C\n\nCorrect option: About 9.9 years, obtained from 0.693÷0.07", src: "90d51ee4ce5c" },
  "precalc-scenario-012": { front: "A Ferris wheel has a radius of 20 m and its center is 25 m above the ground. A passenger starts from the lowest point (5 m above the ground), and one revolution takes 12 minutes. Find the passenger's height above the ground at t=4 minutes.\nA. 35 m, since substituting t=4 gives a cosine value of -1/2\nB. 15 m, substituting after reversing the sign of the cosine term in h(t)\nC. 25 m, ignoring the amplitude term and taking only the height of the midline\nD. 45 m, directly taking the height of the highest point of the wheel", back: "Answer: A\nExplanation: h(t)=25-20cos(2πt/12); at t=4, cos(2π/3)=-1/2, so h=25+10=35 m. The answer is A\n\nCorrect option: 35 m, since substituting t=4 gives a cosine value of -1/2", src: "e301fa197146" },
  "precalc-scenario-013": { front: "Simplify (1-cos²θ)/(sinθ·cosθ), and state the additional conditions required for the equality to hold.\nA. It simplifies to tanθ, and it holds for every real number θ with no additional conditions\nB. It simplifies to cotθ, and sinθ≠0 and cosθ≠0 are required\nC. It simplifies to tanθ, and only cosθ≠0 is required\nD. It simplifies to tanθ, and sinθ≠0 and cosθ≠0 are required", back: "Answer: D\nExplanation: Using 1-cos²θ=sin²θ in the numerator, the expression equals sin²θ/(sinθcosθ)=tanθ, and sinθ≠0 and cosθ≠0 are required. The answer is D\n\nCorrect option: It simplifies to tanθ, and sinθ≠0 and cosθ≠0 are required", src: "748c59d638dc" },
  "precalc-scenario-014": { front: "Find the value of arcsin(sin(5π/6)).\nA. 5π/6, assuming that the inverse function and the original function cancel each other directly\nB. π/6, first taking 1/2 and then answering within the principal value range\nC. -π/6, giving the answer directly after taking the negative of the reference angle\nD. -5π/6, taking the negative of both the original angle and the result", back: "Answer: B\nExplanation: 5π/6 is not in the range [-π/2,π/2] of arcsin; first compute sin(5π/6)=1/2, so arcsin(1/2)=π/6. The answer is B\n\nCorrect option: π/6, first taking 1/2 and then answering within the principal value range", src: "7092bbb32103" },
  "precalc-scenario-015": { front: "The height of a simple harmonic motion is h(t)=A sin(B(t-C))+D (m), with a maximum of 14 m, a minimum of 2 m, and a period of 8 s, and it first reaches the maximum at t=1 s. Find the height at t=3 s.\nA. 2 m, mistakenly treating the sine term as reaching the minimum value -1\nB. 14 m, substituting after writing the horizontal shift as t-1\nC. 8 m, since the phase is π at that time and the sine value is 0\nD. 11 m, mistakenly taking the period parameter to be the reciprocal of the period, 1/8", back: "Answer: C\nExplanation: The maximum and the minimum give an amplitude of 6 and a midline of 8, B=2π/8=π/4, and from the maximum at t=1 we get C=-1; at t=3 the phase is π, so h=8 m. The answer is C\n\nCorrect option: 8 m, since the phase is π at that time and the sine value is 0", src: "de2f7108f3f1" },
  "precalc-scenario-016": { front: "Given sinθ+cosθ=1/2, and θ is a second-quadrant angle. Find the value of sinθ-cosθ.\nA. √7/2, taking the positive root because θ is in the second quadrant\nB. -√7/2, taking the negative sign after the square root without determining the quadrant\nC. 1/2, writing the minus sign in the square relation as a plus sign\nD. √7/4, forgetting that the denominator must also be square-rooted", back: "Answer: A\nExplanation: Squaring gives 1+2sinθcosθ=1/4, that is, sinθcosθ=-3/8, so (sinθ-cosθ)²=1-2sinθcosθ=7/4; in the second quadrant the positive value is taken, giving √7/2. The answer is A\n\nCorrect option: √7/2, taking the positive root because θ is in the second quadrant", src: "bc02aa5618b0" },
  "precalc-scenario-017": { front: "How many solutions does the equation sin(2x)=cos x have in the interval [0,2π)?\nA. 2, dividing both sides by cos x and then solving only 2sin x=1\nB. 5, counting one extra solution 7π/6 for sin x=1/2\nC. 3, assuming that cos x=0 has only one solution, x=π/2\nD. 4, namely π/6, π/2, 5π/6, 3π/2", back: "Answer: D\nExplanation: Using the double-angle formula reduces the equation to cos x(2sin x-1)=0; cos x=0 gives π/2 and 3π/2, and sin x=1/2 gives π/6 and 5π/6, for 4 solutions in total. The answer is D\n\nCorrect option: 4, namely π/6, π/2, 5π/6, 3π/2", src: "f311b8e31a19" },
  "precalc-scenario-018": { front: "What is the graph represented by the polar equation r=4cos θ?\nA. Center (4,0), radius 4, read directly from the coefficient in r=4cosθ\nB. Center (0,2), radius 2, read by replacing the polar axis with the y-axis\nC. Center (2,0), radius 2, converting to (x-2)²+y²=4\nD. Center (2,0), radius 4, taking the constant term as the radius after completing the square", back: "Answer: C\nExplanation: Multiplying both sides by r gives r²=4r cosθ, that is, x²+y²=4x; completing the square gives (x-2)²+y²=4, a circle with center (2,0) and radius 2. The answer is C\n\nCorrect option: Center (2,0), radius 2, converting to (x-2)²+y²=4", src: "155e880a1407" },
  "precalc-scenario-019": { front: "What are the coordinates of the lowest point (where y takes its minimum) of the curve represented by the parametric equations x=t+2, y=t²-4t+1 (t any real number)?\nA. (4,-3), obtained by substituting t=2 into both equations\nB. (2,-3), taking the parameter t=2 directly as the x-coordinate\nC. (4,3), computing -4+1 incorrectly as +3\nD. (2,1), taking the point corresponding to t=0", back: "Answer: A\nExplanation: y=(t-2)²-3 takes its minimum value -3 at t=2; at that time x=2+2=4, so the lowest point is (4,-3). The answer is A\n\nCorrect option: (4,-3), obtained by substituting t=2 into both equations", src: "7644922e5469" },
  "precalc-scenario-020": { front: "What are the number of petals of the graph of the polar equation r=3cos(2θ) and the maximum value of |r|, respectively?\nA. 2 petals, maximum |r| is 3, taking n=2 directly as the number of petals\nB. 4 petals, maximum |r| is 3, using 2n to find the number of petals\nC. 3 petals, maximum |r| is 3, taking the coefficient as the number of petals\nD. 6 petals, maximum |r| is 3, computing the number of petals as 2·3", back: "Answer: B\nExplanation: In r=3cos(2θ), n=2 is even, so the number of petals is 2n=4, and the maximum value of |r| is the coefficient 3. The answer is B\n\nCorrect option: 4 petals, maximum |r| is 3, using 2n to find the number of petals", src: "e55b6252980f" },
  "precalc-scenario-021": { front: "Converting the rectangular equation x²+(y-2)²=4 into the polar equation form r=f(θ) gives which of the following?\nA. r=4cos θ, writing the correspondence between sinθ and cosθ backwards\nB. r=2, assuming that r in a polar equation always equals the radius of the circle\nC. r²=4sin θ, reducing the degree only on the left side when canceling r\nD. r=4sin θ, obtained by canceling r from r²=4r sinθ", back: "Answer: D\nExplanation: Expanding gives x²+y²-4y=0; substituting x²+y²=r² and y=r sinθ gives r²=4r sinθ, and canceling r gives r=4sin θ. The answer is D\n\nCorrect option: r=4sin θ, obtained by canceling r from r²=4r sinθ", src: "3193e4a45840" },
  "precalc-scenario-022": { front: "The first row of a theater has 20 seats, and each row after that has 3 more seats than the previous row, with 15 rows in total. Find the total number of seats in the theater.\nA. 615, obtained from the arithmetic series sum formula\nB. 930, multiplying the number of seats in the last row by the number of rows\nC. 553, adding up only through the 14th row\nD. 975, computing the number of seats in the last row as 65", back: "Answer: A\nExplanation: The first term is 20 and the common difference is 3, so the last row has 20+14×3=62 seats and the total is 15×(20+62)/2=615. The answer is A\n\nCorrect option: 615, obtained from the arithmetic series sum formula", src: "1c226dd4e111" },
  "precalc-scenario-023": { front: "An airplane flies due east with an airspeed of 200 km/h, and the wind velocity is 150 km/h toward due north. Find the magnitude of the airplane's velocity relative to the ground and the angle it makes with due east (to the nearest degree).\nA. 250 km/h, about 53° north of east, taking the tangent ratio as 200/150\nB. 350 km/h, about 37° north of east, adding the two velocities directly\nC. 250 km/h, about 37° north of east, combining them with the Pythagorean theorem\nD. 50 km/h, direction still due east, subtracting the two velocities and taking the magnitude", back: "Answer: C\nExplanation: The two velocities are perpendicular, so the ground speed is √(200²+150²)=250 km/h, and the angle is arctan(150/200)≈36.9°≈37°. The answer is C\n\nCorrect option: 250 km/h, about 37° north of east, combining them with the Pythagorean theorem", src: "b0c39a12d09e" },
  "precalc-scenario-024": { front: "Given f(x)=2x+3 and g(x)=x²-1. Find the value of f⁻¹(g(3)).\nA. 8, answering after computing only the step g(3)=8\nB. 5/2, obtained from g(3)=8 and f⁻¹\nC. 13, substituting after mistakenly writing f⁻¹(x) as 2x-3\nD. 19, computing with f(8) instead of f⁻¹(8)", back: "Answer: B\nExplanation: First compute g(3)=9-1=8, then find f⁻¹(y)=(y-3)/2, so f⁻¹(8)=(8-3)/2=5/2. The answer is B\n\nCorrect option: 5/2, obtained from g(3)=8 and f⁻¹", src: "0aa82ae36bfa" },
  "precalc-scenario-025": { front: "Let f(x)=x²+4x with a restricted domain of x≥-2. Find f⁻¹(x) and its domain.\nA. f⁻¹(x)=√(x+4)-2, domain x≥0\nB. f⁻¹(x)=-√(x+4)-2, domain x≥-4\nC. f⁻¹(x)=√(x+4)+2, domain x≥-4\nD. f⁻¹(x)=√(x+4)-2, domain x≥-4", back: "Answer: D\nExplanation: Completing the square gives f(x)=(x+2)²-4, whose range on x≥-2 is [-4,+∞); solving for the inverse gives f⁻¹(x)=√(x+4)-2 with domain x≥-4. The answer is D\n\nCorrect option: f⁻¹(x)=√(x+4)-2, domain x≥-4", src: "71756ce0efb3" },
  "precalc-scenario-026": { front: "Let f(x)=x²-2x and g(x)=3x-1. Find the value of f(g(2))-g(f(2)).\nA. 16, evaluating each of the two compositions separately and then subtracting\nB. 15, answering after computing only f(g(2))\nC. -1, writing the order of the two compositions backwards\nD. 14, treating -1 as +1 when subtracting", back: "Answer: A\nExplanation: g(2)=3×2-1=5, f(5)=25-10=15; f(2)=4-4=0, g(0)=-1; 15-(-1)=16. A answered after computing only the first term, the -1 given in C is actually g(f(2)), and D treated -1 as +1 to get 14.\n\nCorrect option: 16, evaluating each of the two compositions separately and then subtracting", src: "2856cc911687" },
  "precalc-scenario-027": { front: "The value tables of the functions f and g are as follows: when x takes 1, 2, 3, 4 in order, f(x) is 3, 1, 4, 2 in order and g(x) is 2, 4, 1, 3 in order. Find the value of f(g(3))+g(f(1)).\nA. 6, both expressions skip looking up the inner function in the table\nB. 5, the second term omits the inner step g(1)=2\nC. 3, computing only the value of the first composite expression\nD. 4, reading the two expressions from the table to get 3 and 1 and then adding", back: "Answer: D\nExplanation: From the table g(3)=1, so f(g(3))=f(1)=3; also f(1)=3, so g(f(1))=g(3)=1, and the sum is 4. A skipped the inner function to get f(3)+g(1)=4+2=6, B wrongly took g(1)=2 for the second term to get 5, and D computed only the first term to get 3.\n\nCorrect option: 4, reading the two expressions from the table to get 3 and 1 and then adding", src: "d9e44ad4df1d" },
  "precalc-scenario-028": { front: "Written in interval notation, the domain of the function h(x)=√(x+3)/(x-1) is which of the following?\nA. (-3,1)∪(1,+∞), writing the square-root condition as x+3>0\nB. [-3,1)∪(1,+∞), obtained from x≥-3 and x≠1\nC. [-3,+∞), ignoring the restriction that the denominator cannot be zero\nD. [1,+∞), mistaking \"the denominator is nonzero\" for x-1≥0", back: "Answer: B\nExplanation: The square root requires x+3≥0, that is x≥-3, and the denominator requires x-1≠0, that is x≠1, so the domain is [-3,1)∪(1,+∞). B wrote the square-root condition as x+3>0 and lost x=-3, C ignored that the denominator cannot be zero, and D wrongly wrote the denominator condition as x-1≥0.\n\nCorrect option: [-3,1)∪(1,+∞), obtained from x≥-3 and x≠1", src: "29072aa2a712" },
  "precalc-scenario-029": { front: "The domain of the function f(x)=5-2√(x-4) is x≥4. Find the range of f.\nA. [5,+∞), taking the range after ignoring the negative sign of the coefficient -2 entirely\nB. (-∞,3], substituting 1 as the minimum value of the square-root term\nC. (-∞,5], the square-root term is 0 when x=4 and the maximum is attained there\nD. (-∞,5), wrongly believing that the function value cannot reach 5 when x=4", back: "Answer: C\nExplanation: √(x-4)≥0 and the coefficient is -2, so 5-2√(x-4)≤5, and the maximum 5 is attained when x=4, so the range is (-∞,5]. A ignored the negative sign and got [5,+∞), B took the minimum value of the square-root term as 1 and got (-∞,3], and C wrongly believed that the endpoint 5 is not attained.\n\nCorrect option: (-∞,5], the square-root term is 0 when x=4 and the maximum is attained there", src: "9f64e399a24e" },
  "precalc-scenario-030": { front: "The number of people enrolled in a course can be described by the linear model L(t)=300+40t and the quadratic model Q(t)=20t²-10t+300, where t is the number of weeks after enrollment begins (0≤t≤10). Find the difference between the average rates of change of the two models on the interval 2≤t≤6 (Q minus L).\nA. 110 people/week, obtained by subtracting 40 from 150\nB. 600 people/week, using the difference of the function values at the two endpoints without dividing by 4\nC. 150 people/week, computing only the average rate of change of Q\nD. 40 people/week, reporting only the slope of the linear model", back: "Answer: A\nExplanation: Q(2)=80-20+300=360, Q(6)=720-60+300=960, so the average rate of change is (960-360)/4=150 people/week; the slope of L is constantly 40 people/week, and the difference is 150-40=110 people/week. The 600 in A is the difference of the function values at the endpoints without dividing by 4, C reports only the 150 of Q, and D reports only the 40 of L.\n\nCorrect option: 110 people/week, obtained by subtracting 40 from 150", src: "727294757c6d" },
  "precalc-scenario-031": { front: "A quadratic function f satisfies f(0)=2, f(1)=5, f(2)=10, f(3)=17, f(4)=26. Which of the following correctly describes the monotonicity and concavity of f on the interval [0,4]?\nA. Increasing and concave down, because it grows faster and faster\nB. Increasing and concave up, the first differences increase term by term\nC. Decreasing and concave up, reading the first differences as decreasing\nD. Growing linearly, because the second differences are always constant", back: "Answer: B\nExplanation: The first differences are 3, 5, 7, 9 in order, all positive and increasing term by term, and the second differences are constantly 2, so f is increasing and concave up on [0,4] (f(x)=x²+2x+2). A took increasing differences as concave down, B read the signs of the differences backwards, and D mistook constant second differences for a linear function.\n\nCorrect option: Increasing and concave up, the first differences increase term by term", src: "0a037e5f75d3" },
  "precalc-scenario-032": { front: "The graph of y=f(x) passes through the point (2,-3). Let g(x)=-2f(x-1)+4. Find the point on the graph of g that corresponds to it.\nA. (1,10), substituting after reversing the direction of the shift\nB. (3,-2), mistaking the vertical coefficient -2 for +2\nC. (3,10), shifting right 1 first and then reflecting and stretching vertically\nD. (2,10), ignoring the horizontal shift and applying only the vertical transformation", back: "Answer: C\nExplanation: Let x-1=2, giving x=3, and g(3)=-2f(2)+4=-2×(-3)+4=10, so the corresponding point is (3,10). B reversed the direction of the shift and got x=1, C took the coefficient as +2 and got 2×(-3)+4=-2, and D ignored the horizontal shift and transformed only the vertical coordinate.\n\nCorrect option: (3,10), shifting right 1 first and then reflecting and stretching vertically", src: "8af9243eb5d1" },
  "precalc-scenario-033": { front: "The function f(x)=(2x+3)/(x-1) is considered only on the domain x>1, where f is a one-to-one function. Find f⁻¹(x) and its domain.\nA. f⁻¹(x)=(x+3)/(x-2), domain x≠2\nB. f⁻¹(x)=(x-3)/(x+2), domain x>2 (signs reversed)\nC. f⁻¹(x)=(x+3)/(x-2), domain x>1 (copying the original domain)\nD. f⁻¹(x)=(x+3)/(x-2), domain x>2 (from the range)", back: "Answer: D\nExplanation: f(x)=2+5/(x-1), and x>1 gives 5/(x-1)>0, so the range is y>2; solving for the inverse gives x=(y+3)/(y-2), hence f⁻¹(x)=(x+3)/(x-2) with domain x>2. A wrote x≠2, which brings in y=2 that the original function cannot take, C wrote the constant term with the sign reversed, and D copied the original domain x>1 onto the inverse function.\n\nCorrect option: f⁻¹(x)=(x+3)/(x-2), domain x>2 (from the range)", src: "e8be233caee9" },
  "precalc-scenario-034": { front: "Let the polynomial p(x)=-3(x+2)²(x-1)³(x-4). Which of the following pairs (the zeros at which the graph crosses the x-axis, and the limit of p as x→+∞) is correct?\nA. x=1 and x=4; the limit is -∞\nB. x=1 and x=4; the limit is +∞\nC. x=-2 and x=4; the limit is -∞\nD. x=1 and x=-2; the limit is -∞", back: "Answer: A\nExplanation: The three zeros have multiplicities 2 (x=-2), 3 (x=1), and 1 (x=4) in that order; at even multiplicities the graph is tangent and at odd multiplicities it crosses, so the graph crosses the x-axis at x=1 and x=4; the leading term -3x⁶ has even degree and a negative coefficient, so p→-∞ as x→+∞. A has the wrong sign for the limit, and B and C choose the wrong zeros for crossing the x-axis (the multiplicity at x=-2 is 2, so the graph is only tangent there).\n\nCorrect option: x=1 and x=4; the limit is -∞", src: "d2eeb022b18f" },
  "precalc-scenario-035": { front: "Given r(x)=(2x²-8)/(x²+x-6). Which of the following correctly describes the discontinuities and asymptotes of the graph of r?\nA. Removable discontinuity at (2,0), vertical asymptote x=-3, horizontal line y=2\nB. Vertical asymptotes x=2 and x=-3, horizontal asymptote y=2, with no removable discontinuity\nC. Removable discontinuity at (2,1.6), vertical asymptote x=-3, horizontal line y=2\nD. Removable discontinuity at (2,1.6), vertical asymptote x=-3, with no horizontal line", back: "Answer: C\nExplanation: r(x)=2(x-2)(x+2)/[(x+3)(x-2)], and after canceling x-2, x=2 is a removable discontinuity whose vertical coordinate is 2×4/5=1.6, so the hole is (2,1.6); x=-3 is a vertical asymptote, and since the numerator and denominator have the same degree the horizontal asymptote is y=2. A took the vertical coordinate of the hole as the numerator zero 0, B did not cancel and treated x=2 as a vertical asymptote as well, and D wrongly believed that there is no horizontal asymptote when the degrees are equal.\n\nCorrect option: Removable discontinuity at (2,1.6), vertical asymptote x=-3, horizontal line y=2", src: "1db9a8752406" },
  "precalc-scenario-036": { front: "A radioactive isotope sample has an initial mass of 240 g, and its half-life is 12 years. Find the number of years required for the remaining mass of the sample to drop to 15 g.\nA. 36 years, counting the number of halvings as 3\nB. 48 years, 4 half-lives are needed, 4×12=48\nC. 60 years, counting the number of halvings as 5\nD. 192 years, using 240÷15=16 and then multiplying by 12", back: "Answer: B\nExplanation: 240÷15=16=2⁴, so 4 half-lives are needed, and 4×12=48 years. B counted one half-life too few and got 36 years, C counted one too many and got 60 years, and the 240÷15×12=192 in D takes the mass multiple directly as a number of years.\n\nCorrect option: 48 years, 4 half-lives are needed, 4×12=48", src: "f0d7dfcfee58" },
  "precalc-scenario-037": { front: "Solve the logarithmic equation log₂x+log₂(x+6)=4 and find the real value of x.\nA. x=5, mistaking the sum of logarithms for the sum of the two arguments and then solving\nB. x=10, keeping only the argument of the term x+6\nC. x=-8, keeping the negative root that should be discarded from the quadratic equation\nD. x=2, obtained from x(x+6)=16 after discarding the negative root", back: "Answer: D\nExplanation: By the product rule for logarithms, log₂[x(x+6)]=4, that is x(x+6)=16, x²+6x-16=0, giving x=2 or x=-8; the domain requires x>0, so -8 is discarded. A treated the sum of logarithms as the sum of the arguments and got 2x+6=16, B took only x+6 as the argument of 16, and C kept the negative root.\n\nCorrect option: x=2, obtained from x(x+6)=16 after discarding the negative root", src: "22671758934f" },
  "precalc-scenario-038": { front: "The water depth at a harbor satisfies d(t)=4+3sin(π(t-1)/6) meters, where t is the number of hours elapsed after midnight (0≤t≤24). Find the time on that day when the water depth first reaches 5.5 meters.\nA. 2 o'clock, from the first solution where the sine term equals 0.5\nB. 4 o'clock, giving as the answer the time when the water depth reaches its maximum of 7 meters\nC. 3 o'clock, answering directly after ignoring the phase shift\nD. 6 o'clock, taking the second solution where the value of sin is 0.5", back: "Answer: A\nExplanation: Setting 4+3sin(π(t-1)/6)=5.5 gives sin(π(t-1)/6)=0.5, whose first solution satisfies π(t-1)/6=π/6, so t=2. The t=4 in A is the time when the water depth reaches its maximum of 7 meters, C ignored the phase shift and got t=3, and D took the second solution within the same period and got t=6.\n\nCorrect option: 2 o'clock, from the first solution where the sine term equals 0.5", src: "3c3672adf477" },
  "precalc-scenario-039": { front: "The terminal side of the angle θ passes through the point (3,-3√3). Find the values of sinθ and cosθ.\nA. sinθ=√3/2, cosθ=-1/2, reversing the signs for the quadrant\nB. sinθ=-3√3, cosθ=3, forgetting to divide by r=6\nC. sinθ=1/2, cosθ=-√3/2, swapping the horizontal and vertical coordinates\nD. sinθ=-√3/2, cosθ=1/2, taking the positive sign according to the quadrant", back: "Answer: D\nExplanation: r=√(3²+(3√3)²)=√36=6, and the point is in the fourth quadrant, so cosθ=3/6=1/2 and sinθ=-3√3/6=-√3/2. A reversed both signs, B forgot to divide by 6 (it should be -3√3/6), and D swapped the horizontal and vertical coordinates.\n\nCorrect option: sinθ=-√3/2, cosθ=1/2, taking the positive sign according to the quadrant", src: "468062334537" },
  "precalc-scenario-040": { front: "Find the value of sin(arccos(3/5)) and explain the basis for determining the sign.\nA. 3/5, writing the sine value and the cosine value as the same ratio\nB. 4/5, the range of arccos gives an angle in the first quadrant\nC. -4/5, wrongly believing that the angle of arccos is in the fourth quadrant\nD. 4/3, taking the tangent value by mistake by using opposite over adjacent", back: "Answer: B\nExplanation: Let θ=arccos(3/5), then cosθ=3/5 and θ∈[0,π]; since cosθ>0, θ is a first-quadrant angle, and sinθ=√(1-9/25)=4/5, which is positive. A took 3/5 directly, B wrongly took the fourth quadrant and made it negative, and C took tanθ=4/3.\n\nCorrect option: 4/5, the range of arccos gives an angle in the first quadrant", src: "6d6f86bc7a84" },
  "precalc-scenario-041": { front: "Simplify [1-(sin⁴θ+cos⁴θ)]/(sin²θ·cos²θ) and state the condition required for the equality to hold.\nA. 2, it holds for every real number θ with no additional condition\nB. 0, mistaking sin⁴θ+cos⁴θ for 1\nC. 2, and it holds only when sinθ≠0 and cosθ≠0\nD. 2sin²θcos²θ, dropping one factor when canceling", back: "Answer: C\nExplanation: From sin⁴θ+cos⁴θ=1-2sin²θcos²θ the numerator is 2sin²θcos²θ, which equals 2 after canceling; since the denominator contains sinθcosθ, we need sinθ≠0 and cosθ≠0. B ignored that the denominator cannot be zero, C mistook sin⁴θ+cos⁴θ for 1 and got 0, and D dropped one factor of the denominator when canceling.\n\nCorrect option: 2, and it holds only when sinθ≠0 and cosθ≠0", src: "8de5a6b0ed50" },
  "precalc-scenario-042": { front: "In polar coordinates, what curve is represented by the equation r=2+2sinθ? Which of the following correctly describes the shape of the curve, its axis of symmetry, and the distance from the farthest point to the pole?\nA. A cardioid, symmetric about θ=π/2, with |r| at most 4\nB. It represents a circle whose center is at the pole and whose radius is 2\nC. A cardioid, symmetric about the polar axis, with |r| at most 2\nD. A limaçon with an inner loop, because r takes negative values after θ=3π/2", back: "Answer: A\nExplanation: r=2+2sinθ≥0 always holds, so there is no inner loop and the curve is a cardioid; since r(π/2+α)=r(π/2-α), it is symmetric about the line θ=π/2, and the maximum value is 2+2×1=4. A takes it as a circle, C judges the axis of symmetry wrongly and takes the maximum as 2, and D wrongly believes that r takes negative values and an inner loop appears.\n\nCorrect option: A cardioid, symmetric about θ=π/2, with |r| at most 4", src: "87ab8f413105" },
  "precalc-scenario-043": { front: "Convert the rectangular-coordinate point (-3,3√3) to polar coordinates (r,θ), where r>0 and 0≤θ<2π. The result is?\nA. (6,π/3), ignoring the quadrant and taking the reference angle directly\nB. (3√3,2π/3), dropping the square of the horizontal coordinate when finding r\nC. (6,4π/3), taking a third-quadrant angle just because the horizontal coordinate is negative\nD. (6,2π/3), obtained from r=6 and the reference angle π/3", back: "Answer: D\nExplanation: r=√((-3)²+(3√3)²)=√36=6; the point is in the second quadrant and the reference angle is arctan(3√3/3)=π/3, so θ=π-π/3=2π/3. A ignored the quadrant and took π/3, B dropped 3² when finding r and got √27=3√3, and D took 4π/3 by looking only at the negative horizontal coordinate.\n\nCorrect option: (6,2π/3), obtained from r=6 and the reference angle π/3", src: "35b0605372c0" },
  "precalc-scenario-044": { front: "The motion of a projectile can be described by the parametric equations x(t)=40t and y(t)=30t-5t² (x and y are in meters and t is in seconds). Find the horizontal distance x when the projectile falls back to the ground.\nA. 120 meters, substituting the time t=3 corresponding to the highest point\nB. 240 meters, finding t=6 from y=0 and then substituting into the equation for x\nC. 0 meters, believing that the horizontal displacement is zero when it falls back to the ground\nD. 480 meters, adding together the upward and downward parts of the path", back: "Answer: B\nExplanation: Setting y=30t-5t²=5t(6-t)=0 gives the landing time t=6 (t=0 is the starting point), and x(6)=40×6=240 meters. A used the time of the highest point t=3 and got 120 meters, B wrongly believed that the horizontal displacement is zero, and C doubled 240 meters into 480 meters.\n\nCorrect option: 240 meters, finding t=6 from y=0 and then substituting into the equation for x", src: "ecc5b6a6a5df" },
  "precalc-scenario-045": { front: "Given the vectors a=(4,-3) and b=(-1,2). Find the magnitude of the vector 2a-b (to the nearest 0.1).\nA. √106≈10.3, multiplying only the horizontal coordinate of a by 2\nB. √65≈8.1, writing the minus sign in 2a-b as a plus sign and then finding the magnitude\nC. √145≈12.0, obtained from 2a-b=(9,-8)\nD. √50≈7.1, subtracting directly after missing the factor 2", back: "Answer: C\nExplanation: 2a=(8,-6), so 2a-b=(8+1,-6-2)=(9,-8), whose magnitude is √(81+64)=√145≈12.0. B multiplied only the horizontal coordinate by 2 and got (9,-5) (magnitude √106), C wrote it as 2a+b=(7,-4) (magnitude √65), and D missed the factor 2 and got a-b=(5,-5) (magnitude √50).\n\nCorrect option: √145≈12.0, obtained from 2a-b=(9,-8)", src: "b406361f6ad3" },
  "precalc-scenario-046": { front: "Let the matrix M=[0 -1; 1 0], let the coordinates of point P be (4,-1), and write the coordinates of the point as a column vector. Find the coordinates of the point P′ after M is applied, and state the geometric meaning of the transformation.\nA. (1,4), obtained by a 90° counterclockwise rotation about the origin\nB. (-1,-4), a 90° clockwise rotation about the origin\nC. (-1,4), a reflection about the line y=x\nD. (4,-1), the determinant is 1 so the point stays fixed", back: "Answer: A\nExplanation: M(x,y)=(-y,x), and substituting (4,-1) gives (1,4), that is a 90° counterclockwise rotation about the origin. What A gets is (-1,-4), the 90° clockwise rotation, C's (-1,4) is the point symmetric about y=x, and D wrongly believes that a determinant of 1 means the point does not move.\n\nCorrect option: (1,4), obtained by a 90° counterclockwise rotation about the origin", src: "273912d27f24" },
  "precalc-scenario-047": { front: "A geometric sequence {aₙ} satisfies a₂=6 and a₅=162. Find the sum of the first 5 terms S₅ of this sequence.\nA. 726, substituting the second term 6 as the first term into the sum formula\nB. 242, obtained by substituting r=3 and a₁=2 into the formula\nC. 410, using the sum formula for an arithmetic sequence by mistake\nD. 80, miscalculating 3⁵ as 81 when finding the common ratio", back: "Answer: B\nExplanation: r³=a₅/a₂=162/6=27, so r=3 and a₁=6/3=2, hence S₅=2(3⁵-1)/(3-1)=2×242/2=242. A took a₂ as the first term and got 6(3⁵-1)/2=726, B used the arithmetic formula and got (2+162)×5/2=410, and C computed 3⁵ as 81 and got 80.\n\nCorrect option: 242, obtained by substituting r=3 and a₁=2 into the formula", src: "d587babaa4bc" },
  "precalc-scenario-048": { front: "In the expansion of the binomial (3-x)⁵, what is the coefficient of the x³ term (including the sign)?\nA. 90, dropping the negative sign when expanding (-x)³\nB. -9, missing the binomial coefficient C(5,3)=10\nC. -90, obtained from the combination number 10 and 3² and the negative sign\nD. -270, miscalculating 3² as 3³=27", back: "Answer: C\nExplanation: The x³ term is C(5,3)·3²·(-x)³=10×9×(-1)x³, so the coefficient is -90. A dropped the negative sign and got 90, B missed the combination number 10 and got -9, and D computed 3² as 27 and got -270.\n\nCorrect option: -90, obtained from the combination number 10 and 3² and the negative sign", src: "cc9f39629c97" },
  "precalc-scenario-049": { front: "The number of fish in a pond satisfies P(t)=1200/(1+5e^{-0.4t}) fish, where t is the number of months after the fry are released (ln5≈1.609). Find the number of months required for the fish population to reach 600 (to the nearest 0.1).\nA. About 1.6 months, forgetting to divide by 0.4 after computing ln5\nB. About 0.6 months, multiplying ln5 by 0.4 instead of dividing\nC. About 5.8 months, writing the condition as 5e^{-0.4t}=0.5\nD. About 4.0 months, obtained from e^{-0.4t}=0.2", back: "Answer: D\nExplanation: Setting 1200/(1+5e^{-0.4t})=600 gives 5e^{-0.4t}=1, that is e^{-0.4t}=0.2, so -0.4t=-ln5 and t=1.609/0.4≈4.0 months. A computed only ln5≈1.6, B took 1.609×0.4≈0.6 as the answer, and the condition in C gives t=ln10/0.4≈5.8.\n\nCorrect option: About 4.0 months, obtained from e^{-0.4t}=0.2", src: "cf7854462a7f" },
  "precalc-scenario-050": { front: "A parking lot's fee rule is as follows: parking for no more than 2 hours is a flat fee of 10 yuan; for the part exceeding 2 hours an extra 3 yuan is charged per hour, and any part less than 1 hour is counted as 1 hour. A certain car parks for 5.5 hours. How many yuan should be paid?\nA. 22 yuan, the excess 3.5 hours are charged as 4 hours\nB. 20.5 yuan, charging the excess part precisely as 3.5 hours\nC. 19 yuan, rounding the excess part down to 3 hours\nD. 26.5 yuan, charging all of the time at 3 yuan per hour", back: "Answer: A\nExplanation: The excess is 5.5-2=3.5 hours, and counting any partial hour as a full hour makes it 4 hours, so the fee is 10+4×3=22 yuan. B charged the 3.5 hours precisely and got 20.5 yuan, C rounded down to 3 hours and got 19 yuan, and D charged all of the time at 3 yuan per hour and got 26.5 yuan.\n\nCorrect option: 22 yuan, the excess 3.5 hours are charged as 4 hours", src: "12d109eaf07d" },
  "stats-scenario-001": { front: "A researcher randomly selected 60 of the 800 first-year high school students at a school and then randomly divided these 60 students into two groups of 30 each. One group used a new memorization method and the other used a traditional method. Two weeks later both groups took the same memory test. Based on this design, the most appropriate inference is\nA. There is evidence that the new method improved scores, and the conclusion can be generalized to all first-year high school students nationwide\nB. There is only correlational evidence, because each group has only 30 students, too few to infer causation\nC. There is only correlational evidence, because the same student was not measured twice\nD. There is evidence that the new method improved scores, and the conclusion can be generalized only to first-year high school students at that school", back: "Answer: D\nExplanation: Consider first the sampling method: random sampling means the conclusion can be generalized only to the first-year high school students at that school who were sampled. Consider next the grouping method: random assignment allows a causal inference between the new method and scores. A small sample size or the absence of repeated measurements does not overturn either point, and extending the conclusion nationwide goes beyond the sampled population\n\nCorrect option: There is evidence that the new method improved scores, and the conclusion can be generalized only to first-year high school students at that school", src: "41443e419c25" },
  "stats-scenario-002": { front: "To compare the effects of a new painkiller with a placebo, a researcher randomly divided 120 patients with chronic low back pain into two groups; one group took the new drug and the other took a placebo identical in appearance and taste. However, the nurse who handed out the drugs knew who was taking the new drug, while the patients did not. Which of the following statements about this experiment is correct\nA. Both the patients and the nurse were blinded, so the experiment contains no bias at all\nB. The patients were blinded but the nurse was not, so the nurse's attitude may affect the patients' reports\nC. The patients were blinded but the nurse was not, so no causal difference between the two groups can be inferred\nD. Because a placebo was used as a control, the experiment is an observational study", back: "Answer: B\nExplanation: That the patients did not know their group is single blinding; the nurse knew who was taking the new drug, so her attitude while giving the drug and asking questions may affect the patients' pain reports, thereby introducing bias. Random assignment still allows this experiment to support a causal inference, and a placebo control does not turn it into an observational study\n\nCorrect option: The patients were blinded but the nurse was not, so the nurse's attitude may affect the patients' reports", src: "d752c580d0ff" },
  "stats-scenario-003": { front: "A school wants to compare the effects of two mathematics teaching methods on students' final exam scores. Students are first divided into three strata (high, middle, and low) according to their entrance scores, then randomly assigned within each stratum to one of the two teaching methods, and finally the final exam scores are compared. The main purpose of this arrangement is\nA. to keep the number of students assigned to each teaching method exactly the same at all times\nB. to completely eliminate the influence of entrance scores on differences in final exam scores\nC. to compare the two teaching methods while controlling for differences in score strata\nD. to treat the entrance-score stratum as an additional treatment variable", back: "Answer: C\nExplanation: Stratifying first and then randomly assigning within each stratum is a block design; its purpose is to separate the variation due to entrance scores from the error, making the comparison of the two teaching methods more precise. A blocking variable is not a treatment variable, and it can only reduce, not completely eliminate, score differences\n\nCorrect option: to compare the two teaching methods while controlling for differences in score strata", src: "5503f67ea681" },
  "stats-scenario-004": { front: "After the evening news, a television station asked viewers to respond by hotline or mobile phone vote on whether they support lengthening the school day. A total of 4200 responses were received, 71% of which expressed support. The most appropriate assessment of the survey results is\nA. The sample size is very large, so 71% is nearly the same as the population proportion and there is nothing to worry about\nB. The sample size is very large, so the results can be generalized to all viewers who own mobile phones\nC. The sample size is large enough to offset the bias caused by voluntary response, so the results can still be generalized\nD. This is a voluntary response sample; enthusiastic viewers are more likely to respond, so the results cannot be generalized to the population", back: "Answer: D\nExplanation: Letting viewers decide for themselves whether to respond constitutes a voluntary response sample; those who are enthusiastic or hold strong opinions are more likely to respond, and this is a systematic bias. No matter how large the sample size is, it only reduces random variation and cannot eliminate this bias, so the results cannot be generalized to all viewers\n\nCorrect option: This is a voluntary response sample; enthusiastic viewers are more likely to respond, so the results cannot be generalized to the population", src: "c68230eb211b" },
  "stats-scenario-005": { front: "An observational study compared students who often eat breakfast with those who rarely do and found that the former had a noticeably higher mean GPA. On this basis the researcher recommended that all students eat breakfast every day in order to improve their grades. The most appropriate criticism of this recommendation is\nA. A third variable such as family income may affect both breakfast and grades\nB. An observational study cannot provide information about whether an association exists between the two variables\nC. Because there was no random sampling, there is no association at all between breakfast habits and grades\nD. As long as the sample size is large enough, an association can be used as a causal relationship", back: "Answer: A\nExplanation: An observational study can only establish association; breakfast habits may vary together with third variables such as family income and daily routine, and these variables in turn affect grades. Association is not causation, but the study itself still provides information that an association exists between the two\n\nCorrect option: A third variable such as family income may affect both breakfast and grades", src: "df44c3b9a770" },
  "stats-scenario-006": { front: "A researcher wants to compare the effects of two types of running shoes on 5-kilometer times. 40 runners each ran once in each type of shoe over a two-week period, with the order in which the shoes were worn determined at random, and then the difference between each runner's two times was compared. This design\nA. is a completely randomized design, because the runners were randomly divided into two groups\nB. is a paired design, but because there was no random sampling, no causal inference can be made\nC. is a paired design, and the random order controls for order effects and individual differences\nD. is an observational study, because each runner served as his or her own control", back: "Answer: C\nExplanation: Each runner received both treatments in turn and the difference between the two times was compared, which is a paired design. Randomizing the order balances order effects such as practice effects and fatigue, and individual differences cancel out in the differences, so a causal inference is supported even without random sampling\n\nCorrect option: is a paired design, and the random order controls for order effects and individual differences", src: "8456cd69fde8" },
  "stats-scenario-007": { front: "A chain brand collected daily sales y (cups) and price per cup x (yuan) from 12 stores and obtained the regression line ŷ=320-18.5x with r²=0.64. The correct interpretation of this regression coefficient is\nA. For each 1-yuan increase in price per cup, daily sales decrease by an average of 0.64 cups\nB. For each 1-yuan increase in price per cup, daily sales decrease by an average of 18.5 cups\nC. The correlation r between price and daily sales is equal to -0.64\nD. When the price per cup rises by 1 yuan, daily sales must decrease by about 18.5 cups", back: "Answer: B\nExplanation: The slope is the average change in y for each 1-unit increase in x, so for each 1-yuan increase in price, daily sales decrease by an average of 18.5 cups. The value 0.64 is r², the coefficient of determination, not the slope; the correlation should be -0.8, and an average decrease does not mean a decrease every single time\n\nCorrect option: For each 1-yuan increase in price per cup, daily sales decrease by an average of 18.5 cups", src: "498acd5b7aad" },
  "stats-scenario-008": { front: "A brand uses the price per cup at its stores to predict daily sales, and the coefficient of determination of the regression model is r²=0.64. The most appropriate interpretation of r² is\nA. Price can explain about 64% of the variation in daily sales, and the rest comes from other factors\nB. For each 1-unit change in price, there is a 64% probability that daily sales change along with it\nC. The correlation r between price and daily sales is also 0.64, in the negative direction\nD. The average gap between predicted values and actual sales is about 0.64 cups", back: "Answer: A\nExplanation: r² is the proportion of the total variation accounted for by the regression sum of squares, meaning that when price is used to predict daily sales, about 64% of the variation in sales can be explained by the regression and the remaining 36% comes from factors other than price. r should equal -0.8, and r² is not the average prediction error\n\nCorrect option: Price can explain about 64% of the variation in daily sales, and the rest comes from other factors", src: "83d114d855c6" },
  "stats-scenario-009": { front: "A researcher used 24 students' weekly practice time x (hours) to predict test scores y (points). In the scatterplot, the point with the largest x is clearly below the overall trend; after removing this point the slope increases from 1.3 to 2.1 and r² increases from 0.55 to 0.81. The most appropriate statement about this point is\nA. The point must be a data-entry error, so it should simply be deleted from the formal analysis\nB. The point makes r² smaller, so it must be an influential point\nC. The point clearly affects the slope, and the report should note it and check its influence\nD. The point deviates from the line, showing that a linear model is not appropriate for this data set", back: "Answer: C\nExplanation: The point lies at the far end of x and clearly deviates from the trend. Removing it changes the slope from 1.3 to 2.1 and r² from 0.55 to 0.81, showing that it has a strong influence on the regression line, so its influence should be reported and checked. Deviating from the trend or making r² smaller is not enough to conclude that it is erroneous data\n\nCorrect option: The point clearly affects the slope, and the report should note it and check its influence", src: "99bf1dc04d6b" },
  "stats-scenario-010": { front: "A school uses daily study time x (hours) to predict mathematics test scores y (points) and obtains ŷ=52+6.5x. In the data, x ranges from 2 to 10 hours. A student plans to study 20 hours per day, and the teacher uses this equation to predict his score. The most appropriate assessment of this is\nA. The predicted value is 182 points, which exceeds the maximum possible score, showing that the equation was computed incorrectly\nB. As long as r² is close to 1, predictions made for any x are equally reliable\nC. The predicted value is very high, showing that study time and scores are negatively correlated\nD. 20 hours is far beyond the range of the data and constitutes extrapolation, so the prediction is not reliable", back: "Answer: D\nExplanation: Substituting 20 hours into the equation gives 52 plus 130, which equals 182 points, but x in the original data lies only between 2 and 10 hours. Using the equation to predict x outside that range is extrapolation, and the regression relationship need not hold outside the range of the data. A large r² only means a good fit within the range\n\nCorrect option: 20 hours is far beyond the range of the data and constitutes extrapolation, so the prediction is not reliable", src: "a7af10f6cb3a" },
  "stats-scenario-011": { front: "A school surveyed 200 students: 45 of the 100 boarding students exercise every day, and 30 of the 100 commuting students exercise every day. Comparing the proportions who exercise every day in the two groups, the most appropriate conclusion is\nA. The proportion of boarding students who exercise every day is 0.15 higher, showing that boarding causes students to enjoy exercise more\nB. The proportion who exercise every day among all students is 0.45, so there is no difference between the two groups\nC. The proportion for boarding students is 0.15 higher, but this does not show that boarding causes a greater enjoyment of exercise\nD. The proportion of commuting students who exercise every day is 0.70, clearly higher than that of boarding students", back: "Answer: C\nExplanation: The proportion of boarding students who exercise every day is 45 divided by 100, which equals 0.45, and that of commuting students is 30 divided by 100, which equals 0.30; the two differ by 0.15. But these are observational data, so it cannot be said that boarding causes a greater enjoyment of exercise. The value 0.70 is the proportion of commuting students who do not exercise\n\nCorrect option: The proportion for boarding students is 0.15 higher, but this does not show that boarding causes a greater enjoyment of exercise", src: "2608d4e08fa9" },
  "stats-scenario-012": { front: "In a regression analysis, a residual plot is made with x on the horizontal axis and the residuals on the vertical axis. In the plot the residuals first rise as x increases and then steadily fall, forming a clear curved shape. The most appropriate conclusion is\nA. The residuals show systematic curvature, showing that a linear model may not be appropriate\nB. The residuals are curved, showing autocorrelation among adjacent residuals\nC. The mean of the residuals is about 0, showing that a linear model is appropriate\nD. As long as r² is large enough, the curvature in the residual plot can be ignored", back: "Answer: A\nExplanation: The residuals rise and then fall as x increases, forming systematic curvature; this shows that the linear model fails to capture the relationship between x and y, so the form of the model is not appropriate. A residual mean of 0 does not rule out curvature, curvature is not a matter of autocorrelation among adjacent residuals, and a large r² does not cover it up either\n\nCorrect option: The residuals show systematic curvature, showing that a linear model may not be appropriate", src: "263b875cbc8e" },
  "stats-scenario-013": { front: "In a factory with two production lines, line A produced 60% of all products with a defect rate of 2%, and line B produced 40% with a defect rate of 5%. One item is randomly selected from all of the day's products and is known to be defective. The probability that it came from line A is approximately\nA. about 0.600, that is, using line A's share of total production directly\nB. about 0.375, that is, reweighting by each line's share of the contribution to defective items\nC. about 0.012, that is, the product of line A's production share and its defect rate\nD. about 0.020, that is, the joint probability that an item from line B is defective", back: "Answer: B\nExplanation: The probability that line A contributes a defective item is 0.6 times 0.02, which equals 0.012, and for line B it is 0.4 times 0.05, which equals 0.020. The conditional probability that a defective item came from line A is 0.012 divided by 0.032, which equals 0.375. The value 0.600 is the prior production share, and 0.012 and 0.020 are joint probabilities rather than conditional probabilities\n\nCorrect option: about 0.375, that is, reweighting by each line's share of the contribution to defective items", src: "0023796a1346" },
  "stats-scenario-014": { front: "A player makes each free throw with probability 0.7, and the free throws are independent. He keeps shooting free throws until his first success. The probability that he first succeeds on exactly the 4th free throw is approximately\nA. 0.0756, that is, the probability of exactly one success in four free throws\nB. 0.0189, that is, the first three are misses and the fourth is a success\nC. 0.0270, that is, the probability that the first three are all misses\nD. 0.4116, that is, the probability of exactly three successes in four free throws", back: "Answer: B\nExplanation: First succeeding on exactly the 4th attempt requires the first three to be misses and the fourth to be a success; the probability is 0.3 cubed times 0.7, which is approximately 0.0189. The value 0.0756 is the binomial probability of exactly one success in four attempts, 0.4116 is exactly three successes, and 0.0270 omits the requirement that the last attempt be a success\n\nCorrect option: 0.0189, that is, the first three are misses and the fourth is a success", src: "2905e55ab46c" },
  "stats-scenario-015": { front: "For a shop, the number of units X of a product sold each day has expected value 12 units and standard deviation 3 units. Each unit sold yields a profit of 20 yuan, and the shop also pays a fixed cost of 200 yuan per day. If the daily net profit is Y=20X-200 yuan, then the expected value and standard deviation of Y are, respectively\nA. 40 yuan and 3 yuan, because the variation in the number of units sold does not change with the profit\nB. 40 yuan and 60 yuan, because the standard deviation is affected only by the factor of 20\nC. 240 yuan and 60 yuan, because the fixed cost need not be subtracted from the expected value\nD. 40 yuan and 140 yuan, because the fixed cost must also be subtracted from the standard deviation", back: "Answer: B\nExplanation: First use the linearity of expectation: 20 times 12 minus 200 equals 40 yuan. Then note that the standard deviation is affected only by the multiplier, and adding or subtracting a constant does not change it, so the standard deviation is 20 times 3, which equals 60 yuan. Taking the standard deviation to be 3 omits the multiplication by 20, and subtracting 200 from the standard deviation confuses the two types of operations\n\nCorrect option: 40 yuan and 60 yuan, because the standard deviation is affected only by the factor of 20", src: "0f40539f0921" },
  "stats-scenario-016": { front: "A raffle costs 5 yuan per play. Let X yuan be the prize from one play, with distribution P(X=0)=0.8, P(X=20)=0.15, P(X=100)=0.05. The expected net gain from playing once is\nA. an expected net gain of 8 yuan, that is, the expected prize from one play\nB. an expected net gain of 3 yuan, that is, the expected prize minus the 5-yuan cost\nC. an expected net gain of 5 yuan, that is, the 5-yuan participation cost that must be paid every time\nD. an expected net gain of -3 yuan, that is, the 5-yuan cost minus the expected prize", back: "Answer: B\nExplanation: First find the expected prize: 0.15 times 20 plus 0.05 times 100 equals 8 yuan. Then subtract the 5-yuan participation cost of each play, so the expected net gain is 3 yuan. Taking 8 yuan as the net gain omits the cost, and subtracting 8 from 5 reverses the direction of the subtraction\n\nCorrect option: an expected net gain of 3 yuan, that is, the expected prize minus the 5-yuan cost", src: "f79d795dfe6a" },
  "stats-scenario-017": { front: "A machine fills beverage bottles. The volume X of a single bottle has expected value 500 milliliters and standard deviation 4 milliliters. Three bottles are packed into a box, and the volumes of the bottles are independent. The standard deviation of the total volume of one box of beverage is approximately\nA. about 6.93 milliliters, because the variances are added and then the square root is taken\nB. about 12 milliliters, because the standard deviation is added in proportion as the number of bottles increases\nC. about 4 milliliters, because packing into a box changes only the mean and not the standard deviation\nD. about 48 milliliters, because the variances of the 3 bottles should be added directly to give the result", back: "Answer: A\nExplanation: The variance of a sum of independent random variables equals the sum of their variances, that is, 3 times 16 equals 48, and the standard deviation is the square root of 48, approximately 6.93 milliliters. Adding the standard deviations in proportion gives 12, and treating the variance directly as the standard deviation gives 48. Packing into a box likewise changes the standard deviation of the total volume\n\nCorrect option: about 6.93 milliliters, because the variances are added and then the square root is taken", src: "bebd8feedf4a" },
  "stats-scenario-018": { front: "In a city, 40% of residents support a certain proposal. A random sample of 100 residents is taken from the city, and the sample proportion p̂ is used to estimate the support rate. Then the sampling distribution of p̂\nA. is approximately normal, with mean 0.4 and standard deviation about 0.049\nB. is approximately normal, with mean 0.4 and standard deviation about 0.0024\nC. is not approximately normal, because the population proportion 0.4 is not equal to 0.5\nD. is approximately normal, with mean 0.4 and standard deviation about 0.0049", back: "Answer: A\nExplanation: Check the conditions first: np equals 40 and n times (1-p) equals 60, both at least 10, so the sampling distribution of p̂ is approximately normal, with mean equal to the population proportion 0.4 and standard deviation equal to the square root of 0.4 times 0.6 divided by 100, about 0.049. The value 0.0024 is the variance, and 0.0049 comes from taking the square root of the denominator n as well\n\nCorrect option: is approximately normal, with mean 0.4 and standard deviation about 0.049", src: "d20de031f15a" },
  "stats-scenario-019": { front: "A factory tests H0: the mean battery life equals 40 hours against Ha: the mean life is greater than 40 hours, with significance level α=0.05. If in fact the mean battery life is exactly 40 hours but the test result rejects H0, then this decision\nA. is a Type II error, and its probability is equal to α\nB. is a Type II error, and its probability equals 1 minus α\nC. is a Type I error, and its probability equals 1 minus β\nD. is a Type I error, and its probability is equal to α", back: "Answer: D\nExplanation: Rejecting H0 when H0 is true is a Type I error, and its probability is controlled by the significance level, so it equals α. A Type II error is failing to reject when H0 is false, with probability denoted β; 1 minus β is the power of the test, not an error probability\n\nCorrect option: is a Type I error, and its probability is equal to α", src: "dbb2a5b6a155" },
  "stats-scenario-020": { front: "A researcher tests H0: μ=10 against Ha: μ≠10, obtains a p-value equal to 0.03, and compares it with α=0.05. The most appropriate interpretation of this result is\nA. If H0 is true, the probability of obtaining the current result or a more extreme one is 3%\nB. A p-value of 0.03 means that the probability that the null hypothesis H0 is true is 3%\nC. After rejecting H0, the probability that the null hypothesis is false is about 97%\nD. Because the p-value is less than 0.05, H0 has been proven false", back: "Answer: A\nExplanation: The p-value is the probability of obtaining the current or a more extreme sample result given that H0 is true. Since 0.03 is less than α equal to 0.05, H0 is rejected. The p-value is not the probability that H0 is true, and rejecting H0 is not the same as proving H0 false; it only means that the evidence against H0 is fairly strong\n\nCorrect option: If H0 is true, the probability of obtaining the current result or a more extreme one is 3%", src: "354d88ca474c" },
  "stats-scenario-021": { front: "A researcher takes a random sample of residents from a city and obtains a 95% confidence interval for the mean commute time of (28, 36) minutes. The correct interpretation of this interval is\nA. The probability that the population mean falls between 28 and 36 minutes is 95%\nB. About 95% of the residents of this city have commute times between 28 and 36 minutes\nC. About 95% of intervals constructed in this way contain the population mean\nD. On repeated sampling, about 95% of sample means fall within this interval", back: "Answer: C\nExplanation: The 95% in a confidence interval describes the long-run performance of the construction method: about 95% of the intervals constructed from repeated sampling contain the population mean. For this one interval that has already been computed, we can only say that it does or does not contain the population mean. The population mean is not a random variable, and the interval does not describe individual residents\n\nCorrect option: About 95% of intervals constructed in this way contain the population mean", src: "588ecf66f039" },
  "stats-scenario-022": { front: "A school claims that 60% of its students take public transportation to school. To test this claim, a researcher randomly selects 80 students, 40 of whom take public transportation. Let p be the true proportion of students who take public transportation. The most appropriate statement about this test is\nA. A two-proportion z-test should be used instead, because the 80 students are divided into two groups, those who take it and those who do not\nB. The approximately normal condition is not met, because p̂=0.5 is not equal to the hypothesized value 0.6\nC. The conditions are met, z is about -1.83, and the one-sided p-value is about 0.034\nD. The conditions are met, z is about -1.83, and the two-sided p-value is about 0.068", back: "Answer: D\nExplanation: First check the conditions using the hypothesized value: 80 times 0.6 equals 48 and 80 times 0.4 equals 32, both at least 10. Then, using p̂ equal to 0.5, z is about -1.83, and because the alternative hypothesis is two-sided the p-value is about 0.068. The value 0.034 results from mistaking a two-sided test for a one-sided one, and the claim that the conditions are not met does not hold either\n\nCorrect option: The conditions are met, z is about -1.83, and the two-sided p-value is about 0.068", src: "50f67264e7eb" },
  "stats-scenario-023": { front: "A study randomly surveyed 300 adults, recording their highest level of education (high school or below, bachelor's degree, graduate degree) and whether they exercise regularly every week, in order to determine whether the two variables are related. In the contingency table test, all expected counts are not less than 6.2. The most appropriate procedure is\nA. to use a chi-square test for independence, since the expected-count condition is already met\nB. to use a chi-square goodness-of-fit test, because it can compare two categorical variables\nC. to use a chi-square test for independence, but the expected counts are too small, so the condition is not met\nD. to use a two-proportion z-test, because both variables have more than two categories", back: "Answer: A\nExplanation: An association between two categorical variables is tested with a chi-square test for independence. Education split into three categories cannot be handled by a two-proportion z-test, which applies only to 2×2 tables, and a chi-square goodness-of-fit test deals with the distribution of only one variable. All expected counts not less than 6.2 already satisfies the condition of at least 5\n\nCorrect option: to use a chi-square test for independence, since the expected-count condition is already met", src: "1521438ff8a1" },
  "stats-scenario-024": { front: "A study organized 400 students into a 2×2 contingency table by whether they attended after-school tutoring and whether they passed the final exam. A chi-square test for independence gives χ²=6.74, df=1, p-value=0.0094. Taking α=0.05, the correct conclusion is\nA. at α=0.05 the independence hypothesis is rejected, and the two variables are associated\nB. the p-value 0.0094 means that the probability that the two variables are independent is only 0.0094\nC. the small p-value shows that there is a strong causal relationship between the two variables\nD. at α=0.05 the independence hypothesis cannot be rejected, because the χ² value is not large enough", back: "Answer: A\nExplanation: First, χ² equal to 6.74 with df equal to 1 gives a p-value of about 0.0094. Comparing with α equal to 0.05, the p-value is less than α, so the independence hypothesis is rejected and the conclusion is that the two variables are associated. A chi-square test shows association only, not causation, and the p-value is not the probability that the independence hypothesis is true\n\nCorrect option: at α=0.05 the independence hypothesis is rejected, and the two variables are associated", src: "1e8f33d4b775" },
  "stats-scenario-025": { front: "A study uses data from 30 cities to predict per capita consumption y (thousand yuan) from per capita income x (thousand yuan). The regression output gives an intercept of 1.35, a slope of 0.72, a standard error of the slope of 0.24, and a p-value of 0.006 for the test of the slope. Taking α=0.05, the correct conclusion is\nA. the slope of 0.72 means that the correlation between income and consumption is also 0.72\nB. because the p-value is small, the model can explain 99.4% of the variation in consumption\nC. for each 1-thousand-yuan increase in income, consumption definitely rises by 0.72 thousand yuan\nD. there is evidence that the population slope is not 0, and the two variables have a linear relationship", back: "Answer: D\nExplanation: First compute the t-value for the slope test: 0.72 divided by 0.24 equals 3.0. With df of 28 this corresponds to a two-sided p-value of about 0.006, which is less than 0.05, so the null hypothesis that the population slope is 0 is rejected, indicating evidence supporting a linear relationship between income and consumption. A small p-value does not mean a large proportion of variation explained, and a regression slope is not equal to a correlation\n\nCorrect option: there is evidence that the population slope is not 0, and the two variables have a linear relationship", src: "8e3adb5ce773" },
  "stats-scenario-026": { front: "A school has 1200 students in total: 500 in grade 10, 400 in grade 11, and 300 in grade 12. A researcher wants to estimate the mean amount of sleep per day of the students in the whole school. He first divides the students into three strata by grade and then randomly selects a total of 120 students within the strata in proportion to the number of students. Compared with simply randomly selecting 120 of the 1200 students directly, the main advantage of this stratified sampling is\nA. The proportions of the grades in the sample match those of the whole school, and the variation within strata is smaller, so the variability of the estimate is smaller\nB. The numbers of students selected from the grades are exactly the same, 40 each, making the sample more balanced across the strata\nC. Within a stratum, convenience sampling can replace random sampling, because stratification itself already guarantees representativeness\nD. The conclusion can be generalized to all high school students nationwide, because the proportions of the grades have been controlled", back: "Answer: A\nExplanation: After proportional stratification the numbers sampled from the strata are 50, 40, and 30, so the sample structure matches that of the whole school, and the small within-stratum variation makes the variability of the estimate smaller, so A is correct; 40 students would be equal allocation rather than proportional allocation, sampling within a stratum must still be random rather than convenience sampling, and stratification guarantees representativeness only for this school and cannot generalize the conclusion to high school students nationwide\n\nCorrect option: The proportions of the grades in the sample match those of the whole school, and the variation within strata is smaller, so the variability of the estimate is smaller", src: "fa5bb4677d2e" },
  "stats-scenario-027": { front: "A factory produces 2000 parts every day. An inspector numbers the parts 1 to 2000 in production order, first randomly chooses a starting point from 1 to 20, and then selects one part every 20 parts, checking 100 parts in total; the defect rate turns out to be noticeably lower than in past records. The most appropriate statement about this sampling method is\nA. This is cluster sampling, because taking one part every 20 parts amounts to treating 20 consecutive products as one cluster\nB. This is systematic sampling, and if defects appear periodically with a period that coincides with the interval of 20, defects may be missed\nC. This is stratified sampling, because the products are divided by number into 20 strata and then one part is drawn from each\nD. This is simple random sampling, because the starting point is randomly generated, so the sample is certainly unbiased", back: "Answer: B\nExplanation: A random starting point plus a fixed interval of 20 is systematic sampling, and if defects appear periodically with a period that coincides with the interval, defects will be missed systematically, so B is correct; treating 20 consecutive parts as one group is cluster sampling, dividing products by number into strata and drawing one part from each is stratified sampling, and a random starting point is not the same as simple random sampling, in which every part has an equal chance of being selected\n\nCorrect option: This is systematic sampling, and if defects appear periodically with a period that coincides with the interval of 20, defects may be missed", src: "7d83d3b8de77" },
  "stats-scenario-028": { front: "A website placed a voting button on its home page and received 6800 responses within two days, 82% of which opposed building a new waste treatment plant; at the same time, a researcher randomly selected 400 registered users of the same website for telephone interviews, and 46% of them opposed it. The most appropriate explanation of the difference between the two results is\nA. The sample of 6800 is far larger than 400, so 82% is closer to the true proportion\nB. The home-page vote is biased, so the interview results from the 400 randomly selected users are equally untrustworthy\nC. The home-page vote is a voluntary response sample, and enthusiastic people are more willing to take part, so no matter how large the sample is, the bias is hard to eliminate\nD. The difference between the two results shows that residents' opinions changed noticeably within two days, so both results are valid", back: "Answer: C\nExplanation: The home-page vote is taken by viewers who choose to take part themselves, and those with strong opinions are more likely to respond, which is a systematic bias; increasing the sample size only reduces random fluctuation and cannot eliminate this bias, so C is correct; a sample of 6800 cannot make 82% closer to the true proportion, there is no basis for extending the bias of the home-page vote to the randomly selected sample of 400 interviewees, and opinions would not change that quickly within two days\n\nCorrect option: The home-page vote is a voluntary response sample, and enthusiastic people are more willing to take part, so no matter how large the sample is, the bias is hard to eliminate", src: "8ab11efe5740" },
  "stats-scenario-029": { front: "A pharmaceutical company tested a new anti-allergy drug, randomly dividing 200 patients into two groups: one group took the new drug, and the other took a placebo identical in appearance and taste, and neither the patients nor the doctors who assessed the symptoms knew the group assignments. As a result, symptom scores in the new-drug group fell by an average of 4.2 points, and those in the placebo group fell by 1.6 points. The most appropriate conclusion from this experiment is\nA. The difference of 2.6 points between the two groups shows that the new drug is effective, and the conclusion can be generalized to all allergy patients nationwide\nB. Because both the patients and the doctors were blinded, the experiment contains no bias at all, and the difference comes entirely from the drug\nC. With a difference of 2.6 points and random assignment, it can be inferred that the new drug has a causal effect on these patients\nD. Symptom scores in the placebo group also fell by 1.6 points, showing that the placebo is effective and that the experiment lacks a control group", back: "Answer: C\nExplanation: Random assignment plus a placebo control plus double blinding means that the difference of 2.6 points between the two groups can be given a causal interpretation, but it applies only to the patients who took part in the experiment, so C is correct; without random sampling from a population the conclusion cannot be generalized to all allergy patients nationwide, double blinding controls only part of the bias rather than eliminating all of it, the decline in the placebo group is a placebo effect, and the experiment does still have a control group\n\nCorrect option: With a difference of 2.6 points and random assignment, it can be inferred that the new drug has a causal effect on these patients", src: "923b3dd2ea9d" },
  "stats-scenario-030": { front: "An agricultural research station wants to compare the effects of two fertilizers on wheat yield. Because the fertility of the experimental plots varies considerably, the 24 plots are first divided by fertility into 8 blocks of 3 plots each with similar fertility, and then within each block the 3 plots are randomly assigned to fertilizer A, fertilizer B, and a control. Compared with completely randomly dividing the 24 plots into three groups, the main advantage of this design is\nA. It gives each treatment the same number of plots, so the experiment no longer needs random assignment\nB. It treats fertility as a second treatment variable, so that the interaction between fertilizer and fertility can be compared\nC. The block design can completely eliminate fertility differences, so that differences in yield come entirely from the two fertilizers\nD. It separates fertility differences from the error, making differences among the treatments easier to detect", back: "Answer: D\nExplanation: Blocking separates the variation caused by fertility, and reducing the error makes differences among the treatments easier to detect, so D is correct; a block design still requires random assignment, fertility is a blocking variable rather than a second treatment variable, and blocking can only reduce, not completely eliminate, fertility differences\n\nCorrect option: It separates fertility differences from the error, making differences among the treatments easier to detect", src: "f4beeece8762" },
  "stats-scenario-031": { front: "A researcher wants to compare the effects of two keyboard layouts on typing speed. He recruits 30 typists, each of whom types the same passage once with each of the two layouts within a two-week period, with the order of use determined by random numbers, and finally he analyzes the difference between each typist's two times. The most appropriate statement about this design and the inference is\nA. It is a paired design, individual differences cancel out in the differences, and the random order controls for practice effects\nB. It is a completely randomized design, because the order for each typist is determined by random numbers\nC. It is an observational study, because each typist used two different keyboard layouts one after the other\nD. It is a paired design, but because the typists were not obtained by random sampling, no inference at all can be made from the results", back: "Answer: A\nExplanation: Having the same group of people receive both treatments one after the other and analyzing the differences is a paired design; individual differences cancel out in the differences and the random order balances practice and fatigue effects, so A is correct; a completely randomized design would assign individuals to different groups, whereas here every typist receives both treatments; this is not an observational study; and the absence of random sampling affects only how far the conclusion can be generalized, not the causal inference for this group of typists\n\nCorrect option: It is a paired design, individual differences cancel out in the differences, and the random order controls for practice effects", src: "f5a31f6d1c57" },
  "stats-scenario-032": { front: "A city health department randomly selected 1500 adults from the adults of the whole city for a survey and found that the proportion with high blood pressure was 21% among those who drank sugary beverages more than 3 times per week and 12% among those who rarely drank them. On this basis the researcher recommended that residents drink fewer sugary beverages in order to lower their risk of high blood pressure. The most appropriate criticism of this recommendation is\nA. Because the survey used random sampling, the conclusion can both be generalized to the adults of the whole city and show that sugary beverages cause high blood pressure\nB. Because there was no random assignment, people who drink more beverages may also differ in other respects, so no causal inference can be made\nC. Because the sample size reached 1500, random fluctuation is already small, so the causal relationship in it is reliable\nD. Because there was no random assignment, even the proportion of the adults of the whole city who have high blood pressure cannot be estimated", back: "Answer: B\nExplanation: Random sampling guarantees only generalizability, whereas random assignment is what supports a causal conclusion; people who drink more beverages may also differ in other respects, and these third variables confound the comparison, so B is correct; random sampling cannot replace random assignment, a large sample size only reduces random fluctuation and cannot eliminate confounding, and random sampling is precisely what makes the citywide proportion estimable\n\nCorrect option: Because there was no random assignment, people who drink more beverages may also differ in other respects, so no causal inference can be made", src: "cfd77f71d49e" },
  "stats-scenario-033": { front: "A university investigated the admission outcomes of its applicants, organized by the department applied to as follows: in the highly competitive department A, 20 men applied and 4 were admitted, and 80 women applied and 24 were admitted; in the less selective department B, 80 men applied and 64 were admitted, and 20 women applied and 17 were admitted. The most appropriate analysis of the data from these two departments is\nA. Men's overall admission rate of 68% is higher than women's 41%, showing that the university clearly favors men in admissions\nB. In department A the joint proportion of women admitted, 0.24, is 6 times that of men, so women are more likely to be admitted\nC. Women's admission rate is higher in both departments, showing that women's overall admission rate must also be higher than men's\nD. Women's admission rate is higher in both departments, and the overall difference comes mainly from differences in the structure of the departments applied to", back: "Answer: D\nExplanation: In department A the admission rate for women, 24/80=30%, is higher than men's 4/20=20%, and in department B the rate for women, 17/20=85%, is higher than men's 64/80=80%, but overall men applied more often to the less selective department B, so the difference between the overall rates of 68% and 41% comes mainly from the structure of the departments, and D is correct; A draws a conclusion favoring men from marginal proportions while ignoring the confounding variable of department; B divides the two joint proportions 0.24 and 0.04, which have different denominators, to get a factor of 6, when in fact the number of women applying to that department is 4 times the number of men, and their chances of being admitted are only 30% versus 20%, with women's overall admission rate actually lower; C is contrary to the data\n\nCorrect option: Women's admission rate is higher in both departments, and the overall difference comes mainly from differences in the structure of the departments applied to", src: "9c484721ab32" },
  "stats-scenario-034": { front: "The grade-12 mathematics mock exam scores (out of 150) at two high schools in a city are as follows: school A has 200 students, median 96, interquartile range 18, mean 98, standard deviation 12, highest score 150; school B has 200 students, median 96, interquartile range 26, mean 92, standard deviation 20, lowest score 22. Comparing the distributions of the scores at the two schools, the most appropriate statement is\nA. The median at both schools is 96, showing that the shapes of the two distributions are also exactly the same\nB. The standard deviation at school B is larger, showing that the mean score of school B's students is also higher than that of school A's students\nC. The interquartile range at school A is smaller, showing that the scores of its middle half of students are more concentrated than those at school B\nD. School A has a highest score of 150, showing that the proportion of high-scoring students at school A is clearly higher than at school B", back: "Answer: C\nExplanation: The interquartile range describes the spread of the middle half of the data; school A's 18 is smaller than school B's 26, so the middle half of school A's scores is more concentrated, and C is correct; equal medians do not mean equal shapes, a larger standard deviation and a higher mean are two different things, and school B's mean of 92 is in fact lower, and a single highest score cannot show the proportion of high-scoring students\n\nCorrect option: The interquartile range at school A is smaller, showing that the scores of its middle half of students are more concentrated than those at school B", src: "fd5506775d9d" },
  "stats-scenario-035": { front: "To show that housing prices in a city rose from 3.0 ten-thousand yuan per square meter to 3.6 ten-thousand yuan per square meter within one year, a media outlet set the vertical axis of the chart it drew to start at 2.8 ten-thousand yuan and enlarged both the height and the width of the bars representing housing prices to 2 times their original size. The most appropriate assessment of this chart is\nA. The actual increase is about 20%, but truncating the vertical axis and enlarging the width and height of the bars exaggerates the apparent size of the increase\nB. The actual increase is about 20%, and setting the vertical axis to start at 2.8 ten-thousand yuan shows that the data in the chart are themselves erroneous\nC. After both the width and the height of the bars are enlarged 2 times, the visual area is also enlarged 2 times, which matches the actual increase exactly\nD. As long as the chart labels the starting point of the vertical axis, truncating the vertical axis will not mislead readers at all", back: "Answer: A\nExplanation: Starting the vertical axis at 2.8 ten-thousand yuan visually magnifies the difference of 0.6 ten-thousand yuan, and enlarging the width and the height 2 times each makes the area 4 times as large while the increase is still 20%, which is a typical misleading graph, so A is correct; the data themselves are not wrong, an area enlarged 2 times is not consistent with the actual increase, and labeling the starting point cannot eliminate the exaggeration caused by truncating the vertical axis\n\nCorrect option: The actual increase is about 20%, but truncating the vertical axis and enlarging the width and height of the bars exaggerates the apparent size of the increase", src: "ded69364bc88" },
  "stats-scenario-036": { front: "The lifetime of a certain type of battery is approximately normally distributed with mean 500 hours and standard deviation 40 hours. From a standard normal table, P(Z<0.5)=0.6915 and P(Z<1.25)=0.8944. The proportion of batteries of this type with a lifetime between 520 hours and 550 hours is approximately\nA. about 0.692, that is, directly taking the cumulative proportion 0.6915 corresponding to 520 hours\nB. about 0.894, that is, directly taking the cumulative proportion 0.8944 corresponding to 550 hours\nC. about 0.106, that is, using 1 minus the cumulative proportion 0.8944 corresponding to 550 hours\nD. about 0.203, that is, subtracting the cumulative proportions corresponding to 550 hours and 520 hours", back: "Answer: D\nExplanation: First compute z1=(520-500)/40=0.5 and z2=(550-500)/40=1.25, then take the difference of the two cumulative proportions, 0.8944-0.6915=0.2029, so D is correct; 0.6915 is the proportion below 520 hours, 0.8944 is the proportion below 550 hours, and 1-0.8944=0.1056 is the proportion above 550 hours, so all three use only a single boundary\n\nCorrect option: about 0.203, that is, subtracting the cumulative proportions corresponding to 550 hours and 520 hours", src: "523df503fe80" },
  "stats-scenario-037": { front: "A company claims that the proportion of its customer service calls answered within 30 seconds is 0.35. The quality department randomly checks 200 call records every day and uses the sample proportion p̂ to estimate this proportion. The most appropriate statement about the sampling distribution of p̂ is\nA. mean about 0.35 and standard deviation about 0.0011, because the variance was taken directly as the standard deviation\nB. mean about 0.35 and standard deviation about 0.034, and it is approximately normal because both expected counts are greater than 10\nC. mean about 0.35 and standard deviation about 0.034, but the distribution must be right-skewed, because the population proportion is less than 0.5\nD. mean about 0.35 and standard deviation about 0.48, because the sample size need not be divided out when computing the standard deviation", back: "Answer: B\nExplanation: First check that np=70 and n(1-p)=130 are both greater than 10, so the distribution is approximately normal, with mean equal to the population proportion 0.35 and standard deviation equal to the square root of 0.35 times 0.65 divided by 200, approximately 0.0337, so B is correct; 0.0011 is the variance, a proportion not equal to 0.5 does not make the distribution right-skewed, and failing to divide by the sample size gives 0.477\n\nCorrect option: mean about 0.35 and standard deviation about 0.034, and it is approximately normal because both expected counts are greater than 10", src: "d7d586373ccd" },
  "stats-scenario-038": { front: "The distribution of the monthly income of a city's residents is clearly right-skewed, with population mean 6000 yuan and standard deviation 2400 yuan. A researcher uses a computer simulation to randomly draw samples from this city and compute the sample mean x̄, running two sets of simulations, one with sample size 4 and one with sample size 100. The most appropriate statement about the sampling distribution of x̄ is\nA. When the sample size is 4, the distribution of x̄ must also be approximately normal, because the population mean happens to be 6000 yuan\nB. The larger the sample size, the closer x̄ is to 6000 yuan, showing that x̄ itself is biased when the sample size is small\nC. Under both sample sizes the mean of x̄ is about 6000 yuan, and with sample size 100 the distribution is narrower and closer to normal\nD. With sample size 100 the standard deviation of x̄ is still about 2400 yuan, because the population standard deviation of income does not change", back: "Answer: C\nExplanation: The sample mean is an unbiased estimator of the population mean for any sample size, so in both sets of simulations the mean of x̄ is about 6000 yuan; when n=100 the standard error is 2400 divided by 10, which equals 240 and is far smaller than 1200 when n=4, and by the Central Limit Theorem the distribution is closer to normal, so C is correct; with sample size 4 the sampling distribution from a right-skewed population will not be approximately normal, x̄ is still unbiased when the sample size is small, and when n=100 the standard deviation should be about 240 yuan rather than 2400 yuan\n\nCorrect option: Under both sample sizes the mean of x̄ is about 6000 yuan, and with sample size 100 the distribution is narrower and closer to normal", src: "bd929fe5c242" },
  "stats-scenario-039": { front: "A school randomly surveyed 400 students, of whom 248 supported extending the library's opening hours. The researcher computed a sample proportion p̂=0.62, a standard error of about 0.0243, and a 95% confidence interval of about (0.572, 0.668). The most appropriate interpretation of this interval is\nA. About 95% of the school's students support extending the opening hours, with a proportion between 0.572 and 0.668\nB. On repeated sampling, about 95% of the intervals constructed in the same way will contain the school's true proportion\nC. The probability that the school's true support proportion falls between 0.572 and 0.668 is 95%\nD. The probability that the sample proportion 0.62 falls within this interval is 95%, showing that the estimate is very reliable", back: "Answer: B\nExplanation: The 95% describes the long-run performance of the interval construction, and about 95% of the intervals obtained from repeated sampling will contain the true population proportion, so B is correct; A treats the interval as a range of the proportions of individual students, C treats the population parameter as a random variable, and D overlooks that the sample proportion 0.62 is itself the center of the interval, so its probability of falling within it is 1\n\nCorrect option: On repeated sampling, about 95% of the intervals constructed in the same way will contain the school's true proportion", src: "262e206f9dda" },
  "stats-scenario-040": { front: "A factory randomly selected 25 steel cables and measured their tensile strength; the sample mean is 820 newtons and the standard deviation is 60 newtons. With 24 degrees of freedom t*=2.064, and the margin of error of the 95% confidence interval is about 24.8 newtons. If the sample size is changed to 100 cables, with the sample standard deviation still about 60 newtons and t* still taken as 2.064, then the new margin of error is approximately\nA. about 24.8 newtons, because the sample size changes only the center of the interval and not its width\nB. about 6.2 newtons, because the margin of error is inversely proportional to the sample size, so making the sample size 4 times as large reduces it to one quarter\nC. about 49.6 newtons, because as the sample size increases the standard error also becomes 2 times its original value\nD. about 12.4 newtons, because the margin of error is inversely proportional to the square root of the sample size, so it is exactly halved", back: "Answer: D\nExplanation: The standard error is 60 divided by the square root of 25, which equals 12, and the margin of error is 2.064 times 12, about 24.8; when the sample size becomes 100 the standard error is 60 divided by 10, which equals 6, so the margin of error is about 12.4, that is, the margin of error is inversely proportional to the square root of the sample size, and D is correct; the margin of error changes with the sample size rather than only the center of the interval changing, being inversely proportional to the sample size would give 6.2, and as the sample size increases the standard error should become smaller rather than 2 times as large\n\nCorrect option: about 12.4 newtons, because the margin of error is inversely proportional to the square root of the sample size, so it is exactly halved", src: "4763d5c89ee6" },
  "stats-scenario-041": { front: "Last year 55% of the students at a school exercised regularly. This year the school randomly surveyed 150 students, 96 of whom exercise regularly. A researcher tests whether this year's proportion differs from last year's 55%, taking α=0.05, and has already confirmed that the conditions are met. Based on this test, the most appropriate conclusion is\nA. z is about 2.22 and the two-sided p-value is about 0.027, so H0 is rejected, showing that the proportion has indeed changed\nB. z is about 2.22 and the p-value is about 0.013, because a one-sided test should be done here\nC. The conditions are not met, because p̂=0.64 differs from the hypothesized value 0.55 by 0.09, too large a deviation\nD. z is about 2.22 and the p-value is about 0.027, showing that the probability that H0 is true is about 0.027", back: "Answer: A\nExplanation: From p̂=96/150=0.64, and using the hypothesized value to compute the standard error, the square root of 0.55 times 0.45 divided by 150 is about 0.0406, so z is about 2.22, and the two-sided p-value of about 0.027 is less than 0.05, so H0 is rejected, and since the alternative is two-sided A is correct; asking whether the proportion differs calls for a two-sided test, 0.013 is the one-sided p-value, the conditions are met because np0=82.5 and n(1-p0)=67.5 are both greater than 10, and the p-value is not the probability that H0 is true\n\nCorrect option: z is about 2.22 and the two-sided p-value is about 0.027, so H0 is rejected, showing that the proportion has indeed changed", src: "f3db83c9007e" },
  "stats-scenario-042": { front: "A brand claims that the mean net content of its bottled juice is 500 milliliters. An inspector randomly selects 16 bottles and measures a sample mean of 494 milliliters and a standard deviation of 8 milliliters, testing whether the mean content is too low, with α=0.05. It is known that with df=15 a one-sided area of 0.0123 corresponds to t=-2.5, and a one-sided area of 0.0045 corresponds to t=-3.0. Based on this test, the most appropriate conclusion is\nA. t is about -3.00 and the two-sided p-value is about 0.009, so H0 cannot be rejected at α=0.05\nB. t is about -0.75, because the difference of 6 milliliters should be divided directly by the standard deviation of 8 milliliters\nC. t is about -3.00 and the one-sided p-value is about 0.0045, so H0 is rejected and the content is judged to be too low\nD. t is about -3.00 and the one-sided p-value is about 0.0045, showing that the probability that the content is too low is 0.45%", back: "Answer: C\nExplanation: t equals (494-500) divided by (8 divided by 4), which is -6 divided by 2, equal to -3.0; the alternative is one-sided, and with df=15 the one-sided p-value of about 0.0045 is less than 0.05, so H0 is rejected and the mean content is judged to be too low, and C is correct; 0.009 is the two-sided p-value and the direction is wrong, dividing 6 by 8 omits the division by the square root of the sample size, and the p-value is not the probability of the event that the mean content is too low\n\nCorrect option: t is about -3.00 and the one-sided p-value is about 0.0045, so H0 is rejected and the content is judged to be too low", src: "4f2940cbeecb" },
  "stats-scenario-043": { front: "A factory tests H0: the new process has not lowered the defect rate (the defect rate is still 8%) against Ha: the defect rate is lower than 8%, taking α=0.05. If the true defect rate is 5%, the power of this test is 0.80. The most appropriate statement about the two types of error and the power of this test is\nA. Because the power is 0.80, the probability that the new process is truly effective is exactly 0.80, regardless of the sample\nB. If the new process is ineffective, the probability of wrongly concluding that it is effective is 0.20; if the true rate is 5%, the probability of failing to detect this is 0.05\nC. As long as the sample size keeps increasing, the probabilities of both types of error can be reduced to zero, making the power equal to 1\nD. If the new process is ineffective, the probability of wrongly concluding that it is effective is 0.05; if the true rate is 5%, failing to detect this has probability 0.20", back: "Answer: D\nExplanation: α=0.05 is the probability of wrongly concluding that the process is effective when H0 is true, that is, the Type I error probability; a power of 0.80 is the probability of correctly rejecting when the alternative holds, so the Type II error probability is 1-0.80=0.20, and D is correct; power is not the probability that the new process is effective, the two numbers 0.20 and 0.05 have been swapped, and increasing the sample size can only reduce the Type II error rather than reducing both types of error to zero\n\nCorrect option: If the new process is ineffective, the probability of wrongly concluding that it is effective is 0.05; if the true rate is 5%, failing to detect this has probability 0.20", src: "cc277587d2da" },
  "stats-scenario-044": { front: "A company ran a randomized experiment with 200000 users to compare the order rates of two interface designs: 12.2% for the old interface and 12.5% for the new one, with a p-value of 0.002 for the test and α=0.05. The development cost required for the redesign is far higher than the benefit brought by 0.3 percentage points. The most appropriate interpretation of this result is\nA. Because the p-value is only 0.002, this difference certainly has practical significance, and the company should redesign immediately\nB. The difference is statistically significant, but whether the redesign is worthwhile also depends on the actual size of the difference and the cost of the redesign\nC. Because the difference is only 0.3 percentage points, this statistical significance must mean that an error occurred in the calculation\nD. A large sample makes the p-value very small, so the conclusions of such large-sample tests have no value at all", back: "Answer: B\nExplanation: A p-value less than α shows only that the difference is unlikely to be caused by random fluctuation; with a very large sample even a very small difference will be significant, and whether it has practical significance also depends on the size of the difference and on the benefits and costs, so B is correct; statistical significance is not the same as practical significance, a small difference does not mean a calculation error, and a large-sample test still provides evidence about whether an effect exists\n\nCorrect option: The difference is statistically significant, but whether the redesign is worthwhile also depends on the actual size of the difference and the cost of the redesign", src: "96dd9564b3ee" },
  "stats-scenario-045": { front: "A school surveyed 300 students about their favorite type of lunch; the counts for the four types are 90, 85, 65, and 60 in that order, and the school claims that the four types are equally popular. It is known that with df=3 a chi-square value of 7.81 corresponds to a right-tail area of 0.05 and 9.35 corresponds to a right-tail area of 0.025. The conclusion of this goodness-of-fit test is\nA. The expected counts are all 75, χ² is about 8.67, and the p-value is between 0.025 and 0.05, so the school's claim is rejected\nB. The expected counts are all 75, χ² is about 8.67, df should be 4, and the p-value is greater than 0.05, so the school's claim cannot be rejected\nC. The expected counts are all 75, χ² is about 8.67, and the p-value is about 0.017, because χ² should be divided by 2 before the table is used\nD. The expected counts should be taken as the observed count of each type, such as 90, and χ² is about 0.029, showing that the counts for the four types agree with the school's claim", back: "Answer: A\nExplanation: The expected count for each type is 300 divided by 4, which equals 75, and χ²=(90-75)²/75+(85-75)²/75+(60-75)²/75+(60-75)²/75=3+1.33+3+3, about 8.67, with df=4-1=3; 8.67 falls between 7.81 and 9.35, so the p-value is between 0.025 and 0.05, and the null hypothesis that the four types are the same is rejected, so A is correct; the degrees of freedom of a chi-square goodness-of-fit test is the number of categories minus 1 rather than 4, dividing χ² by 2 has no basis, and the expected counts should be computed from the total multiplied by the hypothesized proportions rather than taken directly as the observed count of some type\n\nCorrect option: The expected counts are all 75, χ² is about 8.67, and the p-value is between 0.025 and 0.05, so the school's claim is rejected", src: "7239be9a9592" },
  "stats-scenario-046": { front: "A study randomly surveyed 200 residents in each of two cities about whether they support a certain policy: in city A, 120 support it and 80 oppose it; in city B, 90 support it and 110 oppose it. It is known that with df=1 a chi-square value of 3.84 corresponds to a right-tail area of 0.05 and 6.63 corresponds to a right-tail area of 0.01. The most appropriate statement about this test is\nA. The expected count of supporters in city A is 100, χ² is about 8.00, and the p-value is greater than 0.01, so the null hypothesis cannot be rejected\nB. The expected count of supporters in city A is 105, χ² is about 9.02, df should be 3, and the p-value is between 0.01 and 0.05\nC. The expected count of supporters in city A is 105, χ² is about 9.02, and the p-value is about 0.0027, showing that the probability that the support rates are the same is 0.27%\nD. The expected count of supporters in city A is 105, χ² is about 9.02, and the p-value is less than 0.01, so the hypothesis that the two cities have the same support rate is rejected", back: "Answer: D\nExplanation: The expected count of supporters in city A is 200 times 210 divided by 400, which equals 105, and χ²=2 times (15²/105)+2 times (15²/95), about 9.02, with df=(2-1)(2-1)=1; the p-value of about 0.0027 is less than 0.01, so the hypothesis that the two cities have the same support rate is rejected, and D is correct; expected counts are obtained by multiplying the row total by the column total and dividing by the grand total rather than by simply averaging the numbers of people in the two cities, the degrees of freedom of a 2×2 table is 1 rather than 3, and 0.0027 is a p-value rather than the probability that the support rates are the same\n\nCorrect option: The expected count of supporters in city A is 105, χ² is about 9.02, and the p-value is less than 0.01, so the hypothesis that the two cities have the same support rate is rejected", src: "eb1a02a32a22" },
  "stats-scenario-047": { front: "A company uses advertising spending x (ten-thousand yuan) to predict monthly sales y (ten-thousand yuan) and obtains ŷ=40+3.5x, with x in the data ranging from 2 to 10 ten-thousand yuan, r²=0.86, and no obvious curvature in the residual plot. In one month the spending was 6 ten-thousand yuan and the actual sales were 68 ten-thousand yuan. The most appropriate statement about this month's data and the use of the model is\nA. The predicted value is 61 ten-thousand yuan and the residual is -7 ten-thousand yuan, showing that the actual value is below the model's predicted value\nB. The predicted value is 68 ten-thousand yuan and the residual is 7 ten-thousand yuan, because the residual is the difference between actual sales and spending\nC. The predicted value is 61 ten-thousand yuan and the residual is +7 ten-thousand yuan; if x=20 is used for prediction, that is extrapolation and is not reliable\nD. The predicted value is 61 ten-thousand yuan and the residual is +7 ten-thousand yuan; and because r² is fairly large, predicting with x=20 is equally reliable", back: "Answer: C\nExplanation: ŷ=40+3.5 times 6=61 ten-thousand yuan, and the residual is 68-61=+7 ten-thousand yuan, showing that the actual sales in that month were higher than the prediction; but x in the data lies only between 2 and 10, so taking x=20 is extrapolation, and the regression relationship need not hold outside the range of the data, so C is correct; the residual is positive 7 rather than negative 7, the residual is the actual value minus the predicted value rather than the difference between the actual value and the spending, and a large r² only shows a good fit within the range and cannot make extrapolation reliable\n\nCorrect option: The predicted value is 61 ten-thousand yuan and the residual is +7 ten-thousand yuan; if x=20 is used for prediction, that is extrapolation and is not reliable", src: "55b3ecb44a9c" },
  "stats-scenario-048": { front: "A restaurant chain uses store area x (hundred square meters) to predict monthly revenue y (ten-thousand yuan), and the output is an intercept of 6.9, a slope of 8.3, r=0.79, and r²=0.624. One old store has an area of only 3 hundred square meters and monthly revenue of only 5 ten-thousand yuan (the remaining stores have areas between 6 and 12), and after removing this store the slope becomes 6.1 and r² becomes 0.43. The most appropriate statement about these results is\nA. The slope of 8.3 means that for each additional 1 hundred square meters of area monthly revenue rises by an average of 8.3 ten-thousand yuan, and this store has a fairly large influence\nB. r²=0.624 means that for each 1-unit increase in store area, revenue rises by an average of about 0.624 ten-thousand yuan\nC. r=0.79 means that store area can explain 79% of the variation in revenue, and the rest comes from other factors\nD. Because this store has the lowest revenue and removing it can increase r², this store should simply be deleted in the analysis", back: "Answer: A\nExplanation: The slope of 8.3 means that for each additional 1 hundred square meters of store area monthly revenue rises by an average of 8.3 ten-thousand yuan, and this store lies at the low end of x and clearly below the overall trend; after removing it the slope falls from 8.3 to 6.1 and r² from 0.624 to 0.43, showing that it has a fairly large influence on the regression and should be reported and checked, so A is correct; r² is the proportion of variation explained rather than the percentage by which revenue rises, r equal to 0.79 does not mean that 79% of the variation can be explained, low revenue does not show that these are erroneous data, and it is precisely this store that raised r² from 0.43 to 0.624, so deleting it lowers r² instead, and deleting it at will would conceal its influence on the regression\n\nCorrect option: The slope of 8.3 means that for each additional 1 hundred square meters of area monthly revenue rises by an average of 8.3 ten-thousand yuan, and this store has a fairly large influence", src: "34e8efa7e337" },
  "stats-scenario-049": { front: "In a bacterial culture experiment, time t (hours) and the number of bacteria y (count) were recorded, and y grows faster and faster over time. After taking the natural logarithm of y, the scatterplot of log y against t is approximately a straight line, with regression equation log ŷ=2.10+0.35t and r²=0.98, whereas a plot of log y against log t is still clearly curved. The most appropriate statement about this model is\nA. A power model should be used instead, because taking the logarithm of both variables at the same time is always enough to turn the scatterplot into a straight line\nB. For each 1-hour increase in t, y becomes about e^0.35≈1.42 times its original value, that is, approximately exponential growth\nC. The 0.35 in the equation shows that for each 1-hour increase in t, y increases by an average of 0.35\nD. The r² of log y against t is 0.98, showing that the correlation coefficient between y and t is also about 0.98", back: "Answer: B\nExplanation: That log y against t is a straight line shows that y and t approximately satisfy the exponential relationship y approximately equal to e^2.10 times e^0.35t; for each 1-hour increase in t, y becomes e^0.35, about 1.42 times its original value, so B is correct; that log y against log t is still curved shows that this is not a power model, the 0.35 in the straight-line equation is the increment of log y rather than the increment of y, and the r² of log y against t cannot be taken as the correlation coefficient between y and t\n\nCorrect option: For each 1-hour increase in t, y becomes about e^0.35≈1.42 times its original value, that is, approximately exponential growth", src: "688b40552a6e" },
  "stats-scenario-050": { front: "A researcher wants to test whether the proportion of women among the customers of a coffee shop is 0.5. In the actual sample of 40 people there are 26 women, giving a sample proportion p̂=0.65. Under the condition p=0.5, 1000 samples of size 40 were simulated, of which 63 had p̂ at least 0.65 and 55 had p̂ at most 0.35. Based on this simulation result, the most appropriate conclusion is\nA. The simulated p-value is about 0.063, which is less than 0.05, so there is evidence that the proportion of women is not 0.5\nB. The simulated p-value is about 0.118, showing that the probability that the proportion of women is 0.5 is about 11.8%\nC. The mean of p̂ in the simulation is about 0.65, because the simulation was carried out under the observed sample proportion of 0.65\nD. The simulated p-value is about 0.118, which is greater than 0.05, so there is not enough evidence to conclude that the proportion of women is not 0.5", back: "Answer: D\nExplanation: The sum of the extreme proportions on the two sides in the simulation is (63+55)/1000=0.118, which is greater than 0.05, so there is not enough evidence to reject p=0.5, and D is correct; 0.063 counts only one side, the p-value is the probability of obtaining the current or a more extreme result when H0 is true rather than the probability that H0 is true, the simulation was carried out under the condition p=0.5, and the mean of p̂ in the simulation should be about 0.5 rather than 0.65\n\nCorrect option: The simulated p-value is about 0.118, which is greater than 0.05, so there is not enough evidence to conclude that the proportion of women is not 0.5", src: "c13ae159eb6f" },
  "calcbc-scenario-001": { front: "The deviation function of an oscillating system is D(x)=(sin 3x−3x)/x³ (x is in radians, x≠0). Find lim(x→0) D(x).\nA. -3/2\nB. -1/2\nC. -9/2\nD. -27/2", back: "Answer: C\nExplanation: Expand using sin u=u−u³/6 and take u=3x to get sin 3x=3x−27x³/6, so D(x)→−27/6=−9/2\n\nCorrect option: -9/2", src: "02ce2668f076" },
  "calcbc-scenario-002": { front: "Let f(x)=(1−cos 2x)/x² (x≠0), and define f(0)=k. If f is differentiable at x=0, then k and f'(0) are, respectively\nA. k=2, f'(0)=2\nB. k=2, f'(0)=1\nC. k=2, f'(0) does not exist\nD. k=2, f'(0)=0", back: "Answer: D\nExplanation: Since 1−cos 2x≈2x², k=2; then by the definition of the derivative, f'(0)=lim(x→0)[(1−cos 2x)/x²−2]/x=lim(x→0)(−2x/3)=0\n\nCorrect option: k=2, f'(0)=0", src: "f3908fd3aa6a" },
  "calcbc-scenario-003": { front: "A particle has displacement s(t) meters at time t seconds, and it is known that s(2)=3 and s'(2)=1 meter per second. Find the value of lim(h→0)[s(2+3h)−s(2−h)]/h.\nA. 3 meters per second\nB. 4 meters per second\nC. 2 meters per second\nD. -4 meters per second", back: "Answer: B\nExplanation: Split the expression as 3·[s(2+3h)−s(2)]/(3h)+[s(2)−s(2−h)]/h; the two parts approach 3s'(2) and s'(2) respectively, giving 4 meters per second in total\n\nCorrect option: 4 meters per second", src: "bc3b943f688d" },
  "calcbc-scenario-004": { front: "The reading of a sensor at x is R(x)=x(√(x²+4)−x) (unit: volts). Find lim(x→∞) R(x).\nA. 4 volts\nB. 1 volt\nC. 2 volts\nD. -2 volts", back: "Answer: C\nExplanation: Rationalizing gives R(x)=4x/(√(x²+4)+x); dividing numerator and denominator by x gives 4/(√(1+4/x²)+1)→2 volts\n\nCorrect option: 2 volts", src: "c0dec3e7a24d" },
  "calcbc-scenario-005": { front: "Let f(x)=x²sin(1/x) (x≠0) and f(0)=0. Regarding the continuity and differentiability of f at x=0, the correct statement is\nA. f is differentiable at 0, and f'(0)=1\nB. f is continuous at 0, but f'(0) does not exist\nC. f is not continuous at 0, because sin(1/x) oscillates\nD. f is differentiable at 0, and f'(0)=0", back: "Answer: D\nExplanation: Since |f(x)|≤x², f is continuous at 0; also f'(0)=lim(x→0)x sin(1/x)=0 (a bounded quantity times an infinitesimal\n\nCorrect option: f is differentiable at 0, and f'(0)=0", src: "a4b887b644de" },
  "calcbc-scenario-006": { front: "The radius of a circular oil slick increases at a rate of 2 cm/s. When the radius is r=10 cm, what is the instantaneous rate of change dA/dt of the area of the oil slick?\nA. 40π cm²/s\nB. 20π cm²/s\nC. 80π cm²/s\nD. 400π cm²/s", back: "Answer: A\nExplanation: A=πr²; differentiating with respect to t gives dA/dt=2πr·dr/dt=2π×10×2=40π, with units cm²/s\n\nCorrect option: 40π cm²/s", src: "6c293d88c628" },
  "calcbc-scenario-007": { front: "A particle moves along a straight line with velocity v(t)=t²−4t+5 (meters per second), where 0≤t≤5. Find the minimum velocity during this time interval.\nA. 1 meter per second\nB. 5 meters per second\nC. 10 meters per second\nD. 0 meters per second", back: "Answer: A\nExplanation: v'(t)=2t−4=0 gives t=2, and v(2)=1; comparing with the endpoint values v(0)=5 and v(5)=10, the minimum value is 1 meter per second\n\nCorrect option: 1 meter per second", src: "1af5f0408ae3" },
  "calcbc-scenario-008": { front: "The function f(x)=x² satisfies the conditions of the Mean Value Theorem on the closed interval [0,3]. The value c∈(0,3) guaranteed by the Mean Value Theorem is\nA. c=3.0\nB. c=4.5\nC. c=3/2\nD. c=-1.5", back: "Answer: C\nExplanation: The average rate of change is (9−0)/(3−0)=3; setting f'(c)=2c=3 gives c=3/2, and 3/2∈(0,3)\n\nCorrect option: c=3/2", src: "63cc3f730662" },
  "calcbc-scenario-009": { front: "A fence of total length 24 meters is used against a sufficiently long wall to enclose a rectangular pen (the wall serves as one side, so no fence is needed there). What is the largest area that can be enclosed?\nA. 144 square meters\nB. 12 square meters\nC. 72 square meters\nD. 36 square meters", back: "Answer: C\nExplanation: Let the side perpendicular to the wall be x; then the other side is 24−2x, A=x(24−2x), and A'=24−4x=0 gives x=6, the other side is 12, and the maximum area is 72 square meters\n\nCorrect option: 72 square meters", src: "7bd43b0e7204" },
  "calcbc-scenario-010": { front: "A ladder 5 meters long leans against a vertical wall, and its bottom slides away from the wall along the ground at a rate of 1 meter per second. When the bottom is 3 meters from the wall, what is the speed at which the top of the ladder slides down?\nA. -0.75 meters per second\nB. 0.75 meters per second\nC. 1.33 meters per second\nD. 0.5 meters per second", back: "Answer: B\nExplanation: x²+y²=25; differentiating gives 2x·dx/dt+2y·dy/dt=0, and y=4 when x=3, so dy/dt=−(x/y)·dx/dt=−3/4, and the speed of downward sliding is 0.75 meters per second\n\nCorrect option: 0.75 meters per second", src: "290f7eda5a88" },
  "calcbc-scenario-011": { front: "What is the area of the region enclosed by the curve y=x² and the line y=6x?\nA. 36 square units\nB. 72 square units\nC. 108 square units\nD. 180 square units", back: "Answer: A\nExplanation: The intersection points are x=0 and x=6; area=∫_0^6 (6x−x²)dx=3x²−x³/3 evaluated from 0 to 6=108−72=36 square units\n\nCorrect option: 36 square units", src: "a05ae7c26848" },
  "calcbc-scenario-012": { front: "The region enclosed by y=x, y=0, and x=3 is revolved about the x-axis. What is the volume of the resulting solid of revolution?\nA. 27π cubic units\nB. 9 cubic units\nC. 9π cubic units\nD. 27 cubic units", back: "Answer: C\nExplanation: V=π∫_0^3 x² dx=π·[x³/3]_0^3=9π cubic units\n\nCorrect option: 9π cubic units", src: "a2ebcb6ad3d8" },
  "calcbc-scenario-013": { front: "An object moves along a straight line during 0≤t≤9 seconds with velocity v(t)=t² (meters per second). Find the average velocity during this time interval.\nA. 243 meters per second\nB. 40.5 meters per second\nC. 81 meters per second\nD. 27 meters per second", back: "Answer: D\nExplanation: Average velocity=(1/9)∫_0^9 t² dt=(1/9)·243=27 meters per second\n\nCorrect option: 27 meters per second", src: "bd1c8175d252" },
  "calcbc-scenario-014": { front: "Find the value of the definite integral ∫_1^e ln x dx.\nA. The value of the integral is e\nB. The value of the integral is e-1\nC. The value of the integral is 1\nD. The value of the integral is 0", back: "Answer: C\nExplanation: Taking u=ln x and dv=dx, integration by parts gives [x ln x − x]_1^e=(e−e)−(0−1)=1\n\nCorrect option: The value of the integral is 1", src: "8681fbaab89c" },
  "calcbc-scenario-015": { front: "Use substitution to find the value of the definite integral ∫_1^2 (2x+1)³ dx.\nA. The value of the integral is 68\nB. The value of the integral is 136\nC. The value of the integral is 544\nD. The value of the integral is 272", back: "Answer: A\nExplanation: Let u=2x+1, du=2dx; the integral becomes (1/2)∫_3^5 u³ du=(1/8)(625−81)=68\n\nCorrect option: The value of the integral is 68", src: "6fc790acdf69" },
  "calcbc-scenario-016": { front: "Find the sum of the geometric series Σ_{n=1}^∞ (2/3)ⁿ.\nA. The sum of the series is 3\nB. The sum of the series is 2\nC. The sum of the series is 2/3\nD. The sum of the series is 6", back: "Answer: B\nExplanation: The first term is a=2/3 and the common ratio is r=2/3, with |r|<1, so the sum=a/(1−r)=(2/3)/(1/3)=2\n\nCorrect option: The sum of the series is 2", src: "5736f0ff6e5d" },
  "calcbc-scenario-017": { front: "For the series Σ_{n=1}^∞ 1/(n²+1), which of the following statements is correct?\nA. Diverges, because the limit of the ratio is 1\nB. Converges, and the ratio test is inconclusive\nC. Converges, because the limit of the ratio is less than 1\nD. Diverges, because the terms do not approach 0", back: "Answer: B\nExplanation: The limit of the ratio is lim (n²+1)/((n+1)²+1)=1, so the ratio test is inconclusive; further, 1/(n²+1)<1/n² and Σ1/n² converges, so the series converges\n\nCorrect option: Converges, and the ratio test is inconclusive", src: "99807688fce4" },
  "calcbc-scenario-018": { front: "The coefficient of the x⁴ term in the Maclaurin series of the function f(x)=e^(−x²) is\nA. The coefficient of x⁴ is -1/2\nB. The coefficient of x⁴ is 1/2\nC. The coefficient of x⁴ is 1\nD. The coefficient of x⁴ is 1/4", back: "Answer: B\nExplanation: From e^u=Σ uⁿ/n!, taking u=−x² and n=2 gives (−x²)²/2!=x⁴/2, so the coefficient of the x⁴ term is 1/2\n\nCorrect option: The coefficient of x⁴ is 1/2", src: "b854db7f97ec" },
  "calcbc-scenario-019": { front: "The interval of convergence of the power series Σ_{n=1}^∞ (x−2)ⁿ/(n·3ⁿ) is\nA. (-1,5)\nB. [-1,5)\nC. (-1,5]\nD. (-∞, +∞)", back: "Answer: B\nExplanation: By the ratio test, |x−2|/3<1 gives a radius of convergence of 3, that is, −1<x<5; at x=−1 the series Σ(−1)ⁿ/n converges, and at x=5 the series Σ1/n diverges, so the interval is [−1,5)\n\nCorrect option: [-1,5)", src: "17de775e5f24" },
  "calcbc-scenario-020": { front: "The convergence of the series Σ_{n=1}^∞ (−1)^(n+1)/√n is\nA. Conditionally convergent, since the series of absolute values diverges\nB. Absolutely convergent, because Σ1/√n converges\nC. Divergent, because the terms do not approach 0\nD. Divergent, because p=1/2 is less than 1", back: "Answer: A\nExplanation: By the Alternating Series Test, the terms decrease to 0, so the alternating series converges; the series of absolute values Σ1/√n is a p-series with p=1/2<1 and diverges, so the series is conditionally convergent\n\nCorrect option: Conditionally convergent, since the series of absolute values diverges", src: "e721d8448753" },
  "calcbc-scenario-021": { front: "The number of bacteria P(t) in a culture satisfies dP/dt=0.3P (t measured in hours), with initial value P(0)=20. Find the approximate number of bacteria after 2 hours (rounded to an integer).\nA. 36 bacteria\nB. 32 bacteria\nC. 26 bacteria\nD. 364 bacteria", back: "Answer: A\nExplanation: Separating variables gives P(t)=20e^(0.3t), so P(2)=20e^0.6≈20×1.822≈36.4, which rounds to 36 bacteria\n\nCorrect option: 36 bacteria", src: "34f5227d77ad" },
  "calcbc-scenario-022": { front: "Given dy/dx=2xy and y(0)=3, the expression for y in terms of x is\nA. y=3e^(2x)\nB. y=e^(x²)+3\nC. y=3e^(x²+1)\nD. y=3e^(x²)", back: "Answer: D\nExplanation: Separating variables gives dy/y=2x dx; integrating gives ln|y|=x²+C, that is, y=Ce^(x²); from y(0)=3 we get C=3, so y=3e^(x²)\n\nCorrect option: y=3e^(x²)", src: "55e584bea8c2" },
  "calcbc-scenario-023": { front: "A curve is given by the parametric equations x=t²+1, y=t³−3t. Find the value of dy/dx at t=2.\nA. 9/2\nB. 4/9\nC. 15/4\nD. 9/4", back: "Answer: D\nExplanation: dy/dx=(dy/dt)/(dx/dt)=(3t²−3)/(2t); substituting t=2 gives (12−3)/4=9/4\n\nCorrect option: 9/4", src: "26bc24523065" },
  "calcbc-scenario-024": { front: "What is the area of the region enclosed by the polar curve r=2cos θ?\nA. The area of the region is π\nB. The area of the region is 2π\nC. The area of the region is 4π\nD. The area of the region is π/2", back: "Answer: A\nExplanation: When r≥0, θ∈[0,π]; area=(1/2)∫_0^π (2cos θ)² dθ=2∫_0^π cos²θ dθ=2·(π/2)=π\n\nCorrect option: The area of the region is π", src: "0a59e078a00a" },
  "calcbc-scenario-025": { front: "What is the approximate arc length of the curve y=(2/3)x^(3/2) on 0≤x≤3?\nA. 5.33 meters\nB. 3.46 meters\nC. 4.67 meters\nD. 10.67 meters", back: "Answer: C\nExplanation: y'=x^(1/2), 1+(y')²=1+x, arc length=∫_0^3 √(1+x) dx=(2/3)(8−1)=14/3≈4.67 meters\n\nCorrect option: 4.67 meters", src: "a2fa8f520286" },
  "calcbc-scenario-026": { front: "The flow rate of a fluid in a pipe (liters per second) varies with time: when 0 ≤ t < 3, F(t) = (t² − 9)/(t − 3), and when t ≥ 3, F(t) = 12 − 2t. Find lim(t→3⁻) F(t).\nA. 6 liters per second\nB. 9 liters per second\nC. 0 liters per second\nD. The limit does not exist", back: "Answer: A\nExplanation: For the branch 0 ≤ t < 3, factor first: (t² − 9)/(t − 3) = t + 3, so lim(t→3⁻) F(t) = 6 liters per second; B is the 9 obtained by not canceling and substituting t = 3 only into the t² in the numerator (ignoring the −9), C sees the numerator and the denominator both approaching 0 and wrongly concludes that the limit is 0, and D confuses \"the denominator approaches 0\" with \"the limit does not exist\", whereas the left-hand limit does exist after canceling.\n\nCorrect option: 6 liters per second", src: "acd615699320" },
  "calcbc-scenario-027": { front: "The output voltage of a sensor at distance x meters (x > 0) is R(x) = √(4x² + 5x) − 2x (volts). Find lim(x→∞) R(x).\nA. 5/8 volts\nB. 5/6 volts\nC. 5/16 volts\nD. 5/4 volts", back: "Answer: D\nExplanation: Rationalizing gives R(x) = 5x/(√(4x² + 5x) + 2x), and dividing numerator and denominator by x gives 5/(√(4 + 5/x) + 2) → 5/4 volts; A counts both radical terms in the denominator as 4x and writes 8x, B omits the square root and approximates √(4x² + 5x) as 4x to get 5/6, and D multiplies the coefficient 4 into the 4x of the denominator again to get 5/16.\n\nCorrect option: 5/4 volts", src: "bcaae3fd82bd" },
  "calcbc-scenario-028": { front: "Let f satisfy f(x) = x² + a when x < 1 and f(x) = bx + 3 when x ≥ 1. If f is differentiable at x = 1, the values of the constants a and b are\nA. a = 4, b = 2\nB. a = 2, b = 4\nC. a = 3, b = 3\nD. There are no constants a and b satisfying the conditions", back: "Answer: A\nExplanation: Differentiable implies continuous: 1 + a = b + 3; differentiability also requires the left-hand derivative 2 to equal the right-hand derivative b, so b = 2 and a = 4; A satisfies only continuity and wrongly takes b = 4, C takes a = b so that the left-hand derivative 2 ≠ the right-hand derivative 3 and f is not differentiable, and D is wrong because when b = 2 the two one-sided derivatives are exactly equal.\n\nCorrect option: a = 4, b = 2", src: "ea909e6695b1" },
  "calcbc-scenario-029": { front: "Let f be continuous on [1,5] and differentiable on (1,5), with f(1) = 3 and f(5) = 11. Which of the following conclusions must hold?\nA. There is a unique c∈(1,5) such that f(c) = 7\nB. There exists c∈(1,5) such that f'(c) = 8\nC. There exists c∈(1,5) such that f'(c) = 0\nD. There exists c∈(1,5) such that f'(c) = 2", back: "Answer: D\nExplanation: f satisfies the conditions of the Mean Value Theorem, so there exists c∈(1,5) such that f'(c) = (11 − 3)/(5 − 1) = 2; A mistakes the \"existence\" of the Intermediate Value Theorem for \"uniqueness\" (f may attain 7 more than once), B miscomputes the average rate of change as 8, and C is the conclusion of Rolle's Theorem, but the endpoint values 3 ≠ 11 make f'(c) = 0 impossible to guarantee.\n\nCorrect option: There exists c∈(1,5) such that f'(c) = 2", src: "2982f30f2c3a" },
  "calcbc-scenario-030": { front: "After a drug is taken orally, the drug concentration in the blood (mg/L) within t hours satisfies C(t) = 50t/(t² + 4). Find the instantaneous rate of change of the concentration C'(1) at t = 1 hour.\nA. 8 mg/(L·h)\nB. 6 mg/(L·h)\nC. 10 mg/(L·h)\nD. 12 mg/(L·h)", back: "Answer: B\nExplanation: Quotient rule: C'(t) = [50(t² + 4) − 50t·2t]/(t² + 4)² = 50(4 − t²)/(t² + 4)², and at t = 1 this gives 150/25 = 6 mg/(L·h); A miswrites the denominator as t + 4 (dropping the square) to get 200/25 = 8, C differentiates only the numerator (treating the denominator as constant) to get 50/5 = 10, and D miscomputes 50(4 − t²) in the numerator as 60 to get 12.\n\nCorrect option: 6 mg/(L·h)", src: "a82d69161908" },
  "calcbc-scenario-031": { front: "In an inverted conical water tank, the water surface radius r and the water depth h satisfy r = h/3 (meters). Water is injected at a constant rate, and the water depth increases at 0.5 meters per minute. When h = 6 meters, what is the rate of increase of the volume of water dV/dt?\nA. 2π m³/min\nB. 4π m³/min\nC. 6π m³/min\nD. 18π m³/min", back: "Answer: A\nExplanation: From r = h/3 we get V = (1/3)πr²h = (1/3)π(h²/9)h = πh³/27, so dV/dt = (πh²/9)·(dh/dt) = (36π/9)(0.5) = 2π m³/min; A forgets to multiply by dh/dt and takes dV/dh = 4π directly as dV/dt, B misremembers r² = h²/9 as h²/3 so that dV/dh = 12π and then multiplies by 0.5 to get 6π, and D ignores the ratio r = h/3 and uses r = h, giving πh²·0.5 = 18π.\n\nCorrect option: 2π m³/min", src: "b9ddc5813f57" },
  "calcbc-scenario-032": { front: "Let f be continuous on [0,6] and twice differentiable on (0,6). It is known that f'(2) = 0, that f' > 0 on (0,2), that f' < 0 on (2,6), and that f'' < 0 on all of (0,6). Which of the following statements is correct?\nA. f has a local maximum at x = 2\nB. f has a local minimum at x = 2\nC. f has an inflection point of its graph at x = 2\nD. The graph of f is concave up on (0,6)", back: "Answer: A\nExplanation: f' is positive to the left of x = 2 and negative to the right, so x = 2 is a maximum point, and f'' < 0 shows that the graph is concave down, which is consistent with the conclusion; B misjudges \"changing from positive to negative\" as a minimum, C requires f'' to change sign at an inflection point, but f'' is negative throughout (0,6) and the concavity does not change, and D misreads f'' < 0 as the graph being concave up (it is actually concave down).\n\nCorrect option: f has a local maximum at x = 2", src: "b05e9b8ec6e9" },
  "calcbc-scenario-033": { front: "A lidless rectangular water tank is made from sheet metal, with a square base and a volume of 500 cubic meters. Let the side of the base be x meters and the height be h meters. Find the minimum surface area of material required.\nA. 315 square meters\nB. 200 square meters\nC. 1000 square meters\nD. 300 square meters", back: "Answer: D\nExplanation: Let the side of the base be x; then h = 500/x² and the surface area is S = x² + 4xh = x² + 2000/x; setting S' = 2x − 2000/x² = 0 gives x = 10 and h = 5, and the minimum surface area is 100 + 200 = 300 square meters; A assumes that \"material is most economical when the side of the base equals the height\" (x = h), and from x³ = 500 gets x ≈ 7.94 and S ≈ 315, B computes only the four side faces 4xh = 200 and omits the base, and C takes the 1000 in the constraint equation directly as the minimum surface area.\n\nCorrect option: 300 square meters", src: "723885e79e58" },
  "calcbc-scenario-034": { front: "The measured radius of a sphere is 5 centimeters, and the measurement error is at most 0.02 centimeters. Use differentials to estimate the maximum possible error in the volume of the sphere computed from this measurement.\nA. 4π cubic centimeters\nB. 0.4π cubic centimeters\nC. 2π cubic centimeters\nD. 20π cubic centimeters", back: "Answer: C\nExplanation: V = (4/3)πr³, dV = 4πr²dr = 4π × 25 × 0.02 = 2π cubic centimeters; A takes the total span of ±0.02 as dr = 0.04 to get 4π, B miswrites the derivative as 4πr (dropping one power) to get 0.4π, and D mistakes dr = 0.02 for 0.2 to get 20π.\n\nCorrect option: 2π cubic centimeters", src: "c64d0331dc12" },
  "calcbc-scenario-035": { front: "The inflow recorded at a reservoir from 0 to 8 hours is as follows: at t = 0, 2, 4, 6, 8 the values of R(t) are 6, 9, 11, 13, 8 (liters per hour). Use the trapezoidal rule with n = 4 to estimate the total inflow, and use it to find the average inflow rate over these 8 hours.\nA. 80 liters per hour\nB. 10 liters per hour\nC. 40 liters per hour\nD. 9.75 liters per hour", back: "Answer: B\nExplanation: Trapezoidal rule: (8/(2×4))[6 + 2(9 + 11 + 13) + 8] = 1 × (6 + 66 + 8) = 80 liters, and dividing by the length of the interval 8 gives an average inflow of 10 liters per hour; A takes 80 liters (the total amount) directly as the average inflow, mixing up the units, C uses the factor 1/2 twice in the trapezoidal formula (dividing 80 by 2 again), and D uses the left-endpoint Riemann sum 2(6 + 9 + 11 + 13) = 78 and divides by 8 to get 9.75.\n\nCorrect option: 10 liters per hour", src: "23056a37eea3" },
  "calcbc-scenario-036": { front: "Let f be a continuous function with f(8) = 5, and define g(x) = ∫_1^(x³) f(t) dt. Find the value of g'(2).\nA. The value of the derivative is 20\nB. The value of the derivative is 15\nC. The value of the derivative is 180\nD. The value of the derivative is 60", back: "Answer: D\nExplanation: Chain rule and the Fundamental Theorem of Calculus: g'(x) = f(x³)·3x², so g'(2) = f(8) × 12 = 5 × 12 = 60; B omits the factor 3 in (x³)' and gets 4 × 5 = 20, C misremembers (x³)' as 3 and gets 3 × 5 = 15, and D multiplies the value 12 of 3x² at x = 2 by 3 once more to get 180.\n\nCorrect option: The value of the derivative is 60", src: "6dbcfc17a79d" },
  "calcbc-scenario-037": { front: "Find the value of the definite integral ∫_0^1 x³ e^(x²) dx (first substitute u = x², then use integration by parts).\nA. The value of the integral is 1/4\nB. The value of the integral is −1/2\nC. The value of the integral is e/2\nD. The value of the integral is 1/2", back: "Answer: D\nExplanation: Let u = x², du = 2x dx; then x³e^(x²)dx = (u/2)e^u du, and integration by parts gives ∫_0^1 = (1/2)[(u − 1)e^u]_0^1 = (1/2)[0 − (−1)] = 1/2; A multiplies by 1/2 once in the substitution and once more in the integration by parts to get 1/4, B reverses the sign of ∫v du in the integration by parts to get −1/2, and C computes only the difference of (1/2)x²e^(x²) at the endpoints (e/2), omitting the subtracted (1/2)∫_0^1 2x e^(x²)dx.\n\nCorrect option: The value of the integral is 1/2", src: "144bab9d04b3" },
  "calcbc-scenario-038": { front: "Find the value of the definite integral ∫_1^2 (2x + 1)/(x(x + 1)) dx (hint: first decompose into partial fractions).\nA. ln 6\nB. ln 3\nC. ln 2\nD. The integral diverges", back: "Answer: B\nExplanation: Partial fractions: (2x + 1)/(x(x + 1)) = 1/x + 1/(x + 1), so the original integral = [ln x + ln(x + 1)]_1^2 = (ln 2 + ln 3) − (0 + ln 2) = ln 3; A substitutes only the upper limit to get ln 6 without subtracting ln 2 at the lower limit, C keeps only the value of ln(x + 1) at x = 1 (omitting the 1/x term), and D wrongly treats an integrand with 1/x on [1,2] as divergent, which is the case for ∫_0^1 1/x dx.\n\nCorrect option: ln 3", src: "2c6ab1800946" },
  "calcbc-scenario-039": { front: "It is known that the improper integral ∫_1^∞ 1/x^k dx converges (k is a constant) and that its value equals 1/2. Find the value of k.\nA. The value of k is 1/2\nB. The value of k is 3/2\nC. The value of k is 3\nD. The value of k is 2", back: "Answer: C\nExplanation: ∫_1^∞ x^(−k)dx converges if and only if k > 1, and in that case its value is 1/(k − 1); from 1/(k − 1) = 1/2 we get k = 3; A remembers the convergence criterion as k < 1 (confusing it with ∫_0^1 1/x^k dx), B makes an error in taking the reciprocal when solving the equation and writes k − 1 = 1/2, and D uses the wrong formula (taking the value of the integral as 1/k) and gets k = 2 from 1/k = 1/2.\n\nCorrect option: The value of k is 3", src: "840254ab797b" },
  "calcbc-scenario-040": { front: "A particle moves along the parametric curve x = t − sin t, y = 1 − cos t (0 ≤ t ≤ 2π, units: meters). Find the arc length of this portion of the curve (one arch).\nA. The arc length is 4 meters\nB. The arc length is 16 meters\nC. The arc length is 4π meters\nD. The arc length is 8 meters", back: "Answer: D\nExplanation: dx/dt = 1 − cos t and dy/dt = sin t, so (dx/dt)² + (dy/dt)² = 2 − 2cos t = 4sin²(t/2), the speed is 2sin(t/2), and the arc length = ∫_0^(2π) 2sin(t/2)dt = 2[−2cos(t/2)]_0^(2π) = 8 meters; A integrates only from 0 to π (half an arch) to get 4, B multiplies the coefficient 2 in the speed by 2 again to get 16, and C omits the square root and integrates 2 − 2cos t directly to get 4π.\n\nCorrect option: The arc length is 8 meters", src: "06bea9066fae" },
  "calcbc-scenario-041": { front: "The curve y = x² and the line y = 2x enclose a region in the first quadrant. Find the area of this region.\nA. 4/3 square units\nB. 8/3 square units\nC. 20/3 square units\nD. 16/3 square units", back: "Answer: A\nExplanation: The intersection points satisfy x² = 2x, that is, x = 0 and x = 2, so the area = ∫_0^2 (2x − x²)dx = [x² − x³/3]_0^2 = 4 − 8/3 = 4/3 square units; B gets the boundary wrong and integrates only y = x² from 0 to 2 to get 8/3, C miswrites the integrand as the sum of the two functions (2x + x²) to get 20/3, and D miswrites the integrand as 2x² (taking 2x as x² as well) to get 16/3.\n\nCorrect option: 4/3 square units", src: "2386b0fd6be5" },
  "calcbc-scenario-042": { front: "The region enclosed by the curve y = √x and y = x is revolved about the x-axis. What is the volume of the resulting solid of revolution?\nA. π/2 cubic units\nB. π/6 cubic units\nC. π/3 cubic units\nD. 2π/3 cubic units", back: "Answer: B\nExplanation: The outer radius is R = √x and the inner radius is r = x, so V = π∫_0^1 [(√x)² − x²]dx = π∫_0^1 (x − x²)dx = π(1/2 − 1/3) = π/6 cubic units; A computes only the disk of the outer radius, π∫_0^1 x dx = π/2, B reverses the inner and outer radii and computes only π∫_0^1 x²dx = π/3, and D writes R² − r² as R² + r² to get 2π/3.\n\nCorrect option: π/6 cubic units", src: "265177ab2b97" },
  "calcbc-scenario-043": { front: "The number of fish in a lake P(t) satisfies the logistic equation dP/dt = 0.2P(1 − P/500), with initial number P(0) = 100 (t in years). Find the time required for the fish population to reach half of the carrying capacity.\nA. 5 ln 4 years\nB. 5 ln 2 years\nC. 10 ln 4 years\nD. 20 ln 4 years", back: "Answer: A\nExplanation: Separating variables gives the solution P(t) = 500/(1 + 4e^(−0.2t)); setting P = 250 gives 1 + 4e^(−0.2t) = 2, that is, e^(−0.2t) = 1/4, so t = ln 4/0.2 = 5ln 4 ≈ 6.93 years; A misreads e^(−0.2t) = 1/4 as 1/2 and gets 5ln 2, C takes k = 0.2 as 0.1 and gets 10ln 4, and D takes k as 0.05 and gets 20ln 4.\n\nCorrect option: 5 ln 4 years", src: "cf3c5a1b0cc3" },
  "calcbc-scenario-044": { front: "Use Euler's method (step size h = 0.5) to find the approximate value at x = 1 of the initial value problem dy/dx = x + y, y(0) = 1.\nA. The approximate value is 2.25\nB. The approximate value is 2.75\nC. The approximate value is 3.0\nD. The approximate value is 2.5", back: "Answer: D\nExplanation: First step: y(0.5) ≈ 1 + 0.5(0 + 1) = 1.5; second step: y(1) ≈ 1.5 + 0.5(0.5 + 1.5) = 1.5 + 1 = 2.5; A omits the contribution of x in the slope during the second step (using only 1.5) to get 2.25, B takes the slope at x = 1 in advance during the second step to get 2.75, and C takes only one step with h = 1 and computes with the slope at the endpoint to get 3.0.\n\nCorrect option: The approximate value is 2.5", src: "83e288518c2f" },
  "calcbc-scenario-045": { front: "Let the sequence be aₙ = (2n + 1)/(n³ + 2). Regarding the convergence of the series Σ_(n=1)^∞ aₙ, which of the following statements is correct?\nA. Diverges (the terms do not approach 0, so it diverges)\nB. Converges (limit comparison with Σ1/n²)\nC. Converges (the limit in the ratio test is 1)\nD. Diverges (it is of the same order as the harmonic series Σ1/n)", back: "Answer: B\nExplanation: aₙ·n² = n²(2n + 1)/(n³ + 2) → 2, and Σ1/n² converges, so by the limit comparison test the original series converges; B, the terms do approach 0, and the nth-term test cannot be used to determine divergence, C, the ratio a_(n+1)/aₙ → 1, so the ratio test fails here and cannot be the basis for convergence, and D, this series is of the same order as 1/n², not of the same order as the harmonic series Σ1/n.\n\nCorrect option: Converges (limit comparison with Σ1/n²)", src: "f94ae13ec374" },
  "calcbc-scenario-046": { front: "The series Σ_(n=1)^∞ (−1)^(n+1)/n⁵ satisfies the conditions of the Alternating Series Test. If the partial sum S₄ of the first 4 terms is used to approximate the sum of the series, then the absolute value of the error certainly does not exceed\nA. 1/6250\nB. 1/3125\nC. 1/7776\nD. 1/16807", back: "Answer: B\nExplanation: When an alternating series satisfies the Leibniz conditions, the error does not exceed the first term omitted; when the first 4 terms are used for the approximation, |error| ≤ a₅ = 1/5⁵ = 1/3125 ≈ 0.00032 (the actual error is about 0.00023); A takes the bound to be half of a₅ (1/6250 ≈ 0.00016), B is off by one term and takes a₆ = 1/7776 ≈ 0.00013, and D is off by two terms and takes a₇ = 1/16807 ≈ 0.00006; all three are smaller than the actual error and cannot serve as a guaranteed upper bound.\n\nCorrect option: 1/3125", src: "9441822e5953" },
  "calcbc-scenario-047": { front: "The interval of convergence of the power series Σ_(n=1)^∞ n(x + 4)ⁿ/7ⁿ (including the determination of whether the endpoints converge) is\nA. (−11,3]\nB. [−11,3]\nC. (−11,3)\nD. [−11,11]", back: "Answer: C\nExplanation: By the ratio test, |x + 4|/7 < 1 gives −11 < x < 3; at the endpoint x = 3 the general term is n, which does not approach 0, and at x = −11 the general term is n(−1)ⁿ, which also does not approach 0, so both endpoints diverge and the interval of convergence is (−11,3); A wrongly judges the series to converge at x = 3, C wrongly applies the Alternating Series Test and believes the series converges at x = −11, and D takes the center to be the origin and the radius to be 7 + 4 = 11, obtaining the symmetric interval [−11,11].\n\nCorrect option: (−11,3)", src: "61e5c28d2351" },
  "calcbc-scenario-048": { front: "Let f(x) = e^x and let its third-degree Taylor polynomial at x = 0 be P₃(x) = 1 + x + x²/2 + x³/6. Use the formula |R₃(0.2)| ≤ M|0.2|⁴/4! (M is the maximum value of |f⁗| on [0, 0.2], and e^(0.2) < 3 may be used) to estimate the value of this error bound.\nA. 0.00007\nB. 0.0016\nC. 0.0048\nD. 0.0002", back: "Answer: D\nExplanation: f⁗(x) = e^x, and on [0, 0.2] we have M = e^(0.2) < 3, so by the Lagrange error bound |R₃(0.2)| ≤ M|0.2|⁴/4! ≤ 3 × 0.0016/24 = 0.0002; A replaces e^(0.2) with M = 1 to get about 0.00007, B both forgets to multiply by M and forgets to divide by 4! (computing only 0.2⁴) to get 0.0016, and C forgets to divide by 4! to get 0.0048.\n\nCorrect option: 0.0002", src: "8d92dfd0f627" },
  "calcbc-scenario-049": { front: "What is the area of the region enclosed by one petal of the polar curve r = 4cos(3θ)?\nA. 4π/3 square units\nB. 2π/3 square units\nC. 8π/3 square units\nD. 16π/3 square units", back: "Answer: A\nExplanation: One petal corresponds to θ∈[−π/6, π/6] (where r ≥ 0), and the area = (1/2)∫_(−π/6)^(π/6) 16cos²(3θ)dθ = 8 × (π/6) = 4π/3 square units; B integrates only over θ∈[0, π/6] (half a petal) to get 2π/3, C omits the 1/2 in the area formula to get 8π/3, and D both omits the 1/2 and takes the interval of integration as [−π/3, π/3] to get 16π/3.\n\nCorrect option: 4π/3 square units", src: "00e8242ec660" },
  "calcbc-scenario-050": { front: "The position vector of a particle in the plane is r(t) = ⟨3t − t³, 3t²⟩ (meters), 0 ≤ t ≤ 5. Find the total distance traveled by the particle during 0 ≤ t ≤ 5.\nA. 133 meters\nB. 140 meters\nC. 6420 meters\nD. 110 meters", back: "Answer: B\nExplanation: v(t) = ⟨3 − 3t², 6t⟩, and the speed = √((3 − 3t²)² + (6t)²) = √(9(1 + t²)²) = 3(1 + t²), so the total distance = ∫_0^5 3(1 + t²)dt = 3(5 + 125/3) = 140 meters; A uses the magnitude of the displacement √((−110)² + 75²) ≈ 133 instead of the total distance, B omits the square root and integrates (dx/dt)² + (dy/dt)² directly to get 6420, and C computes only the magnitude of the displacement in the x direction, 110.\n\nCorrect option: 140 meters", src: "fd8791a56079" },
};
